-- Burns and Skin question bank: exactly 350 hand-written NCLEX-style
-- single-best-answer questions, 50 per note. Every answer is grounded in
-- (and its rationale limited to) the source note listed for its topic:
--   Notes/Burns and Skin/Burns.html
--   Notes/Burns and Skin/Common-Skin-Disorders.html
--   Notes/Burns and Skin/Skin-Conditions-Overview.html
--   Notes/Burns and Skin/Dermatitis-and-Cellulitis.html
--   Notes/Burns and Skin/DVT-vs-Cellulitis.html
--   Notes/Burns and Skin/Periorbital-Cellulitis.html
--   Notes/Burns and Skin/Pressure-Ulcers.html
--
-- Maps each source path through note_catalog.note_id to the published test_topics
-- row(s) for that note (matching test.html's note-level topic grouping). All
-- missing/ambiguous mappings are reported before any deletion or insertion.
-- Safe to rerun: only rows carrying this script's category labels are replaced,
-- and the transaction aborts unless exactly 50 rows per topic (350) exist after insert.
BEGIN;

CREATE TEMP TABLE _burns_sources (
  source_key text PRIMARY KEY,
  source_path text NOT NULL UNIQUE,
  category text NOT NULL UNIQUE
) ON COMMIT DROP;

INSERT INTO _burns_sources (source_key, source_path, category) VALUES
  ('burns', 'Notes/Burns and Skin/Burns.html', 'Burns and Skin NCLEX seed v1 - burns'),
  ('common', 'Notes/Burns and Skin/Common-Skin-Disorders.html', 'Burns and Skin NCLEX seed v1 - common skin disorders'),
  ('overview', 'Notes/Burns and Skin/Skin-Conditions-Overview.html', 'Burns and Skin NCLEX seed v1 - skin conditions overview'),
  ('derm_cellulitis', 'Notes/Burns and Skin/Dermatitis-and-Cellulitis.html', 'Burns and Skin NCLEX seed v1 - dermatitis and cellulitis'),
  ('dvt_cellulitis', 'Notes/Burns and Skin/DVT-vs-Cellulitis.html', 'Burns and Skin NCLEX seed v1 - dvt vs cellulitis'),
  ('periorbital', 'Notes/Burns and Skin/Periorbital-Cellulitis.html', 'Burns and Skin NCLEX seed v1 - periorbital cellulitis'),
  ('pressure', 'Notes/Burns and Skin/Pressure-Ulcers.html', 'Burns and Skin NCLEX seed v1 - pressure ulcers');

CREATE TEMP TABLE _burns_seed_map (
  source_key text PRIMARY KEY,
  source_path text NOT NULL,
  category text NOT NULL,
  note_id uuid NOT NULL,
  note_title text NOT NULL,
  topic_id uuid NOT NULL,
  topic_aliases text[] NOT NULL
) ON COMMIT DROP;

CREATE TEMP TABLE _burns_seed_config (test_id bigint NOT NULL) ON COMMIT DROP;

DO $$
DECLARE
  v_subject_id uuid;
  v_subject_count integer;
  v_note_count integer;
  v_topic_count integer;
  v_note_id uuid;
  v_note_title text;
  v_topic_id uuid;
  v_aliases text[];
  v_test_id bigint;
  v_errors text[] := ARRAY[]::text[];
  r record;
BEGIN
  SELECT count(*)
    INTO v_subject_count
    FROM test_subjects
   WHERE lower(btrim(name)) = 'burns and skin'
     AND is_active = true;
  IF v_subject_count <> 1 THEN
    v_errors := array_append(v_errors,
      format('Expected exactly one active test_subjects row named "Burns and Skin"; found %s.', v_subject_count));
  ELSE
    SELECT id INTO v_subject_id
      FROM test_subjects
     WHERE lower(btrim(name)) = 'burns and skin'
       AND is_active = true;
  END IF;

  SELECT id INTO v_test_id
    FROM tests
   WHERE is_active = true
   ORDER BY id
   LIMIT 1;
  IF v_test_id IS NULL THEN
    v_errors := array_append(v_errors, 'No active tests row is available for test_questions.test_id.');
  END IF;

  FOR r IN SELECT source_key, source_path, category FROM _burns_sources ORDER BY source_key LOOP
    SELECT count(*)
      INTO v_note_count
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_note_count = 0 THEN
      v_errors := array_append(v_errors,
        format('Missing active note_catalog mapping for %s.', r.source_path));
      CONTINUE;
    ELSIF v_note_count > 1 THEN
      v_errors := array_append(v_errors,
        format('Ambiguous active note_catalog mapping for %s (%s rows).', r.source_path, v_note_count));
      CONTINUE;
    END IF;

    SELECT note_id, title
      INTO v_note_id, v_note_title
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_subject_count <> 1 THEN
      v_errors := array_append(v_errors,
        format('Cannot resolve test_topics aliases for %s because the active Burns and Skin subject mapping is not unique.',
               r.source_path));
      CONTINUE;
    END IF;

    SELECT count(*)
      INTO v_topic_count
      FROM test_topics
     WHERE subject_id = v_subject_id
       AND note_id = v_note_id
       AND (status = 'published' OR status IS NULL);

    IF v_topic_count = 0 THEN
      v_errors := array_append(v_errors,
        format('No published test_topics row in Burns and Skin points to note %s (%s).',
               v_note_title, r.source_path));
      CONTINUE;
    END IF;

    -- Sibling topics are expected aliases in test.html's note-level merged row.
    -- Insert all 50 for this source under one deterministic sibling topic_id.
    SELECT t.id
      INTO v_topic_id
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL)
     ORDER BY t.display_order NULLS LAST, t.created_at, t.name, t.id
     LIMIT 1;

    -- Collect the actual underlying aliases for the mapping check/report context.
    SELECT array_agg(t.name ORDER BY t.display_order NULLS LAST, t.name, t.id)
      INTO v_aliases
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL);

    INSERT INTO _burns_seed_map
      (source_key, source_path, category, note_id, note_title, topic_id, topic_aliases)
    VALUES
      (r.source_key, r.source_path, r.category, v_note_id, v_note_title, v_topic_id, v_aliases);
  END LOOP;

  IF cardinality(v_errors) > 0 THEN
    RAISE EXCEPTION E'Burns-Skin seed mapping validation failed before any deletion/insertion:\n - %',
      array_to_string(v_errors, E'\n - ');
  END IF;

  IF (SELECT count(*) FROM _burns_seed_map) <> 7 THEN
    RAISE EXCEPTION 'Internal mapping check failed: expected 7 note mappings, found %.',
      (SELECT count(*) FROM _burns_seed_map);
  END IF;

  INSERT INTO _burns_seed_config (test_id) VALUES (v_test_id);
END $$;

-- Only rows from this script's unique category names are replaced.
DELETE FROM test_questions q
 USING _burns_seed_map m
 WHERE q.category = m.category;

INSERT INTO test_questions
  (test_id, topic_id, question, question_stem, options, correct_answer, rationale,
   category, is_multiple_choice, display_order, points, is_active)
SELECT c.test_id, m.topic_id, v.stem, v.stem, v.options, v.correct_answer, v.rationale,
       m.category, false, v.display_order, 1, true
  FROM (VALUES
  ('burns', 1, 'A client spilled boiling water on the forearm. The nurse notes blisters and a pink, moist wound bed, and the client reports the area is very painful. How should the nurse classify this burn?', '[{"id": "a", "text": "Superficial (first-degree) burn"}, {"id": "b", "text": "Superficial partial-thickness burn"}, {"id": "c", "text": "Deep partial-thickness burn"}, {"id": "d", "text": "Full-thickness (third-degree) burn"}]'::jsonb, '["b"]', 'Blisters with a pink, moist, very painful wound describe a superficial partial-thickness (2nd-degree) burn. A deep partial-thickness burn is pale and white with diminished pain, not pink and very painful.'),
  ('burns', 2, 'A client with a flame burn to the thigh has an area that is leathery, dry, and white. The client does not feel the nurse touching the area. Which burn depth does the nurse document?', '[{"id": "a", "text": "Superficial partial thickness"}, {"id": "b", "text": "Deep partial thickness"}, {"id": "c", "text": "Full thickness (third degree)"}, {"id": "d", "text": "Subdermal (fourth degree)"}]'::jsonb, '["c"]', 'Leathery, dry, black/red/white skin with no pain is a full-thickness (3rd-degree) burn. A 4th-degree burn extends into muscle and bone with charring and exposed bone, which is not described here.'),
  ('burns', 3, 'The nurse is assessing a client with a deep partial-thickness burn of the chest. Which finding does the nurse expect?', '[{"id": "a", "text": "Pink, moist blisters that are very painful"}, {"id": "b", "text": "Charred tissue with exposed bone"}, {"id": "c", "text": "Red, dry skin that blanches without blisters"}, {"id": "d", "text": "Pale, white area with diminished pain"}]'::jsonb, '["d"]', 'A deep partial-thickness burn involves the epidermis and deep dermis and appears pale and white with diminished pain. Pink, moist, very painful blisters describe a superficial partial-thickness burn instead.'),
  ('burns', 4, 'A client sustained a burn that extends into muscle and bone of the lower leg. The tissue is charred and bone is visible. Which outcome does the nurse anticipate the team will discuss with the client?', '[{"id": "a", "text": "Likely amputation of the affected area"}, {"id": "b", "text": "Healing in 1 to 3 weeks without grafting"}, {"id": "c", "text": "Healing in 3 to 7 days without scarring"}, {"id": "d", "text": "Healing with dressing changes alone"}]'::jsonb, '["a"]', 'A 4th-degree (subdermal) burn extends into muscle and bone with charring and exposed bone, and amputation is likely. Healing in 1 to 3 weeks applies to a superficial partial-thickness burn.'),
  ('burns', 5, 'The nurse is reviewing burn assessments for four clients. Which burn will need a skin graft to heal?', '[{"id": "a", "text": "Red, dry burn that blanches when pressed"}, {"id": "b", "text": "Pink, moist burn with intact blisters"}, {"id": "c", "text": "Leathery, dry burn that is painless"}, {"id": "d", "text": "Red, painful burn with no blisters"}]'::jsonb, '["c"]', 'A leathery, dry, painless burn is full thickness (3rd degree), which takes months and needs a graft. Red, dry, blanching burns without blisters are superficial and heal in 3 to 7 days.'),
  ('burns', 6, 'An adult client has burns to the entire right arm and the entire anterior trunk. Using the Rule of Nines, what is the estimated total body surface area (TBSA) burned?', '[{"id": "a", "text": "18%"}, {"id": "b", "text": "27%"}, {"id": "c", "text": "36%"}, {"id": "d", "text": "22.5%"}]'::jsonb, '["b"]', 'In an adult, each arm totals 9% and the anterior trunk is 18%, so 9% + 18% = 27%. Choosing 22.5% wrongly counts only the anterior half (4.5%) of the arm.'),
  ('burns', 7, 'An adult client has burns to the anterior surfaces of both legs and the anterior trunk. Using the Rule of Nines, what is the estimated TBSA burned?', '[{"id": "a", "text": "27%"}, {"id": "b", "text": "45%"}, {"id": "c", "text": "36%"}, {"id": "d", "text": "54%"}]'::jsonb, '["c"]', 'Each adult leg is 18% total with 9% anterior, so both anterior legs equal 18%; adding the anterior trunk (18%) gives 36%. Answering 54% wrongly counts both entire legs.'),
  ('burns', 8, 'An adult client has burns to the entire posterior trunk, the entire left leg, and the perineum. Using the Rule of Nines, what is the estimated TBSA burned?', '[{"id": "a", "text": "37%"}, {"id": "b", "text": "36%"}, {"id": "c", "text": "28%"}, {"id": "d", "text": "46%"}]'::jsonb, '["a"]', 'Posterior trunk (18%) + entire leg (18%) + perineum (1%) = 37%. Answering 36% omits the 1% for the perineum/genitals.'),
  ('burns', 9, 'A child has scald burns to the entire head and neck and the anterior trunk. Using the Rule of Nines adjusted for children, what is the estimated TBSA burned?', '[{"id": "a", "text": "27%"}, {"id": "b", "text": "22.5%"}, {"id": "c", "text": "18%"}, {"id": "d", "text": "36%"}]'::jsonb, '["d"]', 'For children, the head and neck count as 18% and the anterior trunk is 18%, for a total of 36%. Answering 27% uses the adult head and neck value of 9%.'),
  ('burns', 10, 'The nurse is estimating TBSA for a burned child instead of an adult. Which adjustment to the Rule of Nines does the nurse apply?', '[{"id": "a", "text": "Each arm counts as 18% instead of 9%"}, {"id": "b", "text": "Head and neck count as 18% instead of 9%"}, {"id": "c", "text": "Anterior trunk counts as 9% instead of 18%"}, {"id": "d", "text": "Perineum counts as 9% instead of 1%"}]'::jsonb, '["b"]', 'The child''s head and neck are adjusted to 18%, compared with 9% in an adult. Each arm stays 9%, the anterior trunk stays 18%, and the perineum stays 1% in both.'),
  ('burns', 11, 'An adult client who weighs 80 kg has burns over 30% TBSA. Using the Parkland formula, how much fluid should the client receive in the first 24 hours?', '[{"id": "a", "text": "4,800 mL"}, {"id": "b", "text": "7,200 mL"}, {"id": "c", "text": "19,200 mL"}, {"id": "d", "text": "9,600 mL"}]'::jsonb, '["d"]', 'Adult Parkland: 4 mL × 30% × 80 kg = 9,600 mL over 24 hours. 7,200 mL results from wrongly using the child value of 3 mL, and 4,800 mL is only the first-8-hour half.'),
  ('burns', 12, 'An adult client weighing 70 kg has burns over 40% TBSA. Using the Parkland formula, how much fluid should the client receive during the first 8 hours?', '[{"id": "a", "text": "11,200 mL"}, {"id": "b", "text": "5,600 mL"}, {"id": "c", "text": "2,800 mL"}, {"id": "d", "text": "8,400 mL"}]'::jsonb, '["b"]', 'The 24-hour total is 4 mL × 40 × 70 = 11,200 mL, and half (5,600 mL) is given in the first 8 hours. 11,200 mL is the full 24-hour total, not the first-8-hour amount.'),
  ('burns', 13, 'An adult client who weighs 176 lb has burns over 25% TBSA. Using the Parkland formula, what is the total fluid requirement for the first 24 hours?', '[{"id": "a", "text": "17,600 mL"}, {"id": "b", "text": "6,000 mL"}, {"id": "c", "text": "8,000 mL"}, {"id": "d", "text": "4,000 mL"}]'::jsonb, '["c"]', 'Convert first: 176 lb ÷ 2.2 = 80 kg; then 4 mL × 25 × 80 = 8,000 mL. 17,600 mL results from plugging pounds directly into the formula.'),
  ('burns', 14, 'A child who weighs 20 kg has burns over 30% TBSA. Using the Parkland formula for children, how much fluid should the child receive in the first 8 hours?', '[{"id": "a", "text": "900 mL"}, {"id": "b", "text": "1,200 mL"}, {"id": "c", "text": "1,800 mL"}, {"id": "d", "text": "2,400 mL"}]'::jsonb, '["a"]', 'For children, 3 mL × 30 × 20 = 1,800 mL over 24 hours, and half (900 mL) is given in the first 8 hours. 1,200 mL results from wrongly using the adult value of 4 mL.'),
  ('burns', 15, 'An adult was burned at 1400 and arrived in the emergency department at 1600. The calculated Parkland total is 9,600 mL. By what time should the first 4,800 mL be infused?', '[{"id": "a", "text": "1800"}, {"id": "b", "text": "0000"}, {"id": "c", "text": "2200"}, {"id": "d", "text": "0600"}]'::jsonb, '["c"]', 'The first half is given in the first 8 hours timed from the moment of injury, so 1400 + 8 hours = 2200. Choosing 0000 wrongly times the 8 hours from arrival.'),
  ('burns', 16, 'An adult''s Parkland total is 9,600 mL. The burn occurred at 0900, and the first IV fluids were started at 1100. At what hourly rate should the nurse infuse fluid to deliver the first half on schedule?', '[{"id": "a", "text": "600 mL/hr"}, {"id": "b", "text": "400 mL/hr"}, {"id": "c", "text": "1,200 mL/hr"}, {"id": "d", "text": "800 mL/hr"}]'::jsonb, '["d"]', 'Half of 9,600 mL (4,800 mL) is due within 8 hours of injury (by 1700), leaving 6 hours: 4,800 ÷ 6 = 800 mL/hr. 600 mL/hr wrongly spreads the half over 8 hours from the start of fluids.'),
  ('burns', 17, 'An adult client''s Parkland total is 11,200 mL, and the first half was infused on schedule. At what hourly rate should the remaining fluid be infused?', '[{"id": "a", "text": "350 mL/hr"}, {"id": "b", "text": "700 mL/hr"}, {"id": "c", "text": "467 mL/hr"}, {"id": "d", "text": "233 mL/hr"}]'::jsonb, '["a"]', 'The second half (5,600 mL) is given over the next 16 hours: 5,600 ÷ 16 = 350 mL/hr. 700 mL/hr is the rate used for the first 8 hours, not the next 16.'),
  ('burns', 18, 'The provider orders fluid resuscitation using the Parkland formula for a client with a major burn. Which IV solution does the nurse prepare?', '[{"id": "a", "text": "Dextrose 5% in water"}, {"id": "b", "text": "Lactated Ringer''s"}, {"id": "c", "text": "Half-normal saline"}, {"id": "d", "text": "Albumin 25%"}]'::jsonb, '["b"]', 'Parkland formula fluid resuscitation uses Lactated Ringer''s, which replaces fluids and electrolytes. The other solutions are not the fluid specified for Parkland resuscitation.'),
  ('burns', 19, 'A 70-kg adult is receiving fluid resuscitation after a major burn. Which hourly urine output indicates the fluid replacement is adequate?', '[{"id": "a", "text": "15 mL/hr"}, {"id": "b", "text": "25 mL/hr"}, {"id": "c", "text": "50 mL/hr"}, {"id": "d", "text": "30 mL/hr"}]'::jsonb, '["c"]', 'Fluids are titrated to a urine output of 0.5 to 1 mL/kg/hr, which is 35 to 70 mL/hr for a 70-kg client, so 50 mL/hr is adequate. 30 mL/hr falls below the 35 mL/hr minimum.'),
  ('burns', 20, 'The nurse is reviewing the Parkland formula with a nursing student. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "I time the first 8 hours from the injury."}, {"id": "b", "text": "Half the total goes in the first 8 hours."}, {"id": "c", "text": "Adults get 4 mL per kg per percent TBSA."}, {"id": "d", "text": "I can enter the weight in pounds if needed."}]'::jsonb, '["d"]', 'The Parkland formula only works in kilograms; pounds must be converted (lb ÷ 2.2) and never plugged in directly. The other statements correctly describe timing, the half-in-8-hours rule, and the adult multiplier.'),
  ('burns', 21, 'A client rescued from a house fire has soot around the mouth and nose, singed nasal hairs, and a hoarse voice. Which action is the nurse''s priority?', '[{"id": "a", "text": "Prepare for early intubation"}, {"id": "b", "text": "Calculate the Parkland formula"}, {"id": "c", "text": "Apply silver sulfadiazine to the face"}, {"id": "d", "text": "Give the prescribed IM analgesic"}]'::jsonb, '["a"]', 'Soot, singed nasal hairs, and hoarseness signal a dangerous airway burn, so the client should be intubated early before swelling closes the airway. Fluids are important, but the airway comes first.'),
  ('burns', 22, 'The nurse is monitoring a client who inhaled steam and smoke in an enclosed-space fire. Which finding indicates the client''s airway is closing?', '[{"id": "a", "text": "Pain at the forearm burn sites"}, {"id": "b", "text": "High-pitched stridor"}, {"id": "c", "text": "Blisters on both hands"}, {"id": "d", "text": "Red skin on the back that blanches"}]'::jsonb, '["b"]', 'Stridor is a sign that the airway is closing in an inhalation injury. Painful hand or forearm burns and blanching red skin reflect burn depth, not airway closure.'),
  ('burns', 23, 'A client brought in from a burning building is confused, and the skin appears cherry-red. Which condition does the nurse suspect?', '[{"id": "a", "text": "Hypovolemic shock"}, {"id": "b", "text": "Compartment syndrome"}, {"id": "c", "text": "Carbon monoxide poisoning"}, {"id": "d", "text": "Sepsis"}]'::jsonb, '["c"]', 'Confusion or cherry-red skin after smoke inhalation suggests carbon monoxide poisoning. Hypovolemic shock presents with pale, cold skin rather than cherry-red skin.'),
  ('burns', 24, 'A client arrives with 35% TBSA flame burns, facial burns, and a hoarse voice. In which order should the nurse carry out emergent-phase care?', '[{"id": "a", "text": "Airway, IV fluids, IV opioids, clean dry sheet"}, {"id": "b", "text": "IV fluids, airway, clean dry sheet, IV opioids"}, {"id": "c", "text": "IV opioids, airway, IV fluids, clean dry sheet"}, {"id": "d", "text": "Clean dry sheet, IV opioids, IV fluids, airway"}]'::jsonb, '["a"]', 'Emergent-phase care starts with the airway, then Parkland fluid replacement, then IV opioid pain control, then covering with a clean, dry sheet. Starting with fluids or pain control delays the airway priority.'),
  ('burns', 25, 'The nurse is supervising care of a client in the emergent phase of a major burn. Which action by a team member requires correction?', '[{"id": "a", "text": "Covers the client with a clean, dry sheet"}, {"id": "b", "text": "Gives prescribed morphine intravenously"}, {"id": "c", "text": "Hangs Lactated Ringer''s as prescribed"}, {"id": "d", "text": "Gives the prescribed opioid intramuscularly"}]'::jsonb, '["d"]', 'In the emergent phase circulation is poor, so IM medications may not absorb properly; IV is the safest and fastest route. Covering with a clean, dry sheet and giving IV morphine are appropriate.'),
  ('burns', 26, 'Immediately after assessing the airway and starting fluids, the nurse covers a client with extensive burns with a clean, dry sheet. What is the purpose of this action?', '[{"id": "a", "text": "To speed removal of dead tissue"}, {"id": "b", "text": "To prevent infection and heat loss"}, {"id": "c", "text": "To reduce later scar formation"}, {"id": "d", "text": "To release pressure from swelling"}]'::jsonb, '["b"]', 'Covering the client with a clean, dry sheet prevents infection and heat loss. Releasing pressure from swelling is the purpose of escharotomy, not a sheet.'),
  ('burns', 27, 'Six hours after a major burn, a client asks why the nurse will not give an oral pain pill. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "Oral pain pills can cause airway swelling."}, {"id": "b", "text": "Oral pain pills increase the fluid needed."}, {"id": "c", "text": "Poor gut circulation can block absorption."}, {"id": "d", "text": "Oral pain pills interfere with IV fluids."}]'::jsonb, '["c"]', 'In the emergent phase, circulation is poor, especially to the muscles and gut, so PO medications may not absorb properly; IV meds are safest and fastest. The other explanations are not reasons given for avoiding oral medications.'),
  ('burns', 28, 'A client is 5 days post burn injury and is in the acute phase of care. Which focus of care is the priority during this phase?', '[{"id": "a", "text": "Compression garments to reduce scars"}, {"id": "b", "text": "Early intubation to protect the airway"}, {"id": "c", "text": "Support groups for long-term trauma"}, {"id": "d", "text": "Wound healing and infection prevention"}]'::jsonb, '["d"]', 'The acute phase priorities are wound healing, infection prevention, and nutrition. Compression garments and support groups belong to the rehabilitation phase, and airway protection is an emergent-phase priority.'),
  ('burns', 29, 'During sterile wound care for a client in the acute phase of a burn, the nurse prepares to apply an antibiotic ointment. Which agent does the nurse expect to apply?', '[{"id": "a", "text": "Silver sulfadiazine"}, {"id": "b", "text": "Hydrocortisone cream"}, {"id": "c", "text": "Zinc oxide paste"}, {"id": "d", "text": "Petroleum jelly"}]'::jsonb, '["a"]', 'Infection is prevented in the acute phase with sterile wound care and antibiotic ointments such as silver sulfadiazine. The other products are not antibiotic ointments.'),
  ('burns', 30, 'A client in the acute phase of a burn is scheduled for debridement and asks what the procedure involves. Which response by the nurse is accurate?', '[{"id": "a", "text": "Cutting burned skin to release pressure"}, {"id": "b", "text": "Flushing the skin to remove chemicals"}, {"id": "c", "text": "Removing dead tissue from the wound"}, {"id": "d", "text": "Wearing tight garments to flatten scars"}]'::jsonb, '["c"]', 'Debridement is the removal of dead tissue and may be followed by skin grafts. Cutting burned skin to release pressure describes escharotomy, used for compartment syndrome.'),
  ('burns', 31, 'A client recovering from extensive burns is choosing meals. Which selection best meets the client''s nutritional needs?', '[{"id": "a", "text": "Clear broth, gelatin, and tea"}, {"id": "b", "text": "Chicken, eggs, and a milkshake"}, {"id": "c", "text": "Green salad with vinegar dressing"}, {"id": "d", "text": "Plain toast and black coffee"}]'::jsonb, '["b"]', 'Burns increase metabolism, so a high-calorie, high-protein diet is needed; chicken, eggs, and a milkshake provide both. The other choices are low in calories and protein.'),
  ('burns', 32, 'The nurse teaches a client in the acute phase of a burn about nutrition. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I should cut calories since I''m in bed all day."}, {"id": "b", "text": "My body is burning more energy than usual."}, {"id": "c", "text": "I should include protein at every meal."}, {"id": "d", "text": "Extra calories will help my wounds heal."}]'::jsonb, '["a"]', 'Burns increase metabolism, so the client needs a high-calorie, high-protein diet, not fewer calories. The other statements reflect correct understanding of burn nutrition.'),
  ('burns', 33, 'A client in the rehabilitation phase after burns to both hands asks why physical therapy keeps assigning range-of-motion exercises. What is the nurse''s best response?', '[{"id": "a", "text": "They help flush myoglobin from the kidneys."}, {"id": "b", "text": "They keep the blood pressure from dropping."}, {"id": "c", "text": "They help remove dead tissue from the wound."}, {"id": "d", "text": "They help prevent contractures of the joints."}]'::jsonb, '["d"]', 'Range-of-motion exercises in the rehabilitation phase prevent contractures. Removing dead tissue is debridement, an acute-phase intervention.'),
  ('burns', 34, 'A client several months after a burn injury asks why the provider prescribed snug garments to wear over the healed areas. Which response by the nurse is correct?', '[{"id": "a", "text": "They prevent infection in open wounds."}, {"id": "b", "text": "They keep the skin from losing heat."}, {"id": "c", "text": "They help reduce scarring of the skin."}, {"id": "d", "text": "They replace the need for skin grafts."}]'::jsonb, '["c"]', 'Compression garments are used in the rehabilitation phase to reduce scars. Preventing infection and heat loss is the purpose of covering with a clean, dry sheet in the emergent phase.'),
  ('burns', 35, 'Six months after a major burn, a client reports nightmares about the fire and avoids looking in the mirror. Which action by the nurse is most appropriate?', '[{"id": "a", "text": "Prepare the client for early intubation"}, {"id": "b", "text": "Refer the client to a burn survivor support group"}, {"id": "c", "text": "Increase the rate of IV fluids"}, {"id": "d", "text": "Apply silver sulfadiazine to the healed skin"}]'::jsonb, '["b"]', 'Burn survivors often have emotional trauma such as PTSD, anxiety, and body image concerns, and support groups are part of rehabilitation-phase care. The other actions address emergent or acute needs, not psychosocial care.'),
  ('burns', 36, 'The nurse is planning care for a client with major burns. Which time frame correctly describes the acute phase of burn care?', '[{"id": "a", "text": "The first 24 to 48 hours"}, {"id": "b", "text": "Months to years after injury"}, {"id": "c", "text": "The first 8 hours after injury"}, {"id": "d", "text": "From 48 hours until weeks later"}]'::jsonb, '["d"]', 'The acute phase runs from 48 hours to weeks after the burn and focuses on healing the wound. The first 24 to 48 hours is the emergent phase, and months to years is rehabilitation.'),
  ('burns', 37, 'A client with an electrical burn has a small entry wound on the hand and says, ''I feel fine.'' Which action should the nurse take first?', '[{"id": "a", "text": "Place the client on cardiac monitoring"}, {"id": "b", "text": "Prepare the client for discharge home"}, {"id": "c", "text": "Brush the skin off before rinsing it"}, {"id": "d", "text": "Fit the hand with a compression glove"}]'::jsonb, '["a"]', 'Electrical burns cause hidden damage and can injure the heart, so the heart is monitored for deadly arrhythmias like V-fib. A small skin wound does not reflect the hidden damage, so discharge is unsafe.'),
  ('burns', 38, 'The nurse sends urine samples to check for myoglobin in a client with an electrical burn. Which complication is the nurse monitoring for?', '[{"id": "a", "text": "Carbon monoxide poisoning from smoke"}, {"id": "b", "text": "Infection of the entry wound site"}, {"id": "c", "text": "Muscle breakdown that harms the kidneys"}, {"id": "d", "text": "Fluid loss leading to hypovolemic shock"}]'::jsonb, '["c"]', 'Urine is checked for myoglobin because rhabdomyolysis (muscle breakdown) can damage the kidneys. Carbon monoxide poisoning is linked to smoke inhalation, not detected by urine myoglobin.'),
  ('burns', 39, 'A client with a high-voltage electrical burn has myoglobin in the urine. Which intervention does the nurse anticipate?', '[{"id": "a", "text": "Restrict fluids to limit edema"}, {"id": "b", "text": "Give high-volume IV fluids"}, {"id": "c", "text": "Encourage oral fluids only"}, {"id": "d", "text": "Hold fluids until the urine clears"}]'::jsonb, '["b"]', 'High IV fluids are given to flush the kidneys when muscle breakdown releases myoglobin. Restricting or holding fluids would leave the kidneys unprotected.'),
  ('burns', 40, 'The nurse is teaching a nursing student about electrical burns. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "The heart rhythm needs to be monitored."}, {"id": "b", "text": "The urine should be checked for myoglobin."}, {"id": "c", "text": "High IV fluids help to flush the kidneys."}, {"id": "d", "text": "A small skin wound means minimal injury."}]'::jsonb, '["d"]', 'Electrical burns cause hidden damage that can injure the heart, brain, muscles, and organs, so a small skin wound does not mean minimal injury. The other statements describe correct electrical burn care.'),
  ('burns', 41, 'A client arrives after a liquid chemical splashed onto the chest and soaked through the shirt. Which action should the nurse take first?', '[{"id": "a", "text": "Remove the contaminated clothing"}, {"id": "b", "text": "Apply silver sulfadiazine ointment"}, {"id": "c", "text": "Cover the chest with a dry sheet"}, {"id": "d", "text": "Estimate the TBSA with the Rule of Nines"}]'::jsonb, '["a"]', 'Chemical burns keep burning until fully washed off, so contaminated clothing is removed and the skin is flushed with water. Covering or estimating TBSA first allows the chemical to keep burning.'),
  ('burns', 42, 'A worker has a dry powder chemical on both forearms. Which action is appropriate?', '[{"id": "a", "text": "Rinse with water, then brush off the powder"}, {"id": "b", "text": "Apply ointment over the powder"}, {"id": "c", "text": "Brush off the powder, then rinse with water"}, {"id": "d", "text": "Cover the arms with a dry sheet"}]'::jsonb, '["c"]', 'For a dry powder chemical, brush it off first and then rinse. Rinsing first reverses the correct order.'),
  ('burns', 43, 'The nurse is supervising care of a client with a liquid chemical burn to the leg. Which action by a team member requires correction?', '[{"id": "a", "text": "Removes the client''s soaked pants"}, {"id": "b", "text": "Stops flushing the skin after 5 minutes"}, {"id": "c", "text": "Flushes the skin with running water"}, {"id": "d", "text": "Keeps flushing for a full 30 minutes"}]'::jsonb, '["b"]', 'Chemical burns must be flushed with water for at least 20 to 30 minutes, so stopping at 5 minutes is too short. Removing contaminated clothing and flushing with water are correct actions.'),
  ('burns', 44, 'Eight hours after a 40% TBSA burn, a client''s BP is 82/48 mm Hg and heart rate is 126/min. The skin is pale and cold. The client is afebrile and alert. Which complication does the nurse suspect?', '[{"id": "a", "text": "Sepsis"}, {"id": "b", "text": "Compartment syndrome"}, {"id": "c", "text": "Carbon monoxide poisoning"}, {"id": "d", "text": "Hypovolemic shock"}]'::jsonb, '["d"]', 'Low BP, fast HR, and pale, cold skin in the first 24 to 48 hours signal hypovolemic shock, treated with Parkland IV fluids. Sepsis would also include fever and confusion, which are absent.'),
  ('burns', 45, 'A client with a circumferential burn of the lower leg reports increasing pain and tingling. The foot is pale, and the pedal pulse is absent. Which procedure does the nurse anticipate?', '[{"id": "a", "text": "Escharotomy"}, {"id": "b", "text": "Debridement"}, {"id": "c", "text": "Skin grafting"}, {"id": "d", "text": "Compression garment"}]'::jsonb, '["a"]', 'Pain, pale skin, no pulse, and tingling indicate compartment syndrome, which is treated with escharotomy (cutting burned skin to release pressure). Debridement removes dead tissue but does not release pressure.'),
  ('burns', 46, 'Nine days after a major burn, a client has a fever, heart rate of 120/min, BP of 84/50 mm Hg, and new confusion. Which treatment does the nurse anticipate?', '[{"id": "a", "text": "Escharotomy of the burned skin"}, {"id": "b", "text": "Compression garments to the limbs"}, {"id": "c", "text": "IV antibiotics and sterile wound care"}, {"id": "d", "text": "Early intubation for an airway burn"}]'::jsonb, '["c"]', 'Fever, fast HR, low BP, and confusion indicate sepsis, which is treated with IV antibiotics and sterile wound care. Escharotomy treats compartment syndrome, not sepsis.'),
  ('burns', 47, 'The nurse is monitoring serum potassium in a client with a major burn. Which pattern does the nurse anticipate?', '[{"id": "a", "text": "Low early, then high later"}, {"id": "b", "text": "High early, then low later"}, {"id": "c", "text": "High throughout the first weeks"}, {"id": "d", "text": "Low throughout the first weeks"}]'::jsonb, '["b"]', 'Potassium is elevated early after a burn and decreases later. The reversed pattern (low early, high later) is incorrect.'),
  ('burns', 48, 'The nurse is reviewing data for a client in the acute phase of a burn. Which finding suggests the burn wound is infected?', '[{"id": "a", "text": "Pain rated 2/10 after IV opioid"}, {"id": "b", "text": "Urine output of 0.5 mL/kg/hr"}, {"id": "c", "text": "Serum potassium lower than on day 1"}, {"id": "d", "text": "Elevated WBC count with pus and odor"}]'::jsonb, '["d"]', 'Signs of burn infection include fever, elevated WBC, pus, and odor. A potassium decrease later in care is an expected electrolyte pattern, not a sign of infection.'),
  ('burns', 49, 'An adult has superficial partial-thickness burns covering 4% TBSA, limited to the palms and backs of both hands. How should the nurse classify the burn severity?', '[{"id": "a", "text": "Major, because the hands are a critical area"}, {"id": "b", "text": "Moderate, because both hands are involved"}, {"id": "c", "text": "Minor, because the TBSA is less than 10%"}, {"id": "d", "text": "Minor, because the burn is partial thickness"}]'::jsonb, '["a"]', 'Burns to critical areas such as the face, hands, feet, genitals, or airway are classified as major regardless of TBSA. Calling it minor because TBSA is under 10% ignores the critical location.'),
  ('burns', 50, 'An adult has superficial partial-thickness burns covering 15% TBSA on the back and one arm. The face, hands, feet, genitals, and airway are not involved. How should the nurse classify the burn severity?', '[{"id": "a", "text": "Minor, because it is under 20% TBSA"}, {"id": "b", "text": "Major, because it is over 10% TBSA"}, {"id": "c", "text": "Moderate, because it is 10–20% TBSA"}, {"id": "d", "text": "Minor, because no critical area is burned"}]'::jsonb, '["c"]', 'A burn of 10% to 20% TBSA without critical-area involvement is moderate. Major burns are those over 20% TBSA or in critical areas, and minor adult burns are under 10%.'),
  ('common', 1, 'A client presents with thick, red plaques covered with silvery-white scales on both elbows and knees. The nurse recognizes these findings as characteristic of which condition?', '[{"id": "a", "text": "Atopic dermatitis"}, {"id": "b", "text": "Psoriasis"}, {"id": "c", "text": "Contact dermatitis"}, {"id": "d", "text": "Impetigo"}]'::jsonb, '["b"]', 'Psoriasis causes thick, red plaques with silvery-white scales commonly on the elbows, knees, and scalp. Atopic dermatitis also favors elbows and knees, but it presents as dry, itchy, inflamed skin in the skin creases rather than silvery plaques.'),
  ('common', 2, 'The parent of a school-age child newly diagnosed with psoriasis asks whether the child''s siblings could catch the condition. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Psoriasis is not contagious, so the siblings cannot catch it.\""}, {"id": "b", "text": "\"Keep the siblings apart until all of the scales are gone.\""}, {"id": "c", "text": "\"The siblings should use the same cream to prevent spread.\""}, {"id": "d", "text": "\"It spreads through shared towels, so keep towels separate.\""}]'::jsonb, '["a"]', 'Psoriasis is a chronic autoimmune condition and is not contagious, so no separation or prophylactic treatment of siblings is needed. Treating contacts is a scabies measure, not a psoriasis measure.'),
  ('common', 3, 'A client with newly diagnosed psoriasis asks the nurse what causes the condition. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"A mite burrows under the skin and triggers a reaction.\""}, {"id": "b", "text": "\"Bacteria enter the skin after a minor scrape or injury.\""}, {"id": "c", "text": "\"Your immune system attacks your skin, speeding cell turnover.\""}, {"id": "d", "text": "\"Your skin reacts only where it touched an irritant.\""}]'::jsonb, '["c"]', 'Psoriasis is a chronic autoimmune condition in which the body attacks itself, causing rapid skin cell turnover. Bacterial entry after minor trauma describes impetigo, and a localized reaction at the site of contact describes contact dermatitis.'),
  ('common', 4, 'The nurse is reinforcing teaching with a client who has psoriasis. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will moisturize my skin every day.\""}, {"id": "b", "text": "\"I should look for ways to manage my stress.\""}, {"id": "c", "text": "\"I will avoid harsh soaps when I bathe.\""}, {"id": "d", "text": "\"Cold weather will not affect my psoriasis.\""}]'::jsonb, '["d"]', 'Cold is one of the psoriasis triggers to avoid, along with stress, trauma, and infection, so this statement needs correction. Daily moisturizing, stress management, and avoiding harsh soaps are all correct teaching points.'),
  ('common', 5, 'A client with plaque psoriasis receives a new prescription for a topical vitamin D analog. Which medication does the nurse expect to be prescribed?', '[{"id": "a", "text": "Calcipotriene"}, {"id": "b", "text": "Permethrin 5% cream"}, {"id": "c", "text": "Mupirocin"}, {"id": "d", "text": "An oral antibiotic"}]'::jsonb, '["a"]', 'Calcipotriene is the vitamin D analog used to treat psoriasis. Permethrin treats scabies, while mupirocin and oral antibiotics treat the bacterial infection impetigo.'),
  ('common', 6, 'A client has severe psoriasis that has not responded to topical therapy. Which type of treatment does the nurse anticipate may be added for this severe case?', '[{"id": "a", "text": "Cool compresses"}, {"id": "b", "text": "Biologics"}, {"id": "c", "text": "Permethrin cream"}, {"id": "d", "text": "Antihistamines"}]'::jsonb, '["b"]', 'Biologics are reserved for severe cases of psoriasis. Cool compresses are a contact dermatitis measure, permethrin treats scabies, and antihistamines are used for eczema itching.'),
  ('common', 7, 'The nurse reviews treatment plans for several clients with skin disorders. Which plan is consistent with the management of psoriasis?', '[{"id": "a", "text": "Permethrin cream and hot-water laundering"}, {"id": "b", "text": "Mupirocin and no school for 24 hours"}, {"id": "c", "text": "Topical corticosteroids and light therapy"}, {"id": "d", "text": "Stopping the drug and giving IV fluids"}]'::jsonb, '["c"]', 'Psoriasis is treated with topical corticosteroids, vitamin D analogs, phototherapy (light therapy), and biologics for severe cases. Permethrin with hot-water laundering is the scabies plan, and stopping the drug with fluids is the Stevens-Johnson syndrome plan.'),
  ('common', 8, 'An infant is brought to the clinic with dry, itchy, inflamed patches on both cheeks. The parent reports a family history of asthma and allergies. The nurse recognizes these findings as consistent with which condition?', '[{"id": "a", "text": "Contact dermatitis"}, {"id": "b", "text": "Impetigo"}, {"id": "c", "text": "Scabies"}, {"id": "d", "text": "Atopic dermatitis"}]'::jsonb, '["d"]', 'Eczema (atopic dermatitis) causes dry, itchy, inflamed skin, is common on the cheeks of infants, and often occurs with a history of allergies or asthma. Impetigo causes honey-colored crusts around the nose and mouth rather than dry, inflamed patches.'),
  ('common', 9, 'The nurse is obtaining a health history from an adult client with atopic dermatitis. Which finding in the history is the nurse most likely to note?', '[{"id": "a", "text": "A history of allergies and asthma"}, {"id": "b", "text": "A recent course of a sulfa drug"}, {"id": "c", "text": "A household member with night itching"}, {"id": "d", "text": "A recent minor scrape on the face"}]'::jsonb, '["a"]', 'Eczema (atopic dermatitis) is a chronic inflammatory disorder that often occurs with a history of allergies or asthma. A recent sulfa drug suggests Stevens-Johnson syndrome, and a household member with night itching suggests scabies.'),
  ('common', 10, 'The nurse is teaching the parent of a child with eczema about skin hydration. Which product should the nurse recommend?', '[{"id": "a", "text": "A thin lotion used only when skin cracks"}, {"id": "b", "text": "A thick petroleum-based moisturizer"}, {"id": "c", "text": "A deodorant bar soap used twice daily"}, {"id": "d", "text": "Permethrin cream applied from the neck down"}]'::jsonb, '["b"]', 'Eczema treatment includes hydration with thick petroleum-based moisturizers. Soaps are triggers to avoid in eczema, and permethrin is the treatment for scabies.'),
  ('common', 11, 'A client with eczema reports that intense itching is keeping them awake. Which medication does the nurse anticipate to relieve the itching?', '[{"id": "a", "text": "Mupirocin ointment"}, {"id": "b", "text": "Permethrin 5% cream"}, {"id": "c", "text": "An oral antihistamine"}, {"id": "d", "text": "Calcipotriene cream"}]'::jsonb, '["c"]', 'Antihistamines are used for itching in eczema. Mupirocin is a topical antibiotic for impetigo, and permethrin treats the itching of scabies by treating the mite infestation.'),
  ('common', 12, 'The nurse reinforces home-care teaching with the parent of a child who has atopic dermatitis. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"I will keep my child away from known allergens.\""}, {"id": "b", "text": "\"I will apply a thick moisturizer after baths.\""}, {"id": "c", "text": "\"I will use the steroid cream as prescribed.\""}, {"id": "d", "text": "\"I will wash the patches with a strong soap.\""}]'::jsonb, '["d"]', 'Soaps and allergens are eczema triggers that should be avoided, so washing with a strong soap needs correction. Thick moisturizers, topical corticosteroids, and allergen avoidance are all part of eczema treatment.'),
  ('common', 13, 'A nurse develops a red, itchy rash with small blisters on both hands only where latex gloves were worn during a shift. Which condition is most likely?', '[{"id": "a", "text": "Contact dermatitis"}, {"id": "b", "text": "Atopic dermatitis"}, {"id": "c", "text": "Psoriasis"}, {"id": "d", "text": "Impetigo"}]'::jsonb, '["a"]', 'Contact dermatitis is a localized reaction to skin contact with an allergen or irritant, causing a red rash, blisters, and itching at the site; latex is a common cause. Atopic dermatitis is inherited and chronic rather than limited to a site of direct exposure.'),
  ('common', 14, 'A client reports an itchy, blistering rash on both wrists that began after switching to a new laundry detergent. Which action should the nurse teach the client to take first?', '[{"id": "a", "text": "Apply mupirocin ointment to the blisters"}, {"id": "b", "text": "Stop using the new laundry detergent"}, {"id": "c", "text": "Stay away from others until the rash heals"}, {"id": "d", "text": "Apply permethrin cream from the neck down"}]'::jsonb, '["b"]', 'The first step in treating contact dermatitis is to remove the offending agent, then use topical corticosteroids and cool compresses. Mupirocin and permethrin treat impetigo and scabies, not a contact reaction.'),
  ('common', 15, 'A camper has an itchy, blistering rash on the forearms after brushing against poison ivy. Which comfort measure should the nurse recommend for the rash?', '[{"id": "a", "text": "Hot compresses applied to the rash"}, {"id": "b", "text": "Permethrin cream applied overnight"}, {"id": "c", "text": "Cool compresses applied to the rash"}, {"id": "d", "text": "Oral antibiotics started right away"}]'::jsonb, '["c"]', 'Cool compresses are part of contact dermatitis treatment, along with removing the offending agent and using topical corticosteroids. Permethrin is for scabies, and oral antibiotics are for severe impetigo.'),
  ('common', 16, 'A nursing student asks how atopic dermatitis differs from contact dermatitis. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Atopic is localized to exposure; contact is inherited and chronic.\""}, {"id": "b", "text": "\"Both are contagious and spread through direct skin contact.\""}, {"id": "c", "text": "\"Atopic is caused by a mite; contact is caused by bacteria.\""}, {"id": "d", "text": "\"Atopic is inherited and chronic; contact is localized to exposure.\""}]'::jsonb, '["d"]', 'Atopic dermatitis is inherited and chronic, whereas contact dermatitis results from direct exposure and is localized. Option A reverses the two conditions.'),
  ('common', 17, 'A client reports severe itching that is worse at night. The nurse notes tiny thread-like tracks between the client''s fingers. These findings are most consistent with which condition?', '[{"id": "a", "text": "Scabies"}, {"id": "b", "text": "Psoriasis"}, {"id": "c", "text": "Contact dermatitis"}, {"id": "d", "text": "Atopic dermatitis"}]'::jsonb, '["a"]', 'Scabies causes severe itching that is worse at night and burrow lines, which are tiny thread-like tracks, commonly between the fingers. Contact dermatitis causes itching limited to the site of contact without burrows.'),
  ('common', 18, 'The nurse is assessing a client with suspected scabies. Which areas should the nurse inspect most closely for burrow lines?', '[{"id": "a", "text": "Cheeks and the skin creases"}, {"id": "b", "text": "Between the fingers, wrists, and waist"}, {"id": "c", "text": "Around the nose and mouth"}, {"id": "d", "text": "The mouth, eyes, and genitals"}]'::jsonb, '["b"]', 'Scabies burrows are common between the fingers, at the wrists, and at the waist. The cheeks and skin creases are typical eczema sites, and the area around the nose and mouth is typical of impetigo.'),
  ('common', 19, 'The nurse is teaching a client how to use permethrin 5% cream for scabies. Which instruction is correct?', '[{"id": "a", "text": "\"Apply it to your face only and rinse after 1 hour.\""}, {"id": "b", "text": "\"Apply it only to the burrows and leave it on for 3 days.\""}, {"id": "c", "text": "\"Apply it from the neck down and wash off after 8 to 14 hours.\""}, {"id": "d", "text": "\"Apply it to your scalp and rinse off after 30 minutes.\""}]'::jsonb, '["c"]', 'Permethrin 5% cream is applied from the neck down and washed off after 8 to 14 hours. Applying it only to burrows or to the face or scalp does not match the neck-down application.'),
  ('common', 20, 'The nurse reinforces teaching with the parent of a child diagnosed with scabies. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"I will wash all of our bed linens in hot water.\""}, {"id": "b", "text": "\"I will apply the cream from my child''s neck down.\""}, {"id": "c", "text": "\"I will wash my child''s clothes in hot water.\""}, {"id": "d", "text": "\"Only my child needs the cream since no one else itches.\""}]'::jsonb, '["d"]', 'All household members must be treated for scabies, so treating only the child needs correction. Washing clothing and linens in hot water and applying permethrin from the neck down are correct.'),
  ('common', 21, 'A client with scabies asks how to handle clothing and bed linens at home. Which instruction should the nurse give?', '[{"id": "a", "text": "\"Wash clothing and linens in hot water.\""}, {"id": "b", "text": "\"Wash clothing and linens in cold water.\""}, {"id": "c", "text": "\"Shake the linens out outdoors before use.\""}, {"id": "d", "text": "\"Air the linens in sunlight for one day.\""}]'::jsonb, '["a"]', 'Clothing and linens of a client with scabies are washed in hot water. Cold-water washing reverses the correct instruction.'),
  ('common', 22, 'The parent of a child with scabies asks what caused the rash. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is an infection from staph or strep bacteria.\""}, {"id": "b", "text": "\"It is an infestation by the Sarcoptes scabiei mite.\""}, {"id": "c", "text": "\"It is the immune system attacking the skin.\""}, {"id": "d", "text": "\"It is a reaction to an allergen like detergent.\""}]'::jsonb, '["b"]', 'Scabies is a parasitic skin infestation by the Sarcoptes scabiei mite. Staph or strep infection describes impetigo, and immune attack on the skin describes psoriasis.'),
  ('common', 23, 'A 5-year-old child has honey-colored crusts around the nose and mouth that appeared a few days after a minor scrape on the face. The nurse recognizes these findings as consistent with which condition?', '[{"id": "a", "text": "Contact dermatitis"}, {"id": "b", "text": "Psoriasis"}, {"id": "c", "text": "Impetigo"}, {"id": "d", "text": "Atopic dermatitis"}]'::jsonb, '["c"]', 'Impetigo causes honey-colored crusts around the nose and mouth and is common in children after minor skin trauma. Atopic dermatitis in children causes dry, itchy, inflamed skin rather than honey-colored crusts.'),
  ('common', 24, 'A child is diagnosed with a mild case of impetigo. Which medication does the nurse anticipate will be prescribed?', '[{"id": "a", "text": "Permethrin 5% cream"}, {"id": "b", "text": "Calcipotriene cream"}, {"id": "c", "text": "An oral antihistamine"}, {"id": "d", "text": "Mupirocin ointment"}]'::jsonb, '["d"]', 'Impetigo is treated with a topical antibiotic such as mupirocin, with oral antibiotics if severe. Permethrin treats scabies and calcipotriene treats psoriasis.'),
  ('common', 25, 'The parent of a child with impetigo asks when the child may return to school. Which response by the nurse is correct?', '[{"id": "a", "text": "\"After 24 hours of antibiotic treatment.\""}, {"id": "b", "text": "\"Right away, since impetigo is not contagious.\""}, {"id": "c", "text": "\"After 8 hours of antibiotic treatment.\""}, {"id": "d", "text": "\"Only after the full antibiotic course ends.\""}]'::jsonb, '["a"]', 'A child with impetigo should not attend school until 24 hours after starting antibiotics. Impetigo is highly contagious, so an immediate return is unsafe.'),
  ('common', 26, 'The nurse is explaining impetigo to the parents of a toddler. Which statement by the nurse is accurate?', '[{"id": "a", "text": "\"It is a noncontagious autoimmune skin disease.\""}, {"id": "b", "text": "\"It is a highly contagious bacterial skin infection.\""}, {"id": "c", "text": "\"It is a mite infestation that itches at night.\""}, {"id": "d", "text": "\"It is an inherited, chronic inflammatory rash.\""}]'::jsonb, '["b"]', 'Impetigo is a highly contagious bacterial skin infection, usually caused by staph or strep. A noncontagious autoimmune disease describes psoriasis, and a mite infestation describes scabies.'),
  ('common', 27, 'A child has widespread, severe impetigo involving several areas of the face and arms. Which treatment does the nurse anticipate?', '[{"id": "a", "text": "Permethrin cream from the neck down"}, {"id": "b", "text": "Biologic therapy injections"}, {"id": "c", "text": "Oral antibiotics"}, {"id": "d", "text": "Phototherapy sessions"}]'::jsonb, '["c"]', 'Impetigo is treated with topical mupirocin, with oral antibiotics added if severe. Biologics and phototherapy are psoriasis treatments, and permethrin is for scabies.'),
  ('common', 28, 'A child with impetigo lives with two younger siblings. Which instruction is most important for the nurse to give the family to prevent spread?', '[{"id": "a", "text": "\"Apply a thick petroleum moisturizer to the sores.\""}, {"id": "b", "text": "\"Treat everyone in the home with permethrin.\""}, {"id": "c", "text": "\"Wash off the cream after 8 to 14 hours.\""}, {"id": "d", "text": "\"Practice good hygiene throughout the home.\""}]'::jsonb, '["d"]', 'Impetigo is highly contagious, and good hygiene is key to preventing its spread. Treating every household member with permethrin is a scabies measure.'),
  ('common', 29, 'The school nurse is reviewing health records. Which student is at greatest risk for developing impetigo?', '[{"id": "a", "text": "A 6-year-old with a recent minor scrape"}, {"id": "b", "text": "A 16-year-old with plaque psoriasis"}, {"id": "c", "text": "A 17-year-old taking a sulfa drug"}, {"id": "d", "text": "A 15-year-old with a latex allergy"}]'::jsonb, '["a"]', 'Impetigo is common in children after minor skin trauma. A sulfa drug is associated with Stevens-Johnson syndrome, and latex is a common cause of contact dermatitis.'),
  ('common', 30, 'A client started on an anticonvulsant 1 week ago now has a painful red-purple rash that is spreading and blistering, along with sores in the mouth. The nurse suspects which condition?', '[{"id": "a", "text": "Contact dermatitis"}, {"id": "b", "text": "Stevens-Johnson syndrome"}, {"id": "c", "text": "Impetigo"}, {"id": "d", "text": "Psoriasis"}]'::jsonb, '["b"]', 'Stevens-Johnson syndrome is often drug-induced, including by anticonvulsants, and causes a painful red/purple rash that spreads and blisters with mucosal involvement. Contact dermatitis is a localized rash at the site of contact without mucosal involvement.'),
  ('common', 31, 'A hospitalized client receiving a sulfa drug develops a spreading, blistering rash with eye and mouth involvement, and Stevens-Johnson syndrome is suspected. What is the nurse''s priority action?', '[{"id": "a", "text": "Apply cool compresses to the rash"}, {"id": "b", "text": "Apply a topical corticosteroid"}, {"id": "c", "text": "Stop the offending drug immediately"}, {"id": "d", "text": "Apply mupirocin to the blisters"}]'::jsonb, '["c"]', 'Stevens-Johnson syndrome is an emergency, and the priority is to stop the offending drug immediately. Cool compresses and topical corticosteroids are contact dermatitis treatments and do not remove the cause.'),
  ('common', 32, 'The nurse is reviewing the medication history of a client with suspected Stevens-Johnson syndrome. Which medication class is most likely to have caused this reaction?', '[{"id": "a", "text": "Topical antibiotics"}, {"id": "b", "text": "Vitamin D analogs"}, {"id": "c", "text": "Scabicide creams"}, {"id": "d", "text": "Sulfa drugs"}]'::jsonb, '["d"]', 'Stevens-Johnson syndrome is often drug-induced, for example by sulfa drugs, anticonvulsants, or NSAIDs. Topical antibiotics, vitamin D analogs, and scabicides are treatments for impetigo, psoriasis, and scabies.'),
  ('common', 33, 'A client is admitted with Stevens-Johnson syndrome, and the offending drug has been stopped. Which plan of care does the nurse anticipate?', '[{"id": "a", "text": "Fluids, infection prevention, and pain control"}, {"id": "b", "text": "Discharge home with petroleum moisturizer"}, {"id": "c", "text": "Isolation until 24 hours of antibiotics"}, {"id": "d", "text": "Permethrin and hot-water linen washing"}]'::jsonb, '["a"]', 'A client with Stevens-Johnson syndrome is treated like a burn patient, with fluids, infection prevention, and pain control. It is a life-threatening emergency, so discharge home with a moisturizer is inappropriate.'),
  ('common', 34, 'The nurse is caring for clients who take NSAIDs regularly. Which client finding should the nurse report to the health care provider immediately?', '[{"id": "a", "text": "Dry, itchy patches in the elbow creases"}, {"id": "b", "text": "Blistering rash with sores in the mouth and eyes"}, {"id": "c", "text": "Silvery scales on the scalp and knees"}, {"id": "d", "text": "Red rash only where a watch band touches"}]'::jsonb, '["b"]', 'A blistering rash with mucosal involvement in a client taking an NSAID suggests Stevens-Johnson syndrome, a life-threatening emergency. Dry patches in the creases, silvery scales, and a rash at a contact site suggest eczema, psoriasis, and contact dermatitis.'),
  ('common', 35, 'The nurse is assessing the skin of a client with Stevens-Johnson syndrome. Which finding does the nurse expect?', '[{"id": "a", "text": "Honey-colored crusts around the nose"}, {"id": "b", "text": "Thick plaques with silvery-white scales"}, {"id": "c", "text": "Skin that sloughs off like a burn"}, {"id": "d", "text": "Thread-like tracks between the fingers"}]'::jsonb, '["c"]', 'In Stevens-Johnson syndrome, the skin sloughs off like a burn. Honey-colored crusts suggest impetigo, silvery scales suggest psoriasis, and thread-like tracks suggest scabies.'),
  ('common', 36, 'The nurse receives report on four clients. Which client should the nurse see first?', '[{"id": "a", "text": "An infant with dry, itchy patches on the cheeks"}, {"id": "b", "text": "An adult with silvery plaques on the elbows"}, {"id": "c", "text": "A child with night itching between the fingers"}, {"id": "d", "text": "An adult with spreading blisters after a new sulfa drug"}]'::jsonb, '["d"]', 'A spreading blistering rash after starting a sulfa drug suggests Stevens-Johnson syndrome, a rare but life-threatening emergency. Eczema, psoriasis, and scabies are not described as life-threatening.'),
  ('common', 37, 'The charge nurse observes a nurse caring for a client with Stevens-Johnson syndrome that was triggered by an anticonvulsant. Which action by the nurse requires correction?', '[{"id": "a", "text": "Giving the next scheduled anticonvulsant dose"}, {"id": "b", "text": "Monitoring the client''s fluid replacement"}, {"id": "c", "text": "Using measures to prevent infection"}, {"id": "d", "text": "Administering prescribed pain medication"}]'::jsonb, '["a"]', 'The offending drug must be stopped immediately in Stevens-Johnson syndrome, so giving the next dose of the triggering anticonvulsant is unsafe. Fluids, infection prevention, and pain control are the correct burn-like care.'),
  ('common', 38, 'A client reports brushing against poison ivy while gardening yesterday. Which finding does the nurse expect to observe?', '[{"id": "a", "text": "Honey-colored crusts around the mouth"}, {"id": "b", "text": "Red rash, blisters, and itching at the contact site"}, {"id": "c", "text": "Silvery-white scales on the scalp"}, {"id": "d", "text": "Burrow lines on the wrists and waist"}]'::jsonb, '["b"]', 'Poison ivy is a common cause of contact dermatitis, which produces a red rash, blisters, and itching at the site of contact. Burrow lines on the wrists and waist suggest scabies.'),
  ('common', 39, 'The nurse reinforces teaching with a client who has contact dermatitis from a laundry detergent. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will use cool compresses when the rash itches.\""}, {"id": "b", "text": "\"I will apply the steroid cream as it was prescribed.\""}, {"id": "c", "text": "\"I can keep using the detergent if I rinse my skin.\""}, {"id": "d", "text": "\"I will switch to a different laundry detergent.\""}]'::jsonb, '["c"]', 'Contact dermatitis treatment begins with removing the offending agent, so continuing the detergent needs correction. Cool compresses and topical corticosteroids are correct treatments.'),
  ('common', 40, 'The nurse is assessing a toddler with atopic dermatitis. Besides the cheeks, where is the nurse most likely to find the dry, itchy, inflamed skin?', '[{"id": "a", "text": "Between the fingers and at the waist"}, {"id": "b", "text": "Around the nose and the mouth"}, {"id": "c", "text": "The mouth, eyes, and genitals"}, {"id": "d", "text": "The skin creases of the elbows and knees"}]'::jsonb, '["d"]', 'Eczema is common on the cheeks in infants and in the skin creases of the elbows and knees. Between the fingers and at the waist are scabies sites, and around the nose and mouth is typical of impetigo.'),
  ('common', 41, 'A nurse is reviewing skin disorders with a group of new graduates. Which pairing of a condition with its key sign is correct?', '[{"id": "a", "text": "Scabies: night itch and burrows"}, {"id": "b", "text": "Impetigo: silvery scales"}, {"id": "c", "text": "Psoriasis: honey-colored crust"}, {"id": "d", "text": "Eczema: skin peeling with mucosal sores"}]'::jsonb, '["a"]', 'The key sign of scabies is night itch with burrows. Silvery scales belong to psoriasis, honey crust belongs to impetigo, and skin peeling with mucosal involvement belongs to Stevens-Johnson syndrome.'),
  ('common', 42, 'A client with psoriasis has been taught about flare prevention. Which statement by the client indicates understanding?', '[{"id": "a", "text": "\"I should scrub my plaques daily with a harsh soap.\""}, {"id": "b", "text": "\"Infections and skin injuries can trigger a flare.\""}, {"id": "c", "text": "\"I must stay away from others until the scales heal.\""}, {"id": "d", "text": "\"My family members need treatment with my cream too.\""}]'::jsonb, '["b"]', 'Psoriasis triggers include stress, cold, trauma, and infection, so clients should avoid them. Harsh soaps should be avoided, and because psoriasis is not contagious, isolation and treating family members are unnecessary.'),
  ('common', 43, 'A client with both psoriasis and eczema asks how the two conditions differ. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Eczema is autoimmune with silvery scales; psoriasis is dry, itchy skin.\""}, {"id": "b", "text": "\"Both are contagious, so wash your hands after touching either area.\""}, {"id": "c", "text": "\"Psoriasis is autoimmune with silvery scales; eczema is dry, itchy skin.\""}, {"id": "d", "text": "\"Psoriasis is caused by a mite; eczema is caused by bacteria.\""}]'::jsonb, '["c"]', 'Psoriasis is autoimmune with silvery scales, whereas eczema presents as dry, itchy skin. Option A reverses the two conditions, and psoriasis is not contagious.'),
  ('common', 44, 'A client is diagnosed with scabies and lives with a spouse and two children who have no symptoms. Which action by the nurse is appropriate?', '[{"id": "a", "text": "Treat only the client who has symptoms"}, {"id": "b", "text": "Treat the family only if itching develops"}, {"id": "c", "text": "Exclude the client from work for 24 hours"}, {"id": "d", "text": "Arrange treatment for all household members"}]'::jsonb, '["d"]', 'In scabies, all household members are treated along with the client. Waiting for symptoms or treating only the client does not follow the rule to treat contacts.'),
  ('common', 45, 'The nurse is interviewing a client with suspected scabies. Which client statement is most consistent with this condition?', '[{"id": "a", "text": "\"The itching is much worse at night.\""}, {"id": "b", "text": "\"The rash is only where my gloves touched.\""}, {"id": "c", "text": "\"It does not itch, but there are silvery flakes.\""}, {"id": "d", "text": "\"It is painful, and my mouth has blisters.\""}]'::jsonb, '["a"]', 'Scabies causes severe itching that is worse at night. A rash only where gloves touched suggests contact dermatitis, and a painful rash with mouth blisters suggests Stevens-Johnson syndrome.'),
  ('common', 46, 'A client has a localized red, itchy rash with blisters on the hands. When asking about recent exposures, which exposure does the nurse recognize as a common cause of this type of reaction?', '[{"id": "a", "text": "A newly started sulfa drug"}, {"id": "b", "text": "A new household detergent"}, {"id": "c", "text": "A recent minor skin scrape"}, {"id": "d", "text": "A spell of cold weather"}]'::jsonb, '["b"]', 'Detergents, latex, and poison ivy are common causes of contact dermatitis, a localized reaction at the site of contact. A sulfa drug is linked to Stevens-Johnson syndrome, and a minor skin scrape is linked to impetigo.'),
  ('common', 47, 'The nurse reinforces teaching with the parent of a child who has impetigo. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"I will help my child wash hands often.\""}, {"id": "b", "text": "\"I will apply the mupirocin as prescribed.\""}, {"id": "c", "text": "\"My child can go to school today since the first dose is tonight.\""}, {"id": "d", "text": "\"My child will stay home until 24 hours of antibiotics.\""}]'::jsonb, '["c"]', 'A child with impetigo should not attend school until 24 hours after starting antibiotics, so attending school before the first dose needs correction. Hand hygiene and mupirocin use are correct.'),
  ('common', 48, 'The nurse is admitting a client with suspected Stevens-Johnson syndrome. Which areas should the nurse inspect to assess for mucosal involvement?', '[{"id": "a", "text": "Between the fingers, wrists, and waist"}, {"id": "b", "text": "The elbows, knees, and scalp"}, {"id": "c", "text": "The cheeks and the skin creases"}, {"id": "d", "text": "The mouth, eyes, and genitals"}]'::jsonb, '["d"]', 'Stevens-Johnson syndrome involves mucosa of the mouth, eyes, and genitals. The fingers, wrists, and waist are scabies sites, and the elbows, knees, and scalp are psoriasis sites.'),
  ('common', 49, 'The nurse manager observes a nurse caring for a client with scabies. Which action by the nurse requires correction?', '[{"id": "a", "text": "Applying permethrin only to the face and scalp"}, {"id": "b", "text": "Sending the client''s linens to be washed in hot water"}, {"id": "c", "text": "Teaching that all household members need treatment"}, {"id": "d", "text": "Instructing the client to wash off the cream after 8 to 14 hours"}]'::jsonb, '["a"]', 'Permethrin 5% cream is applied from the neck down, so applying it only to the face and scalp is incorrect. Hot-water laundering, treating household members, and washing off after 8 to 14 hours are all correct.'),
  ('common', 50, 'The nurse has taught the parent of an infant with atopic dermatitis about home care. Which statement by the parent indicates understanding?', '[{"id": "a", "text": "\"I will bathe my baby with a strong soap every day.\""}, {"id": "b", "text": "\"I will apply a thick petroleum-based moisturizer.\""}, {"id": "c", "text": "\"My baby''s eczema will be gone after one treatment.\""}, {"id": "d", "text": "\"My baby must stay home from day care for 24 hours.\""}]'::jsonb, '["b"]', 'Eczema is managed with hydration using thick petroleum-based moisturizers. It is a chronic disorder, so a one-time cure is not expected, and soaps are triggers to avoid.'),
  ('overview', 1, 'During a clinical conference, a nursing student describes what counts as a skin condition. Which statement by the student is accurate?', '[{"id": "a", "text": "\"It is any disorder of the skin, hair, or nails.\""}, {"id": "b", "text": "\"It is any disorder of the outer skin layer only.\""}, {"id": "c", "text": "\"It is a skin disorder that is always long-term.\""}, {"id": "d", "text": "\"It is a skin disorder that is always infectious.\""}]'::jsonb, '["a"]', 'A skin condition is any disorder affecting the skin, hair, or nails. Some are temporary, such as rashes, and others are chronic, so skin conditions are not always long-term.'),
  ('overview', 2, 'The nurse is categorizing the causes of skin conditions for a client education handout. Which cause belongs in the inflammation category?', '[{"id": "a", "text": "A fungal infection"}, {"id": "b", "text": "An autoimmune disease"}, {"id": "c", "text": "Prolonged sun exposure"}, {"id": "d", "text": "High humidity"}]'::jsonb, '["b"]', 'Inflammatory causes include allergic reactions and autoimmune disease. Fungal infection is an infectious cause, while sun exposure and humidity are environmental factors.'),
  ('overview', 3, 'A client reports that a skin rash flares whenever the weather becomes hot and humid. The nurse recognizes this trigger as belonging to which category of causes?', '[{"id": "a", "text": "Parasitic infection"}, {"id": "b", "text": "Allergic inflammation"}, {"id": "c", "text": "Environmental factors"}, {"id": "d", "text": "Viral infection"}]'::jsonb, '["c"]', 'Environmental factors that cause skin conditions include sun exposure, irritants, and humidity. Allergic reactions are classified under inflammation rather than environmental factors.'),
  ('overview', 4, 'An adolescent client has pimples, blackheads, whiteheads, and several cysts on the face. The client asks what causes the condition. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is caused by reactivation of a virus.\""}, {"id": "b", "text": "\"It is caused by a fungus spread by pets.\""}, {"id": "c", "text": "\"It is caused by a loss of skin pigment.\""}, {"id": "d", "text": "\"It is caused by hormones, clogged pores, and bacteria.\""}]'::jsonb, '["d"]', 'Acne, which presents with pimples, blackheads, whiteheads, and cysts, is caused by hormones, clogged pores, and bacteria. Loss of skin pigment causes vitiligo, and virus reactivation causes shingles.'),
  ('overview', 5, 'Shortly after eating a new food, a client develops raised, red, itchy welts that appear in one area, fade, and then appear elsewhere. The nurse recognizes these findings as which condition?', '[{"id": "a", "text": "Urticaria (hives)"}, {"id": "b", "text": "Herpes zoster (shingles)"}, {"id": "c", "text": "Tinea corporis (ringworm)"}, {"id": "d", "text": "Psoriasis"}]'::jsonb, '["a"]', 'Hives (urticaria) are raised, red, itchy welts that come and go quickly and can result from an allergic reaction. Ringworm is a red, circular, scaly rash with a clear center rather than welts that come and go.'),
  ('overview', 6, 'A client has recurrent episodes of raised, red, itchy welts that come and go quickly. Which finding in the client''s history is a recognized cause of this condition?', '[{"id": "a", "text": "A recent pregnancy"}, {"id": "b", "text": "A recent stressful event"}, {"id": "c", "text": "Years of outdoor sun exposure"}, {"id": "d", "text": "A family history of moles"}]'::jsonb, '["b"]', 'Hives (urticaria) can be caused by an allergic reaction, stress, or infection. Pregnancy is linked to melasma, sun exposure to melasma and skin cancers, and a family history of moles is not a listed cause of hives.'),
  ('overview', 7, 'An older adult reports burning pain followed by a blistering rash in a band across the right side of the chest only. The nurse recognizes these findings as consistent with which condition?', '[{"id": "a", "text": "Urticaria (hives)"}, {"id": "b", "text": "Impetigo"}, {"id": "c", "text": "Herpes zoster (shingles)"}, {"id": "d", "text": "Tinea corporis (ringworm)"}]'::jsonb, '["c"]', 'Shingles causes a painful blistering rash along nerve paths, usually on one side of the body. Impetigo causes honey-colored crusted sores, usually on the face.'),
  ('overview', 8, 'A client diagnosed with shingles asks the nurse why this happened. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"It is a fungal infection spread by animals.\""}, {"id": "b", "text": "\"It is caused by mites burrowing under the skin.\""}, {"id": "c", "text": "\"It is caused by the body attacking its own skin cells.\""}, {"id": "d", "text": "\"It is caused by reactivation of the varicella-zoster virus.\""}]'::jsonb, '["d"]', 'Shingles (herpes zoster) is caused by reactivation of the varicella-zoster virus. A fungal infection spread by animals describes ringworm, and the body attacking its own skin cells describes psoriasis.'),
  ('overview', 9, 'A client is diagnosed with shingles. Which medication does the nurse anticipate will be prescribed to treat the infection?', '[{"id": "a", "text": "Acyclovir"}, {"id": "b", "text": "Clotrimazole"}, {"id": "c", "text": "Permethrin"}, {"id": "d", "text": "Mupirocin"}]'::jsonb, '["a"]', 'Shingles is a viral condition treated with antiviral medications such as acyclovir or valacyclovir. Clotrimazole is an antifungal, permethrin kills scabies mites, and mupirocin is an antibiotic ointment.'),
  ('overview', 10, 'A client with shingles rates the pain of the rash as 6 on a 0-10 scale. Which topical product does the nurse anticipate for pain management?', '[{"id": "a", "text": "Clotrimazole cream"}, {"id": "b", "text": "Lidocaine cream"}, {"id": "c", "text": "Permethrin cream"}, {"id": "d", "text": "Bacitracin ointment"}]'::jsonb, '["b"]', 'Pain management for shingles includes NSAIDs and lidocaine cream. Clotrimazole is an antifungal, permethrin treats scabies, and bacitracin is an antibiotic ointment for minor bacterial infections.'),
  ('overview', 11, 'A client with active shingles is expecting several visitors. Which visitor should the nurse advise to avoid contact with the client?', '[{"id": "a", "text": "The client''s healthy adult son"}, {"id": "b", "text": "The client''s healthy adult neighbor"}, {"id": "c", "text": "The client''s pregnant daughter"}, {"id": "d", "text": "The client''s healthy spouse"}]'::jsonb, '["c"]', 'Clients with shingles should avoid contact with pregnant women and immunocompromised people. The other visitors are healthy adults without these risks.'),
  ('overview', 12, 'The charge nurse is making assignments on a medical unit. A client with active shingles is being admitted. Which nurse should not be assigned to this client?', '[{"id": "a", "text": "A nurse who works mostly night shifts"}, {"id": "b", "text": "A nurse who was recently hired"}, {"id": "c", "text": "A nurse who just returned from vacation"}, {"id": "d", "text": "A nurse who is currently pregnant"}]'::jsonb, '["d"]', 'Contact between a client with shingles and pregnant women or immunocompromised people should be avoided, so the pregnant nurse should not receive this assignment. Shift, hire date, and recent vacation do not create this risk.'),
  ('overview', 13, 'A child who recently got a new kitten has a red, circular, scaly rash with a clear center on the forearm. The nurse recognizes these findings as consistent with which condition?', '[{"id": "a", "text": "Tinea corporis (ringworm)"}, {"id": "b", "text": "Impetigo"}, {"id": "c", "text": "Psoriasis"}, {"id": "d", "text": "Urticaria (hives)"}]'::jsonb, '["a"]', 'Ringworm is a fungal infection spread by contact or animals that causes a red, circular, scaly rash with a clear center. Hives are raised, itchy welts that come and go quickly rather than a ring-shaped scaly rash.'),
  ('overview', 14, 'A client is diagnosed with a mild, localized case of ringworm on the arm. Which medication does the nurse anticipate?', '[{"id": "a", "text": "Acyclovir tablets"}, {"id": "b", "text": "Clotrimazole cream"}, {"id": "c", "text": "Mupirocin ointment"}, {"id": "d", "text": "Permethrin cream"}]'::jsonb, '["b"]', 'Mild fungal infections such as ringworm are treated with antifungal creams such as clotrimazole or miconazole. Mupirocin is an antibiotic ointment for bacterial infections and does not treat fungus.'),
  ('overview', 15, 'The parent of a child diagnosed with ringworm asks how the child got it. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"A dormant virus became active again.\""}, {"id": "b", "text": "\"Mites burrowed under your child''s skin.\""}, {"id": "c", "text": "\"It is a fungus spread by contact or animals.\""}, {"id": "d", "text": "\"It is caused by hormonal changes.\""}]'::jsonb, '["c"]', 'Ringworm (tinea corporis) is a fungal infection spread by contact or animals, not a worm. Viral reactivation causes shingles, and mites cause scabies.'),
  ('overview', 16, 'The nurse reinforces teaching with a client who has athlete''s foot. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will keep my feet clean and dry.\""}, {"id": "b", "text": "\"I will not share towels with anyone.\""}, {"id": "c", "text": "\"I will apply the antifungal cream as directed.\""}, {"id": "d", "text": "\"I will wear tight socks to keep moisture in.\""}]'::jsonb, '["d"]', 'Fungus thrives in moisture, so clients should keep skin dry and wear loose clothing; keeping moisture in needs correction. Keeping skin dry, not sharing personal items, and using antifungal cream are correct.'),
  ('overview', 17, 'A client has a fungal skin infection that has spread over large areas of the trunk and legs. Which medication does the nurse anticipate?', '[{"id": "a", "text": "Oral terbinafine"}, {"id": "b", "text": "Topical mupirocin"}, {"id": "c", "text": "Oral valacyclovir"}, {"id": "d", "text": "Topical permethrin"}]'::jsonb, '["a"]', 'Widespread fungal infections are treated with oral antifungals such as fluconazole or terbinafine, while antifungal creams are for mild cases. Mupirocin is an antibiotic and valacyclovir is an antiviral.'),
  ('overview', 18, 'A teenager with ringworm plays on a school wrestling team. Which instruction should the nurse give to prevent spread of the infection?', '[{"id": "a", "text": "\"Apply mupirocin ointment to the rash.\""}, {"id": "b", "text": "\"Do not share towels or other personal items.\""}, {"id": "c", "text": "\"Keep the rash moist under a tight covering.\""}, {"id": "d", "text": "\"Take acyclovir until the rash clears.\""}]'::jsonb, '["b"]', 'For fungal infections, clients should keep skin dry and avoid sharing personal items. Keeping the rash moist under a tight covering promotes fungal growth, since fungus thrives in moisture.'),
  ('overview', 19, 'A client who is 6 months pregnant reports new dark patches on the forehead, cheeks, and upper lip. The nurse recognizes these findings as consistent with which condition?', '[{"id": "a", "text": "Vitiligo"}, {"id": "b", "text": "Tinea corporis"}, {"id": "c", "text": "Melasma"}, {"id": "d", "text": "Urticaria"}]'::jsonb, '["c"]', 'Melasma causes dark patches on the face, including the forehead, cheeks, and upper lip, and is linked to hormonal changes such as pregnancy. Vitiligo causes white patches from loss of melanin, the opposite color change.'),
  ('overview', 20, 'A client with melasma asks what can be done to keep the dark patches from getting worse. Which intervention should the nurse emphasize?', '[{"id": "a", "text": "Scheduled phototherapy sessions"}, {"id": "b", "text": "Daily antifungal cream"}, {"id": "c", "text": "Avoiding shared personal items"}, {"id": "d", "text": "Daily use of sunscreen"}]'::jsonb, '["d"]', 'Sunscreen prevents worsening of melasma and vitiligo. Phototherapy is used for vitiligo and psoriasis, and sun exposure is itself a cause of melasma.'),
  ('overview', 21, 'A client who takes birth control pills has developed dark patches on the cheeks and asks why. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Hormonal changes and sun exposure can cause these patches.\""}, {"id": "b", "text": "\"A loss of skin pigment is causing these patches.\""}, {"id": "c", "text": "\"A fungus that grows in moisture is causing these patches.\""}, {"id": "d", "text": "\"Reactivation of a childhood virus is causing these patches.\""}]'::jsonb, '["a"]', 'Melasma is caused by hormonal changes such as pregnancy or birth control, and by sun exposure. Loss of skin pigment causes the white patches of vitiligo, not dark patches.'),
  ('overview', 22, 'A client has white patches of skin on the hands that have slowly spread over the past year. The nurse recognizes these findings as consistent with which condition?', '[{"id": "a", "text": "Melasma"}, {"id": "b", "text": "Vitiligo"}, {"id": "c", "text": "Psoriasis"}, {"id": "d", "text": "Tinea corporis"}]'::jsonb, '["b"]', 'Vitiligo causes white patches of skin that can spread over time. Melasma causes dark patches on the face rather than white patches.'),
  ('overview', 23, 'A client newly diagnosed with vitiligo asks why the white patches developed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Hormonal changes darkened the nearby skin.\""}, {"id": "b", "text": "\"A fungal infection is lightening the skin.\""}, {"id": "c", "text": "\"The skin has lost its melanin, or pigment.\""}, {"id": "d", "text": "\"A virus has reactivated along the nerves.\""}]'::jsonb, '["c"]', 'Vitiligo results from loss of melanin, the skin pigment. Hormonal changes cause melasma, and viral reactivation causes shingles.'),
  ('overview', 24, 'A client with spreading vitiligo asks about treatment options. Which therapy does the nurse anticipate may be recommended?', '[{"id": "a", "text": "Acyclovir tablets"}, {"id": "b", "text": "Permethrin cream"}, {"id": "c", "text": "Clotrimazole cream"}, {"id": "d", "text": "Phototherapy (light therapy)"}]'::jsonb, '["d"]', 'Phototherapy (light therapy) is used for vitiligo and psoriasis. Acyclovir is an antiviral, permethrin treats scabies, and clotrimazole is an antifungal.'),
  ('overview', 25, 'The nurse reinforces teaching with a client who has vitiligo. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"My patches are already white, so I can skip sunscreen.\""}, {"id": "b", "text": "\"The white patches may spread over time.\""}, {"id": "c", "text": "\"I will keep my light therapy appointments.\""}, {"id": "d", "text": "\"I will use moisturizer to prevent dry skin.\""}]'::jsonb, '["a"]', 'Sunscreen prevents worsening of vitiligo, so skipping it needs correction. Vitiligo patches can spread over time, and phototherapy and moisturizers are part of chronic skin condition treatment.'),
  ('overview', 26, 'A client with psoriasis asks why daily moisturizer is part of the treatment plan. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It kills the mites in the scaly patches.\""}, {"id": "b", "text": "\"It helps prevent dryness and itching.\""}, {"id": "c", "text": "\"It prevents spread of the virus to others.\""}, {"id": "d", "text": "\"It cures the fungus that causes the scales.\""}]'::jsonb, '["b"]', 'For chronic skin conditions such as psoriasis, moisturizers prevent dryness and itching. Psoriasis is autoimmune, not caused by mites, a virus, or a fungus.'),
  ('overview', 27, 'An adult client with a history of asthma and seasonal allergies has itchy, dry, red, scaly patches on the hands and elbows. The nurse recognizes these findings as consistent with which condition?', '[{"id": "a", "text": "Scabies"}, {"id": "b", "text": "Tinea corporis"}, {"id": "c", "text": "Atopic dermatitis"}, {"id": "d", "text": "Melasma"}]'::jsonb, '["c"]', 'Eczema (atopic dermatitis) is linked to genetics, allergies, and asthma and causes itchy, dry, red, scaly patches on the hands, elbows, and knees. Ringworm presents as a circular rash with a clear center.'),
  ('overview', 28, 'A client with sensitive skin and eczema asks which bathing and skin-care products to use. Which recommendation by the nurse is appropriate?', '[{"id": "a", "text": "Clotrimazole cream applied daily"}, {"id": "b", "text": "Permethrin cream applied weekly"}, {"id": "c", "text": "Acyclovir ointment applied twice daily"}, {"id": "d", "text": "Hypoallergenic soap and moisturizer"}]'::jsonb, '["d"]', 'Hypoallergenic soaps and moisturizers are recommended for sensitive skin, and eczema is managed by moisturizing and avoiding triggers. Clotrimazole, permethrin, and acyclovir treat fungal, parasitic, and viral conditions.'),
  ('overview', 29, 'A client with an intensely itchy rash asks why the nurse keeps reminding them not to scratch. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Scratching can lead to an infection.\""}, {"id": "b", "text": "\"Scratching can cause skin cancer.\""}, {"id": "c", "text": "\"Scratching can cause pigment loss.\""}, {"id": "d", "text": "\"Scratching can trigger shingles.\""}]'::jsonb, '["a"]', 'Clients are taught to avoid scratching to prevent infection. Pigment loss is the mechanism of vitiligo, and shingles results from virus reactivation, not scratching.'),
  ('overview', 30, 'A child has honey-colored crusted sores on the face caused by a bacterial infection. Which instruction should the nurse give the family to prevent spread?', '[{"id": "a", "text": "\"Apply an antifungal cream to the sores.\""}, {"id": "b", "text": "\"Wash hands and keep the sores covered.\""}, {"id": "c", "text": "\"Leave the sores uncovered to air dry.\""}, {"id": "d", "text": "\"Give acyclovir until the crusts fall off.\""}]'::jsonb, '["b"]', 'Honey-colored crusted sores on the face indicate impetigo, and bacterial infections require handwashing and covering sores to prevent spread. Leaving sores uncovered contradicts this teaching.'),
  ('overview', 31, 'A client has a few small, minor areas of folliculitis on the thigh. Which medication does the nurse anticipate?', '[{"id": "a", "text": "Oral fluconazole"}, {"id": "b", "text": "Oral acyclovir"}, {"id": "c", "text": "Bacitracin ointment"}, {"id": "d", "text": "Permethrin cream"}]'::jsonb, '["c"]', 'Minor bacterial infections such as folliculitis are treated with antibiotic ointments such as mupirocin or bacitracin. Fluconazole is an antifungal and acyclovir is an antiviral.'),
  ('overview', 32, 'A client has a severe bacterial skin infection involving a large area of the back. Which medication does the nurse anticipate?', '[{"id": "a", "text": "Topical clotrimazole"}, {"id": "b", "text": "Oral valacyclovir"}, {"id": "c", "text": "Topical permethrin"}, {"id": "d", "text": "Oral cephalexin"}]'::jsonb, '["d"]', 'Severe bacterial skin infections are treated with oral antibiotics such as cephalexin or clindamycin, while antibiotic ointments are for minor cases. Clotrimazole is an antifungal and valacyclovir is an antiviral.'),
  ('overview', 33, 'The nurse observes an unlicensed assistive personnel (UAP) caring for a child with impetigo. Which action by the UAP requires correction?', '[{"id": "a", "text": "Touching the sores, then the bed rail, without washing hands"}, {"id": "b", "text": "Washing hands after providing care to the child"}, {"id": "c", "text": "Encouraging the child to keep the sores covered"}, {"id": "d", "text": "Gently cleaning the skin around the affected areas"}]'::jsonb, '["a"]', 'For bacterial infections, affected areas are kept clean, lesions are not touched, and hands are washed to prevent spread. Touching the sores and then the environment without handwashing spreads infection.'),
  ('overview', 34, 'A client reports intense itching that is worse at night, and the nurse notes small red bumps on the hands and wrists. Scabies is diagnosed. Which medication does the nurse anticipate?', '[{"id": "a", "text": "Clotrimazole cream"}, {"id": "b", "text": "Permethrin cream"}, {"id": "c", "text": "Acyclovir tablets"}, {"id": "d", "text": "Mupirocin ointment"}]'::jsonb, '["b"]', 'Scabies causes intense itching and small red bumps that are worse at night, and permethrin cream kills scabies mites. Clotrimazole treats fungal infections, not mites.'),
  ('overview', 35, 'A parent whose child has scabies asks why everyone in the home must be treated when only the child itches. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It keeps the virus from reactivating.\""}, {"id": "b", "text": "\"It prevents the fungus from spreading.\""}, {"id": "c", "text": "\"It prevents reinfection in the home.\""}, {"id": "d", "text": "\"It keeps the child''s skin from drying.\""}]'::jsonb, '["c"]', 'All household members are treated for parasitic conditions such as scabies to prevent reinfection. Scabies is caused by mites, not by a virus or fungus.'),
  ('overview', 36, 'A school-age child is treated for head lice. Which instruction should the nurse give the parents about the child''s clothing and bedding?', '[{"id": "a", "text": "\"Wash them in cold water.\""}, {"id": "b", "text": "\"Air them outside for an hour.\""}, {"id": "c", "text": "\"Shake them out before use.\""}, {"id": "d", "text": "\"Wash them in hot water.\""}]'::jsonb, '["d"]', 'For parasitic conditions such as scabies and lice, clothes and bedding are washed in hot water. Cold-water washing reverses the correct instruction.'),
  ('overview', 37, 'The nurse is performing a skin assessment. Which mole finding is most concerning for skin cancer?', '[{"id": "a", "text": "A mole with uneven, irregular edges"}, {"id": "b", "text": "A round mole with a smooth border"}, {"id": "c", "text": "A mole that is one uniform color"}, {"id": "d", "text": "A 3-mm mole unchanged for years"}]'::jsonb, '["a"]', 'Border irregularity, meaning uneven edges, is one of the ABCDE warning signs of skin cancer. A smooth border, a single uniform color, a diameter under 6 mm, and no change do not meet the ABCDE warning criteria.'),
  ('overview', 38, 'The nurse measures several moles on a client''s back. Based on the ABCDE rule, which measurement meets the diameter warning sign for skin cancer?', '[{"id": "a", "text": "2 mm"}, {"id": "b", "text": "4 mm"}, {"id": "c", "text": "5 mm"}, {"id": "d", "text": "8 mm"}]'::jsonb, '["d"]', 'The ABCDE rule lists a diameter greater than 6 mm as a warning sign. Moles of 2, 4, and 5 mm are below this threshold.'),
  ('overview', 39, 'A client reports that a mole on the arm has recently started to itch and occasionally bleeds. Which ABCDE criterion does this finding represent?', '[{"id": "a", "text": "Asymmetry"}, {"id": "b", "text": "Border irregularity"}, {"id": "c", "text": "Evolving"}, {"id": "d", "text": "Color changes"}]'::jsonb, '["c"]', 'Evolving refers to a mole that is growing, itching, bleeding, or changing. Asymmetry means one side looks different, and border irregularity means uneven edges.'),
  ('overview', 40, 'The nurse has taught a client how to perform a skin self-examination using the ABCDE rule. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"A mole with one half unlike the other is a concern.\""}, {"id": "b", "text": "\"A mole with uneven edges should be checked.\""}, {"id": "c", "text": "\"A mole that is growing should be checked.\""}, {"id": "d", "text": "\"A mole with several colors is fine if it is small.\""}]'::jsonb, '["d"]', 'Color change, meaning multiple colors in one mole, is a warning sign regardless of size, so this statement needs correction. Asymmetry, uneven edges, and growth are correctly identified warning signs.'),
  ('overview', 41, 'A fair-skinned older adult with a long history of outdoor work has a slow-growing, waxy bump with a pearly border on the nose. The nurse recognizes these findings as consistent with which condition?', '[{"id": "a", "text": "Basal cell carcinoma"}, {"id": "b", "text": "Squamous cell carcinoma"}, {"id": "c", "text": "Melanoma"}, {"id": "d", "text": "Melasma"}]'::jsonb, '["a"]', 'Basal cell carcinoma appears as a waxy bump with a pearly border, is slow-growing, and is linked to fair skin and long-term sun exposure. Squamous cell carcinoma appears as a scaly, red patch or ulcer.'),
  ('overview', 42, 'A client has a scaly, red, ulcerated patch that developed at the site of a long-standing chronic wound on the leg. The nurse suspects which skin cancer?', '[{"id": "a", "text": "Basal cell carcinoma"}, {"id": "b", "text": "Squamous cell carcinoma"}, {"id": "c", "text": "Melanoma"}, {"id": "d", "text": "Tinea corporis"}]'::jsonb, '["b"]', 'Squamous cell carcinoma is caused by sun exposure and chronic wounds and appears as a scaly, red patch or ulcer that can spread. Basal cell carcinoma appears as a waxy bump with a pearly border.'),
  ('overview', 43, 'During a routine examination, the nurse notes an irregular dark mole on a client''s back that the client says has changed in size, color, and shape. What is the nurse''s most appropriate action?', '[{"id": "a", "text": "Recommend an antifungal cream and recheck"}, {"id": "b", "text": "Reassure the client that moles often change"}, {"id": "c", "text": "Advocate for an urgent dermatology referral"}, {"id": "d", "text": "Plan to reassess the mole in one year"}]'::jsonb, '["c"]', 'An irregular dark mole that changes in size, color, or shape suggests melanoma, which requires urgent dermatology referral. Reassurance or delayed reassessment ignores the evolving warning sign.'),
  ('overview', 44, 'The nurse is screening clients at a community health fair. Which client has the highest risk for melanoma?', '[{"id": "a", "text": "A client with eczema and asthma"}, {"id": "b", "text": "A client who recently had shingles"}, {"id": "c", "text": "A client with melasma during pregnancy"}, {"id": "d", "text": "A fair-skinned client who uses tanning beds"}]'::jsonb, '["d"]', 'Risk factors for melanoma include fair skin, tanning beds, many moles, and family history. Eczema, recent shingles, and melasma are not listed melanoma risk factors.'),
  ('overview', 45, 'The nurse has taught a group of college students about preventing skin cancer. Which statement by a student indicates understanding?', '[{"id": "a", "text": "\"I will use sunscreen and stop using tanning beds.\""}, {"id": "b", "text": "\"Tanning beds are a safe alternative to the sun.\""}, {"id": "c", "text": "\"Moles larger than 6 mm are a normal finding.\""}, {"id": "d", "text": "\"Only moles that are painful need to be checked.\""}]'::jsonb, '["a"]', 'Sunscreen and avoiding tanning beds prevent skin cancer. Tanning beds are a melanoma risk factor, and a diameter greater than 6 mm is an ABCDE warning sign.'),
  ('overview', 46, 'A client diagnosed with basal cell carcinoma on the face asks how it will be treated. Which treatment does the nurse anticipate?', '[{"id": "a", "text": "Antifungal cream"}, {"id": "b", "text": "Surgical removal such as Mohs surgery"}, {"id": "c", "text": "Permethrin cream"}, {"id": "d", "text": "Oral antiviral medication"}]'::jsonb, '["b"]', 'Skin cancers are treated with surgical removal, such as excision or Mohs surgery. Antifungal cream, permethrin, and antivirals treat fungal, parasitic, and viral conditions.'),
  ('overview', 47, 'A client has advanced melanoma that has spread. In addition to surgery, which treatment does the nurse anticipate?', '[{"id": "a", "text": "Topical corticosteroids"}, {"id": "b", "text": "Oral antifungal therapy"}, {"id": "c", "text": "Chemotherapy or radiation"}, {"id": "d", "text": "Daily moisturizers"}]'::jsonb, '["c"]', 'Chemotherapy or radiation is used for advanced skin cancers. Topical corticosteroids and moisturizers are treatments for chronic conditions such as eczema and psoriasis.'),
  ('overview', 48, 'The nurse is reviewing the history of a fair-skinned client newly diagnosed with squamous cell carcinoma. Which history finding is a recognized risk factor for this cancer?', '[{"id": "a", "text": "A history of asthma"}, {"id": "b", "text": "A recent pregnancy"}, {"id": "c", "text": "A recent episode of hives"}, {"id": "d", "text": "A history of HPV infection"}]'::jsonb, '["d"]', 'Risk factors for squamous cell carcinoma include fair skin, sun exposure, and HPV infection. Pregnancy is linked to melasma, and asthma and hives are not listed squamous cell carcinoma risk factors.'),
  ('overview', 49, 'A nursing student asks how the appearance of basal cell carcinoma differs from melanoma. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"BCC is a slow-growing waxy bump; melanoma is a changing dark mole.\""}, {"id": "b", "text": "\"BCC is a changing dark mole; melanoma is a slow-growing waxy bump.\""}, {"id": "c", "text": "\"BCC is a white patch that spreads; melanoma is a ring-shaped rash.\""}, {"id": "d", "text": "\"BCC is a scaly ulcer from a wound; melanoma is a pearly bump.\""}]'::jsonb, '["a"]', 'Basal cell carcinoma is a slow-growing waxy bump with a pearly border, whereas melanoma is an irregular dark mole that changes in size, color, or shape. Option B reverses the two cancers.'),
  ('overview', 50, 'A client has a painful recurrence of herpes simplex lesions. Which medication does the nurse anticipate will be prescribed?', '[{"id": "a", "text": "Clotrimazole"}, {"id": "b", "text": "Valacyclovir"}, {"id": "c", "text": "Mupirocin"}, {"id": "d", "text": "Permethrin"}]'::jsonb, '["b"]', 'Herpes simplex is a viral condition treated with antivirals such as acyclovir or valacyclovir. Clotrimazole is an antifungal and mupirocin is an antibacterial ointment.'),
  ('derm_cellulitis', 1, 'A client reports an itchy red rash with small blisters on both forearms two days after clearing brush that contained poison ivy. Which type of dermatitis does the nurse suspect?', '[{"id": "a", "text": "Contact dermatitis"}, {"id": "b", "text": "Atopic dermatitis"}, {"id": "c", "text": "Seborrheic dermatitis"}, {"id": "d", "text": "Stasis dermatitis"}]'::jsonb, '["a"]', 'Contact dermatitis is caused by touching an irritant or allergen such as poison ivy and produces a red, itchy rash that can blister when severe. Atopic dermatitis is linked to genetics, allergies, and asthma rather than a specific contact exposure.'),
  ('derm_cellulitis', 2, 'A school-age child with asthma, whose parent also has eczema, has itchy, dry, red, scaly patches on the elbows and knees. The nurse recognizes these findings as consistent with which condition?', '[{"id": "a", "text": "Contact dermatitis"}, {"id": "b", "text": "Atopic dermatitis"}, {"id": "c", "text": "Stasis dermatitis"}, {"id": "d", "text": "Cellulitis"}]'::jsonb, '["b"]', 'Atopic dermatitis (eczema) is linked to genetics, allergies, and asthma and causes itchy, dry, red, scaly patches on the face, hands, elbows, and knees. Stasis dermatitis results from poor blood flow and affects the lower legs.'),
  ('derm_cellulitis', 3, 'An adult with oily skin who reports recent stress has greasy, yellowish, scaly patches on the scalp and chest. Which condition do these findings suggest?', '[{"id": "a", "text": "Atopic dermatitis"}, {"id": "b", "text": "Contact dermatitis"}, {"id": "c", "text": "Seborrheic dermatitis"}, {"id": "d", "text": "Stasis dermatitis"}]'::jsonb, '["c"]', 'Seborrheic dermatitis is associated with oily skin, stress, and genetics and causes greasy, yellowish, scaly patches on the scalp, face, and chest. Atopic dermatitis produces dry rather than greasy scaly patches.'),
  ('derm_cellulitis', 4, 'An older adult with poor circulation in the legs has swollen, discolored skin with open sores on both lower legs. Which type of dermatitis is most likely?', '[{"id": "a", "text": "Atopic dermatitis"}, {"id": "b", "text": "Contact dermatitis"}, {"id": "c", "text": "Seborrheic dermatitis"}, {"id": "d", "text": "Stasis dermatitis"}]'::jsonb, '["d"]', 'Stasis dermatitis results from poor blood flow, usually in the legs, and causes swollen, discolored skin with open sores on the lower legs. Contact dermatitis follows exposure to an irritant or allergen.'),
  ('derm_cellulitis', 5, 'The nurse is teaching a client newly diagnosed with seborrheic dermatitis of the scalp. Which product does the nurse expect the provider to recommend?', '[{"id": "a", "text": "Ketoconazole antifungal shampoo"}, {"id": "b", "text": "Cephalexin oral capsules"}, {"id": "c", "text": "Fragranced moisturizing lotion"}, {"id": "d", "text": "Vancomycin intravenous infusion"}]'::jsonb, '["a"]', 'Seborrheic dermatitis is caused by yeast overgrowth and is treated with antifungal shampoos such as ketoconazole or selenium sulfide. Cephalexin is an antibiotic for cellulitis, and dermatitis is not an infection requiring antibiotics.'),
  ('derm_cellulitis', 6, 'Which instruction should the nurse include when teaching a client with stasis dermatitis of the lower legs?', '[{"id": "a", "text": "\"Keep your legs lowered below heart level when sitting.\""}, {"id": "b", "text": "\"Elevate your legs and wear your compression stockings.\""}, {"id": "c", "text": "\"Wash your legs with an antifungal shampoo every day.\""}, {"id": "d", "text": "\"Apply a scented lotion directly onto the open sores.\""}]'::jsonb, '["b"]', 'Stasis dermatitis is treated by elevating the legs and wearing compression stockings to improve circulation. Lowering the legs would not improve the poor blood flow that causes the condition.'),
  ('derm_cellulitis', 7, 'A coworker of a client with atopic dermatitis asks the nurse whether the rash can spread to other people. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Yes, it spreads through direct skin-to-skin contact.\""}, {"id": "b", "text": "\"Yes, until antibiotics have been taken for a full day.\""}, {"id": "c", "text": "\"No, it is inflammation of the skin and is not contagious.\""}, {"id": "d", "text": "\"No, but only once the blisters have dried completely.\""}]'::jsonb, '["c"]', 'Dermatitis is inflammation of the skin caused by irritants, allergens, or underlying conditions, and it is not contagious. Antibiotics are not part of dermatitis treatment because it is not an infection.'),
  ('derm_cellulitis', 8, 'The nurse teaches a client with contact dermatitis about treatment. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will stop using the harsh soap that caused this.\""}, {"id": "b", "text": "\"I will apply a fragrance-free lotion every day.\""}, {"id": "c", "text": "\"I will try my best not to scratch the rash.\""}, {"id": "d", "text": "\"I will need antibiotics to clear up this rash.\""}]'::jsonb, '["d"]', 'Dermatitis is inflammation, not an infection, so antibiotics are not needed. Avoiding triggers, daily fragrance-free moisturizer, and avoiding scratching are all correct dermatitis care.'),
  ('derm_cellulitis', 9, 'Which moisturizer instruction is most appropriate for a client with atopic dermatitis?', '[{"id": "a", "text": "\"Apply a fragrance-free lotion every day.\""}, {"id": "b", "text": "\"Apply a scented lotion only at bedtime.\""}, {"id": "c", "text": "\"Use lotion only when blisters appear.\""}, {"id": "d", "text": "\"Avoid lotion so the skin can breathe.\""}]'::jsonb, '["a"]', 'Daily moisturizing with fragrance-free lotion prevents dry skin in dermatitis. Scented products can act as irritants, and avoiding lotion would allow the skin to become dry and cracked.'),
  ('derm_cellulitis', 10, 'A client with eczema is prescribed topical hydrocortisone and asks what the cream will do. Which response by the nurse is correct?', '[{"id": "a", "text": "\"It kills the bacteria that are causing the rash.\""}, {"id": "b", "text": "\"It reduces the redness and itching of the rash.\""}, {"id": "c", "text": "\"It treats the yeast overgrowth on your skin.\""}, {"id": "d", "text": "\"It improves the blood flow to your lower legs.\""}]'::jsonb, '["b"]', 'Topical steroids such as hydrocortisone reduce redness and itching in dermatitis. Yeast overgrowth is treated with antifungal shampoos, not steroids.'),
  ('derm_cellulitis', 11, 'A client with contact dermatitis reports itching that keeps them awake at night. Which medication does the nurse anticipate to relieve the itching?', '[{"id": "a", "text": "Dicloxacillin"}, {"id": "b", "text": "Ketoconazole"}, {"id": "c", "text": "Diphenhydramine"}, {"id": "d", "text": "Ceftriaxone"}]'::jsonb, '["c"]', 'Antihistamines such as diphenhydramine help relieve the itching of dermatitis. Dicloxacillin and ceftriaxone are antibiotics for cellulitis, and dermatitis does not need antibiotics.'),
  ('derm_cellulitis', 12, 'A parent asks why it is important to keep a child with eczema from scratching the rash. Which explanation by the nurse is best?', '[{"id": "a", "text": "\"Scratching makes the rash contagious to siblings.\""}, {"id": "b", "text": "\"Scratching causes yeast to grow on the scalp.\""}, {"id": "c", "text": "\"Scratching blocks the blood flow to the legs.\""}, {"id": "d", "text": "\"Scratching can lead to an infection of the skin.\""}]'::jsonb, '["d"]', 'Avoiding scratching is a dermatitis priority because it prevents infection. Dermatitis is not contagious, so scratching does not make it spread to others.'),
  ('derm_cellulitis', 13, 'A client asks the nurse how cellulitis develops. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Bacteria enter through a break such as a cut or bite.\""}, {"id": "b", "text": "\"An allergen touches the skin and causes inflammation.\""}, {"id": "c", "text": "\"Yeast overgrows on the oily areas of the skin.\""}, {"id": "d", "text": "\"Poor blood flow causes the skin to break down.\""}]'::jsonb, '["a"]', 'Cellulitis develops when Streptococcus or Staphylococcus bacteria enter through a cut, wound, or insect bite. An allergen touching the skin causes contact dermatitis, not cellulitis.'),
  ('derm_cellulitis', 14, 'A client reports that an insect bite on the lower leg has become a red, swollen, warm, painful area that is spreading quickly. Which condition does the nurse suspect?', '[{"id": "a", "text": "Contact dermatitis"}, {"id": "b", "text": "Cellulitis"}, {"id": "c", "text": "Atopic dermatitis"}, {"id": "d", "text": "Seborrheic dermatitis"}]'::jsonb, '["b"]', 'Cellulitis causes red, swollen, warm skin with a painful area that spreads quickly, often after bacteria enter through an insect bite. Contact dermatitis presents as an itchy, burning rash after touching an irritant.'),
  ('derm_cellulitis', 15, 'The nurse is assessing a client being treated for cellulitis of the forearm. Which finding should the nurse report to the provider immediately?', '[{"id": "a", "text": "Mild warmth over the reddened forearm area"}, {"id": "b", "text": "Tenderness when the reddened area is touched"}, {"id": "c", "text": "Red streaks spreading up the arm toward the chest"}, {"id": "d", "text": "Swelling of the skin over the affected forearm"}]'::jsonb, '["c"]', 'Red streaks spreading toward the heart signal lymphangitis, which is an emergency. Warmth, tenderness, and swelling are expected findings of cellulitis.'),
  ('derm_cellulitis', 16, 'A client with cellulitis of the leg develops red streaks extending from the wound up toward the groin. The nurse interprets this finding as which complication?', '[{"id": "a", "text": "Stasis dermatitis"}, {"id": "b", "text": "Contact dermatitis"}, {"id": "c", "text": "Seborrheic dermatitis"}, {"id": "d", "text": "Lymphangitis"}]'::jsonb, '["d"]', 'Red streaks spreading toward the heart signal lymphangitis, an emergency complication of cellulitis. Stasis dermatitis is related to poor leg circulation and causes discolored skin with open sores, not red streaks.'),
  ('derm_cellulitis', 17, 'A client with mild cellulitis, without suspected MRSA, will be discharged on oral therapy. Which medication does the nurse anticipate?', '[{"id": "a", "text": "Cephalexin"}, {"id": "b", "text": "Vancomycin"}, {"id": "c", "text": "Ketoconazole"}, {"id": "d", "text": "Diphenhydramine"}]'::jsonb, '["a"]', 'Cephalexin or dicloxacillin is first-line oral therapy for mild cellulitis. Vancomycin is an IV antibiotic reserved for MRSA in severe or spreading infection.'),
  ('derm_cellulitis', 18, 'The provider suspects MRSA in a client with mild cellulitis that will be treated with oral medication. Which antibiotic does the nurse anticipate?', '[{"id": "a", "text": "Dicloxacillin"}, {"id": "b", "text": "Clindamycin"}, {"id": "c", "text": "Ceftriaxone"}, {"id": "d", "text": "Hydrocortisone"}]'::jsonb, '["b"]', 'Clindamycin or doxycycline is used orally when MRSA is suspected. Dicloxacillin is the first-line choice for mild cases when MRSA is not suspected.'),
  ('derm_cellulitis', 19, 'A client is admitted with severe, spreading cellulitis, and MRSA is confirmed. Which IV medication does the nurse expect to administer?', '[{"id": "a", "text": "Cephalexin"}, {"id": "b", "text": "Selenium sulfide"}, {"id": "c", "text": "Vancomycin"}, {"id": "d", "text": "Betamethasone"}]'::jsonb, '["c"]', 'IV vancomycin is used for MRSA in severe or spreading cellulitis. Cephalexin is an oral first-line antibiotic for mild cases.'),
  ('derm_cellulitis', 20, 'A client is hospitalized with a severe streptococcal cellulitis that requires IV therapy. Which medication does the nurse anticipate?', '[{"id": "a", "text": "Doxycycline by mouth"}, {"id": "b", "text": "Dicloxacillin by mouth"}, {"id": "c", "text": "Ketoconazole shampoo"}, {"id": "d", "text": "Ceftriaxone intravenously"}]'::jsonb, '["d"]', 'IV ceftriaxone is used for severe strep infections. Oral doxycycline is an option for mild cellulitis when MRSA is suspected, not for severe spreading infection.'),
  ('derm_cellulitis', 21, 'A client is admitted with cellulitis of the right lower leg. How should the nurse position the affected leg?', '[{"id": "a", "text": "Elevated on pillows"}, {"id": "b", "text": "Dangling over the bed edge"}, {"id": "c", "text": "Flat with the knee bent"}, {"id": "d", "text": "Crossed over the other leg"}]'::jsonb, '["a"]', 'Elevating the affected area reduces swelling in cellulitis. Dangling the leg over the bed edge places it in a dependent position, the opposite of elevation.'),
  ('derm_cellulitis', 22, 'A client with cellulitis of the hand asks what can be taken for the pain. Which medication does the nurse anticipate the provider will suggest?', '[{"id": "a", "text": "Diphenhydramine"}, {"id": "b", "text": "Acetaminophen"}, {"id": "c", "text": "Ketoconazole"}, {"id": "d", "text": "Hydrocortisone"}]'::jsonb, '["b"]', 'Pain control in cellulitis includes acetaminophen or ibuprofen. Diphenhydramine is an antihistamine used for itching in dermatitis.'),
  ('derm_cellulitis', 23, 'The nurse teaches a client being discharged on oral antibiotics for cellulitis. Which statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will keep my leg propped up when I sit.\""}, {"id": "b", "text": "\"I will watch my leg for any red streaks.\""}, {"id": "c", "text": "\"I will stop the pills once the redness fades.\""}, {"id": "d", "text": "\"I will go to the ER if I get confused or dizzy.\""}]'::jsonb, '["c"]', 'A cellulitis priority is encouraging the full course of antibiotics, so stopping when redness fades is incorrect. Elevating the leg, watching for red streaks, and seeking emergency care for confusion or dizziness are correct.'),
  ('derm_cellulitis', 24, 'A client being treated at home for cellulitis calls the clinic. Which client report requires the nurse to direct the client to the emergency department?', '[{"id": "a", "text": "\"The area still feels a little warm.\""}, {"id": "b", "text": "\"My leg is less swollen than yesterday.\""}, {"id": "c", "text": "\"The skin is still pink around the cut.\""}, {"id": "d", "text": "\"I have a high fever and feel confused.\""}]'::jsonb, '["d"]', 'High fever, confusion, or dizziness signals sepsis and is a reason to go to the ER. Lingering warmth or pinkness without these findings is not listed as an emergency sign.'),
  ('derm_cellulitis', 25, 'A client has been taking oral antibiotics for cellulitis for 3 days. Which finding indicates the client should go to the emergency department?', '[{"id": "a", "text": "Redness that is rapidly growing larger"}, {"id": "b", "text": "Mild tenderness at the original wound"}, {"id": "c", "text": "Warmth that is slowly decreasing"}, {"id": "d", "text": "Swelling that improves with elevation"}]'::jsonb, '["a"]', 'Rapidly growing redness despite antibiotics is a reason to go to the ER. Decreasing warmth and swelling that improves with elevation suggest the condition is not worsening.'),
  ('derm_cellulitis', 26, 'A family member of a client with cellulitis asks whether they can catch the infection. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Yes, so avoid touching the client''s skin.\""}, {"id": "b", "text": "\"No, but it can spread inside the client''s body.\""}, {"id": "c", "text": "\"Yes, until the client''s temperature is normal.\""}, {"id": "d", "text": "\"No, because it is caused by an allergy.\""}]'::jsonb, '["b"]', 'Cellulitis is not contagious person-to-person, but it can spread inside the body. It is a bacterial infection, not an allergic reaction.'),
  ('derm_cellulitis', 27, 'A client asks why cellulitis must be treated when it is "just a skin infection." The nurse explains that untreated cellulitis can lead to which complications?', '[{"id": "a", "text": "Eczema and seborrheic dermatitis"}, {"id": "b", "text": "Contact dermatitis and dandruff"}, {"id": "c", "text": "Sepsis or a bone infection"}, {"id": "d", "text": "Stasis dermatitis and leg sores"}]'::jsonb, '["c"]', 'Untreated cellulitis can spread inside the body and cause sepsis or bone infection. The dermatitis types listed are inflammatory conditions with their own causes, not complications of cellulitis.'),
  ('derm_cellulitis', 28, 'A client with cellulitis of the foot develops fever and chills. The nurse interprets these findings as an indication of which situation?', '[{"id": "a", "text": "The rash is actually contact dermatitis"}, {"id": "b", "text": "The skin is healing as expected"}, {"id": "c", "text": "The infection is limited to the foot"}, {"id": "d", "text": "The infection is spreading"}]'::jsonb, '["d"]', 'Fever and chills occur in cellulitis when the infection spreads. They do not indicate healing or a localized infection.'),
  ('derm_cellulitis', 29, 'Which finding does the nurse expect when assessing the affected skin of a client with cellulitis?', '[{"id": "a", "text": "Blistering skin with pus"}, {"id": "b", "text": "Greasy, yellow scalp scales"}, {"id": "c", "text": "Dry, scaly elbow patches"}, {"id": "d", "text": "Cool, pale, painless skin"}]'::jsonb, '["a"]', 'In cellulitis the skin may blister or develop pus. Greasy yellow scales are seen in seborrheic dermatitis, and cellulitis skin is red, warm, and painful rather than cool and painless.'),
  ('derm_cellulitis', 30, 'The nurse is caring for four clients with skin conditions. Which client does the nurse expect to receive antibiotic therapy?', '[{"id": "a", "text": "A client with atopic dermatitis of the hands"}, {"id": "b", "text": "A client with cellulitis after a leg wound"}, {"id": "c", "text": "A client with seborrheic dermatitis of the scalp"}, {"id": "d", "text": "A client with contact dermatitis from soap"}]'::jsonb, '["b"]', 'Cellulitis is a bacterial infection and needs antibiotics. Dermatitis is inflammation, not an infection, so no antibiotics are needed.'),
  ('derm_cellulitis', 31, 'A client develops contact dermatitis on the hands after switching to a new dish soap. Which teaching is the priority?', '[{"id": "a", "text": "\"Apply an antifungal shampoo to your hands.\""}, {"id": "b", "text": "\"Take antibiotics until the rash is gone.\""}, {"id": "c", "text": "\"Stop using the soap that irritates your skin.\""}, {"id": "d", "text": "\"Keep your hands lowered below your heart.\""}]'::jsonb, '["c"]', 'Dermatitis treatment begins with avoiding triggers, such as stopping irritating soaps. Antibiotics are not needed because dermatitis is not an infection.'),
  ('derm_cellulitis', 32, 'Where does the nurse expect to find lesions when assessing a client with atopic dermatitis?', '[{"id": "a", "text": "Scalp, face, and chest"}, {"id": "b", "text": "Lower legs only"}, {"id": "c", "text": "Around a single wound"}, {"id": "d", "text": "Face, hands, elbows, and knees"}]'::jsonb, '["d"]', 'Atopic dermatitis causes itchy, dry, red, scaly patches on the face, hands, elbows, and knees. The scalp, face, and chest are typical sites of seborrheic dermatitis.'),
  ('derm_cellulitis', 33, 'A client with seborrheic dermatitis asks what contributes to the condition. Which factors does the nurse identify?', '[{"id": "a", "text": "Oily skin and stress"}, {"id": "b", "text": "Insect bites and cuts"}, {"id": "c", "text": "Poor leg circulation"}, {"id": "d", "text": "Poison ivy contact"}]'::jsonb, '["a"]', 'Seborrheic dermatitis involves yeast overgrowth on the skin associated with oily skin, stress, and genetics. Insect bites and cuts are entry points for cellulitis bacteria.'),
  ('derm_cellulitis', 34, 'A client with greasy, dandruff-like scaling of the scalp is diagnosed with seborrheic dermatitis. Which shampoo ingredient does the nurse expect in the treatment plan?', '[{"id": "a", "text": "Hydrocortisone"}, {"id": "b", "text": "Selenium sulfide"}, {"id": "c", "text": "Diphenhydramine"}, {"id": "d", "text": "Doxycycline"}]'::jsonb, '["b"]', 'Seborrheic dermatitis is treated with antifungal shampoos such as ketoconazole or selenium sulfide. Doxycycline is an antibiotic option for cellulitis when MRSA is suspected.'),
  ('derm_cellulitis', 35, 'Which client history is most consistent with a diagnosis of stasis dermatitis?', '[{"id": "a", "text": "Recent contact with poison ivy"}, {"id": "b", "text": "Family history of asthma"}, {"id": "c", "text": "Poor blood flow in the legs"}, {"id": "d", "text": "Oily skin and recent stress"}]'::jsonb, '["c"]', 'Stasis dermatitis is caused by poor blood flow, usually in the legs. Poison ivy contact causes contact dermatitis, and a family history of asthma is linked to atopic dermatitis.'),
  ('derm_cellulitis', 36, 'Which nursing priority is most important for a client hospitalized with spreading cellulitis?', '[{"id": "a", "text": "Applying moisturizer to prevent dry skin"}, {"id": "b", "text": "Teaching avoidance of skin triggers"}, {"id": "c", "text": "Giving antihistamines for itching"}, {"id": "d", "text": "Monitoring for signs of sepsis"}]'::jsonb, '["d"]', 'Monitoring for signs of sepsis is a cellulitis nursing priority. Moisturizer, trigger avoidance, and antihistamines are priorities for dermatitis.'),
  ('derm_cellulitis', 37, 'The nurse observes a UAP caring for a client with cellulitis of the lower leg. Which action by the UAP requires correction?', '[{"id": "a", "text": "Lowering the affected leg below heart level"}, {"id": "b", "text": "Placing pillows under the affected leg"}, {"id": "c", "text": "Reporting red streaks on the leg to the nurse"}, {"id": "d", "text": "Reporting a new fever to the nurse"}]'::jsonb, '["a"]', 'The affected area should be kept elevated in cellulitis to reduce swelling, so lowering the leg requires correction. Reporting red streaks and fever is appropriate because these signal worsening infection.'),
  ('derm_cellulitis', 38, 'A client with dermatitis reports severe itching. Which medication does the nurse anticipate?', '[{"id": "a", "text": "An oral antibiotic"}, {"id": "b", "text": "An oral antihistamine"}, {"id": "c", "text": "An antifungal shampoo"}, {"id": "d", "text": "An IV antibiotic"}]'::jsonb, '["b"]', 'Antihistamines are a dermatitis priority for severe itching. Antibiotics are not needed because dermatitis is inflammation rather than infection.'),
  ('derm_cellulitis', 39, 'Which finding indicates that a client''s contact dermatitis is severe?', '[{"id": "a", "text": "Greasy yellow scales"}, {"id": "b", "text": "Dry patches on the knees"}, {"id": "c", "text": "Blisters within the rash"}, {"id": "d", "text": "Open sores on the shins"}]'::jsonb, '["c"]', 'Contact dermatitis causes a red, itchy, burning rash with blisters if severe. Open sores on the lower legs are a feature of stasis dermatitis.'),
  ('derm_cellulitis', 40, 'A parent asks the nurse why their child developed atopic dermatitis. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is caused by a bacterial skin infection.\""}, {"id": "b", "text": "\"It results from yeast growing on oily skin.\""}, {"id": "c", "text": "\"It is caused by poor blood flow in the legs.\""}, {"id": "d", "text": "\"It often runs in families with allergies or asthma.\""}]'::jsonb, '["d"]', 'Atopic dermatitis is linked to genetics, allergies, and asthma and often runs in families. Yeast overgrowth on oily skin causes seborrheic dermatitis.'),
  ('derm_cellulitis', 41, 'A nursing student states that cellulitis occurs only on the legs. Which response by the nurse educator is correct?', '[{"id": "a", "text": "\"It often affects the legs but can occur anywhere.\""}, {"id": "b", "text": "\"It occurs only on the arms and the face.\""}, {"id": "c", "text": "\"It occurs only where skin is oily, like the scalp.\""}, {"id": "d", "text": "\"It occurs only in the lower legs of older adults.\""}]'::jsonb, '["a"]', 'Cellulitis causes red, swollen, warm skin that is often on the legs but can occur anywhere. Oily skin areas such as the scalp are associated with seborrheic dermatitis.'),
  ('derm_cellulitis', 42, 'Which client does the nurse identify as at greatest risk for developing cellulitis?', '[{"id": "a", "text": "A client with a family history of eczema"}, {"id": "b", "text": "A client with an open cut on the foot"}, {"id": "c", "text": "A client with oily skin on the face"}, {"id": "d", "text": "A client who recently switched soaps"}]'::jsonb, '["b"]', 'Cellulitis bacteria enter through a cut, wound, or insect bite. A family history of eczema relates to atopic dermatitis, and a new soap relates to contact dermatitis.'),
  ('derm_cellulitis', 43, 'While assessing a client with an infected leg wound, the nurse notes new red streaks spreading up the thigh. What is the nurse''s priority action?', '[{"id": "a", "text": "Apply moisturizer to the streaks"}, {"id": "b", "text": "Recheck the leg in four hours"}, {"id": "c", "text": "Call the provider immediately"}, {"id": "d", "text": "Give a dose of diphenhydramine"}]'::jsonb, '["c"]', 'Red streaks on the skin indicate lymphangitis, an emergency that requires calling the provider immediately. Waiting four hours to recheck delays care for an emergency.'),
  ('derm_cellulitis', 44, 'The nurse receives phone messages from four clients. Which client should the nurse advise to go to the emergency department?', '[{"id": "a", "text": "A client with eczema reporting itching at night"}, {"id": "b", "text": "A client with seborrheic dermatitis reporting flaking"}, {"id": "c", "text": "A client with stasis dermatitis reporting leg swelling"}, {"id": "d", "text": "A client on antibiotics for cellulitis with growing redness"}]'::jsonb, '["d"]', 'Rapidly growing redness despite antibiotics is a reason to go to the ER. Itching, flaking, and leg swelling are expected dermatitis findings managed with routine care.'),
  ('derm_cellulitis', 45, 'Which medication does the nurse expect to be prescribed to reduce the redness and itching of atopic dermatitis?', '[{"id": "a", "text": "Topical betamethasone"}, {"id": "b", "text": "Oral dicloxacillin"}, {"id": "c", "text": "Intravenous vancomycin"}, {"id": "d", "text": "Oral doxycycline"}]'::jsonb, '["a"]', 'Topical steroids such as hydrocortisone and betamethasone reduce redness and itching in dermatitis. Dicloxacillin, vancomycin, and doxycycline are antibiotics for cellulitis, which dermatitis does not require.'),
  ('derm_cellulitis', 46, 'Which statement by a nursing student correctly defines dermatitis?', '[{"id": "a", "text": "\"It is a bacterial infection of the deeper skin layers.\""}, {"id": "b", "text": "\"It is skin inflammation from irritants, allergens, or other conditions.\""}, {"id": "c", "text": "\"It is a yeast infection that is easily spread by touch.\""}, {"id": "d", "text": "\"It is an infection that travels in red streaks to the heart.\""}]'::jsonb, '["b"]', 'Dermatitis is inflammation of the skin caused by irritants, allergens, or underlying conditions. A bacterial infection of the deeper skin layers describes cellulitis.'),
  ('derm_cellulitis', 47, 'A client with atopic dermatitis asks why daily moisturizer is important. Which explanation by the nurse is best?', '[{"id": "a", "text": "\"It kills bacteria living on the skin.\""}, {"id": "b", "text": "\"It treats yeast overgrowth on the skin.\""}, {"id": "c", "text": "\"It prevents dry, cracked skin.\""}, {"id": "d", "text": "\"It improves circulation to the legs.\""}]'::jsonb, '["c"]', 'Applying moisturizer prevents dry, cracked skin in dermatitis. Yeast overgrowth is treated with antifungal shampoo, and circulation is improved with elevation and compression stockings.'),
  ('derm_cellulitis', 48, 'A client has a red area on one arm. Which additional finding suggests cellulitis rather than dermatitis?', '[{"id": "a", "text": "Dry, scaly texture of the patches"}, {"id": "b", "text": "Itching that worsens with a new soap"}, {"id": "c", "text": "A family history of allergies and asthma"}, {"id": "d", "text": "Fever and chills with a spreading painful area"}]'::jsonb, '["d"]', 'Cellulitis causes a painful area that spreads quickly, with fever and chills if the infection spreads. Dry scaly patches, soap-related itching, and family allergy history point to dermatitis.'),
  ('derm_cellulitis', 49, 'A client with stasis dermatitis asks why compression stockings were prescribed. Which explanation by the nurse is correct?', '[{"id": "a", "text": "\"They improve the circulation in your legs.\""}, {"id": "b", "text": "\"They kill the yeast growing on your skin.\""}, {"id": "c", "text": "\"They stop itching caused by allergens.\""}, {"id": "d", "text": "\"They keep bacteria from entering a wound.\""}]'::jsonb, '["a"]', 'Compression stockings help stasis dermatitis by improving poor leg circulation. Yeast is treated with antifungal shampoo, not compression.'),
  ('derm_cellulitis', 50, 'A client with cellulitis of the forearm asks why the nurse keeps the arm propped on pillows. Which response by the nurse is correct?', '[{"id": "a", "text": "\"It keeps the antibiotic in your arm longer.\""}, {"id": "b", "text": "\"It helps reduce the swelling in your arm.\""}, {"id": "c", "text": "\"It prevents the rash from becoming itchy.\""}, {"id": "d", "text": "\"It keeps the infection from being contagious.\""}]'::jsonb, '["b"]', 'Elevating the affected area reduces swelling in cellulitis. Cellulitis is not contagious person-to-person, so elevation is not done to prevent spread to others.'),
  ('dvt_cellulitis', 1, 'A client 2 days after hip surgery has been mostly on bed rest. The client reports a dull, aching cramp in the right calf that worsens when standing, and the nurse notes unilateral pitting edema. Which condition does the nurse suspect?', '[{"id": "a", "text": "Deep vein thrombosis"}, {"id": "b", "text": "Cellulitis"}, {"id": "c", "text": "Pulmonary embolism"}, {"id": "d", "text": "Sepsis"}]'::jsonb, '["a"]', 'DVT causes dull, aching, cramping pain that worsens with walking or standing and unilateral leg swelling with pitting edema, and recent surgery and immobility are risk factors. Pulmonary embolism presents with respiratory symptoms such as sudden dyspnea and chest pain.'),
  ('dvt_cellulitis', 2, 'A client with diabetes reports an insect bite on the shin 3 days ago. The skin around the bite is bright red, hot, and shiny, and the client reports fever and chills. Which condition does the nurse suspect?', '[{"id": "a", "text": "Deep vein thrombosis"}, {"id": "b", "text": "Cellulitis"}, {"id": "c", "text": "Pulmonary embolism"}, {"id": "d", "text": "Venous stasis"}]'::jsonb, '["b"]', 'Cellulitis presents with bright red, hot, shiny skin plus fever, malaise, and chills, and diabetes and skin injury are risk factors. DVT skin usually looks normal or slightly dusky.'),
  ('dvt_cellulitis', 3, 'The nurse is supervising a UAP caring for a client with an acute DVT of the left calf. Which action by the UAP requires correction?', '[{"id": "a", "text": "Reporting new shortness of breath to the nurse"}, {"id": "b", "text": "Positioning the left leg on pillows"}, {"id": "c", "text": "Massaging the left calf to relieve cramping"}, {"id": "d", "text": "Checking with the nurse before ambulating"}]'::jsonb, '["c"]', 'Nursing priorities for DVT include avoiding massage of the affected leg. Elevation is part of DVT treatment, and reporting shortness of breath is appropriate monitoring for PE.'),
  ('dvt_cellulitis', 4, 'The nurse uses a skin marker to outline the reddened area on a client''s leg with cellulitis. What is the purpose of this action?', '[{"id": "a", "text": "To mark the site for a duplex ultrasound"}, {"id": "b", "text": "To locate the deep vein for heparin"}, {"id": "c", "text": "To show where massage must be avoided"}, {"id": "d", "text": "To monitor whether the infection spreads"}]'::jsonb, '["d"]', 'In cellulitis, the area is marked with a pen to monitor progression. Duplex ultrasound is the key assessment for DVT, not cellulitis.'),
  ('dvt_cellulitis', 5, 'A client being treated for a DVT suddenly reports chest pain and shortness of breath. What is the nurse''s priority action?', '[{"id": "a", "text": "Call the provider and prepare to give oxygen"}, {"id": "b", "text": "Massage the affected leg to improve blood flow"}, {"id": "c", "text": "Apply a warm compress to the affected calf"}, {"id": "d", "text": "Encourage the client to walk in the hallway"}]'::jsonb, '["a"]', 'Sudden chest pain and shortness of breath in a client with DVT suggest pulmonary embolism, an immediate emergency requiring the nurse to call the provider and prepare for oxygen. Massage of a DVT leg is to be avoided.'),
  ('dvt_cellulitis', 6, 'Which finding in a client with a known DVT should the nurse recognize as a possible sign of pulmonary embolism?', '[{"id": "a", "text": "Localized burning at a skin wound"}, {"id": "b", "text": "Coughing up blood"}, {"id": "c", "text": "Bright red, shiny skin on the calf"}, {"id": "d", "text": "Blisters with drainage on the shin"}]'::jsonb, '["b"]', 'Hemoptysis (coughing blood) is a warning sign of PE along with sudden chest pain, shortness of breath, and decreased oxygen saturation. Burning, bright red shiny skin, and blisters are cellulitis findings.'),
  ('dvt_cellulitis', 7, 'Which laboratory result does the nurse expect in a client with a suspected DVT?', '[{"id": "a", "text": "Decreased D-dimer"}, {"id": "b", "text": "Decreased WBC count"}, {"id": "c", "text": "Elevated D-dimer"}, {"id": "d", "text": "Positive blood cultures"}]'::jsonb, '["c"]', 'D-dimer is elevated in DVT, which is evaluated with D-dimer and venous Doppler ultrasound. Blood cultures are drawn for cellulitis when the client is febrile or severely ill.'),
  ('dvt_cellulitis', 8, 'Which laboratory finding supports a diagnosis of cellulitis?', '[{"id": "a", "text": "Elevated D-dimer"}, {"id": "b", "text": "Decreased WBC count"}, {"id": "c", "text": "Decreased oxygen saturation"}, {"id": "d", "text": "Elevated WBC count"}]'::jsonb, '["d"]', 'In cellulitis, the CBC shows elevated WBCs. An elevated D-dimer is the expected lab finding in DVT.'),
  ('dvt_cellulitis', 9, 'A client with cellulitis of the leg has a high fever and appears severely ill. Which diagnostic test does the nurse anticipate?', '[{"id": "a", "text": "Blood cultures"}, {"id": "b", "text": "D-dimer level"}, {"id": "c", "text": "Venous Doppler ultrasound"}, {"id": "d", "text": "Homan''s sign"}]'::jsonb, '["a"]', 'Blood cultures are obtained in cellulitis if the client is febrile or the infection is severe. D-dimer, Doppler ultrasound, and Homan''s sign relate to DVT assessment.'),
  ('dvt_cellulitis', 10, 'Which treatment does the nurse anticipate for a client newly diagnosed with a DVT?', '[{"id": "a", "text": "Oral antibiotics"}, {"id": "b", "text": "Heparin"}, {"id": "c", "text": "IV antibiotics"}, {"id": "d", "text": "Warm compresses"}]'::jsonb, '["b"]', 'DVT is treated with anticoagulation such as heparin or warfarin. Antibiotics and warm compresses are part of cellulitis treatment.'),
  ('dvt_cellulitis', 11, 'Which treatment plan does the nurse anticipate for a client with cellulitis of the forearm?', '[{"id": "a", "text": "Heparin and limb massage"}, {"id": "b", "text": "Warfarin and leg elevation"}, {"id": "c", "text": "Antibiotics and warm compresses"}, {"id": "d", "text": "Anticoagulants and ambulation"}]'::jsonb, '["c"]', 'Cellulitis is treated with oral or IV antibiotics, warm compresses, and pain control. Heparin and warfarin are anticoagulants used for DVT.'),
  ('dvt_cellulitis', 12, 'Which assessment does the nurse expect to be used to diagnose a suspected DVT?', '[{"id": "a", "text": "Blood cultures"}, {"id": "b", "text": "Pen marking of borders"}, {"id": "c", "text": "Homan''s sign alone"}, {"id": "d", "text": "Duplex ultrasound"}]'::jsonb, '["d"]', 'Duplex ultrasound is a key assessment for DVT, while Homan''s sign is unreliable. Pen marking of borders is used to track the spread of cellulitis.'),
  ('dvt_cellulitis', 13, 'A nursing student says, "A positive Homan''s sign confirms that the client has a DVT." Which response by the nurse is best?', '[{"id": "a", "text": "\"Homan''s sign is unreliable; ultrasound is used.\""}, {"id": "b", "text": "\"Correct; no further testing will be needed.\""}, {"id": "c", "text": "\"Homan''s sign is used to diagnose cellulitis.\""}, {"id": "d", "text": "\"Correct; the D-dimer will then be decreased.\""}]'::jsonb, '["a"]', 'Homan''s sign is unreliable, so DVT is assessed with duplex ultrasound. D-dimer is elevated, not decreased, in DVT.'),
  ('dvt_cellulitis', 14, 'Which factor is part of Virchow''s triad, the basis for DVT development?', '[{"id": "a", "text": "Skin break or wound"}, {"id": "b", "text": "Venous stasis"}, {"id": "c", "text": "Lymphedema"}, {"id": "d", "text": "Insect bite"}]'::jsonb, '["b"]', 'Virchow''s triad consists of venous stasis, hypercoagulability, and endothelial injury. A skin break or wound is how bacteria enter in cellulitis.'),
  ('dvt_cellulitis', 15, 'Which client does the nurse identify as at greatest risk for DVT?', '[{"id": "a", "text": "A client with an insect bite on the arm"}, {"id": "b", "text": "A client with lymphedema of one leg"}, {"id": "c", "text": "A client who smokes and takes oral contraceptives"}, {"id": "d", "text": "A client with diabetes and a small foot wound"}]'::jsonb, '["c"]', 'Smoking and oral contraceptives are DVT risk factors. Lymphedema, diabetes, and skin injury are risk factors for cellulitis.'),
  ('dvt_cellulitis', 16, 'Which client does the nurse identify as at greatest risk for cellulitis?', '[{"id": "a", "text": "A client on prolonged bed rest"}, {"id": "b", "text": "A client taking oral contraceptives"}, {"id": "c", "text": "A client with obesity who smokes"}, {"id": "d", "text": "A client with lymphedema and a skin tear"}]'::jsonb, '["d"]', 'Risk factors for cellulitis include diabetes, skin injury, immunosuppression, and lymphedema. Prolonged immobility, oral contraceptives, obesity, and smoking are DVT risk factors.'),
  ('dvt_cellulitis', 17, 'How does the nurse expect a client with cellulitis to describe the pain?', '[{"id": "a", "text": "Localized tenderness or burning"}, {"id": "b", "text": "Dull aching cramps when walking"}, {"id": "c", "text": "Cramping that worsens on standing"}, {"id": "d", "text": "Aching throughout the whole leg"}]'::jsonb, '["a"]', 'Cellulitis pain is localized tenderness or a burning sensation. Dull, aching, cramping pain that worsens with walking or standing is typical of DVT.'),
  ('dvt_cellulitis', 18, 'Which client statement about leg pain is most consistent with a DVT?', '[{"id": "a", "text": "\"It burns right around the scratch.\""}, {"id": "b", "text": "\"It''s a dull ache that''s worse when I walk.\""}, {"id": "c", "text": "\"It''s tender only where the skin is shiny.\""}, {"id": "d", "text": "\"It stings where the blisters are draining.\""}]'::jsonb, '["b"]', 'DVT pain is dull, aching, and cramping and worsens with walking or standing. Burning or localized tenderness at shiny, blistered skin points to cellulitis.'),
  ('dvt_cellulitis', 19, 'When inspecting the skin of a client with a suspected DVT, which finding does the nurse expect?', '[{"id": "a", "text": "Bright red, shiny, tight skin"}, {"id": "b", "text": "Blisters with drainage"}, {"id": "c", "text": "Normal or slightly dusky skin"}, {"id": "d", "text": "Hot skin around a wound"}]'::jsonb, '["c"]', 'With DVT, the skin may look normal or slightly dusky. Shiny, tight, red skin with possible blisters or drainage is characteristic of cellulitis.'),
  ('dvt_cellulitis', 20, 'Which skin finding does the nurse expect in a client with cellulitis of the leg?', '[{"id": "a", "text": "Normal color with pitting edema"}, {"id": "b", "text": "Slightly dusky skin over the calf"}, {"id": "c", "text": "Normal-appearing skin over the thigh"}, {"id": "d", "text": "Shiny, tight, red skin with blisters"}]'::jsonb, '["d"]', 'Cellulitis skin is shiny, tight, red, and warm with possible blisters or drainage. Normal or slightly dusky skin is the expected appearance in DVT.'),
  ('dvt_cellulitis', 21, 'Which systemic findings does the nurse expect to be common in a client with cellulitis?', '[{"id": "a", "text": "Fever, malaise, and chills"}, {"id": "b", "text": "Hemoptysis and chest pain"}, {"id": "c", "text": "Dyspnea and low oxygen saturation"}, {"id": "d", "text": "Sudden chest pain and coughing blood"}]'::jsonb, '["a"]', 'Fever, malaise, and chills are common systemic signs of cellulitis. Hemoptysis, chest pain, dyspnea, and decreased oxygen saturation are warning signs of PE from a DVT.'),
  ('dvt_cellulitis', 22, 'A client with a DVT is receiving anticoagulation and is stable. Which nursing action is appropriate?', '[{"id": "a", "text": "Massage the calf every 4 hours"}, {"id": "b", "text": "Encourage ambulation as prescribed"}, {"id": "c", "text": "Mark the calf border with a pen"}, {"id": "d", "text": "Keep the leg lowered off the bed"}]'::jsonb, '["b"]', 'DVT nursing priorities include encouraging ambulation if the client is stable. Massage is to be avoided, and pen marking is used to track cellulitis.'),
  ('dvt_cellulitis', 23, 'Which nursing intervention is appropriate for a client with cellulitis of the lower leg?', '[{"id": "a", "text": "Keep the leg in a dependent position"}, {"id": "b", "text": "Firmly massage the reddened area"}, {"id": "c", "text": "Elevate the affected limb"}, {"id": "d", "text": "Rub lotion deeply into the skin"}]'::jsonb, '["c"]', 'Cellulitis nursing priorities include monitoring spread of infection, elevating the limb, and educating on wound care. A dependent position is the opposite of elevation.'),
  ('dvt_cellulitis', 24, 'Which discharge teaching topic is a nursing priority for a client with cellulitis?', '[{"id": "a", "text": "Signs of pulmonary embolism"}, {"id": "b", "text": "Avoiding massage of the leg"}, {"id": "c", "text": "Taking warfarin every day"}, {"id": "d", "text": "Caring for the skin wound"}]'::jsonb, '["d"]', 'Educating on wound care is a cellulitis nursing priority. Monitoring for PE, avoiding massage, and anticoagulants such as warfarin relate to DVT.'),
  ('dvt_cellulitis', 25, 'A client with cellulitis of the arm has rapidly spreading redness and a high fever. The nurse recognizes that the client is at risk for which complication?', '[{"id": "a", "text": "Sepsis"}, {"id": "b", "text": "Pulmonary embolism"}, {"id": "c", "text": "Deep vein thrombosis"}, {"id": "d", "text": "Venous stasis"}]'::jsonb, '["a"]', 'Rapidly spreading redness with a high fever in cellulitis signals sepsis risk. Pulmonary embolism is the red-flag complication of DVT, signaled by sudden shortness of breath or chest pain.'),
  ('dvt_cellulitis', 26, 'During handoff, the nurse hears four reports about clients with leg swelling. Which report most suggests risk for DVT rather than cellulitis?', '[{"id": "a", "text": "\"Has an insect bite with redness.\""}, {"id": "b", "text": "\"Had surgery and is immobile in bed.\""}, {"id": "c", "text": "\"Has a wound with hot, red skin.\""}, {"id": "d", "text": "\"Has lymphedema with a skin tear.\""}]'::jsonb, '["b"]', 'Recent surgery and prolonged immobility are DVT risk factors. Insect bites, wounds, skin injury, and lymphedema point toward cellulitis.'),
  ('dvt_cellulitis', 27, 'Which statement best explains how cellulitis develops?', '[{"id": "a", "text": "A clot forms in a deep vein"}, {"id": "b", "text": "Blood pools from immobility"}, {"id": "c", "text": "Bacteria enter via a skin break"}, {"id": "d", "text": "The vein wall becomes injured"}]'::jsonb, '["c"]', 'Cellulitis is caused by Streptococcus or Staphylococcus entering through a skin break or wound. Clot formation, venous stasis, and endothelial injury relate to DVT.'),
  ('dvt_cellulitis', 28, 'A client has a red, hot, swollen area on one forearm surrounding a scratch. Which condition is most likely?', '[{"id": "a", "text": "Deep vein thrombosis"}, {"id": "b", "text": "Pulmonary embolism"}, {"id": "c", "text": "Venous stasis"}, {"id": "d", "text": "Cellulitis"}]'::jsonb, '["d"]', 'Cellulitis affects skin and soft tissue, usually a unilateral leg or arm, and follows a skin break. DVT occurs in the deep veins, commonly the calf or thigh.'),
  ('dvt_cellulitis', 29, 'Where does the nurse expect a DVT to most commonly occur?', '[{"id": "a", "text": "The deep veins of the calf or thigh"}, {"id": "b", "text": "The skin and soft tissue of the arm"}, {"id": "c", "text": "The subcutaneous tissue of the hand"}, {"id": "d", "text": "The skin surrounding a recent wound"}]'::jsonb, '["a"]', 'DVT commonly occurs in the deep veins of the calf or thigh. Skin and soft tissue involvement around a wound describes cellulitis.'),
  ('dvt_cellulitis', 30, 'Which description accurately defines cellulitis?', '[{"id": "a", "text": "A blood clot that forms in a deep leg vein"}, {"id": "b", "text": "An acute bacterial skin and subcutaneous infection"}, {"id": "c", "text": "Leg swelling that is caused by venous stasis"}, {"id": "d", "text": "A clot from the leg that has traveled to the lungs"}]'::jsonb, '["b"]', 'Cellulitis is an acute bacterial infection of the skin and subcutaneous tissue. A blood clot in a deep vein defines DVT.'),
  ('dvt_cellulitis', 31, 'The nurse is assessing a client with a red, swollen lower leg. Which finding most strongly suggests cellulitis rather than DVT?', '[{"id": "a", "text": "Unilateral pitting edema"}, {"id": "b", "text": "Dull ache worse with walking"}, {"id": "c", "text": "Bright red, hot, shiny skin"}, {"id": "d", "text": "Recent surgery and immobility"}]'::jsonb, '["c"]', 'Bright red, hot, shiny skin is characteristic of cellulitis. Unilateral pitting edema, a dull ache worse with walking, and recent surgery with immobility point to DVT.'),
  ('dvt_cellulitis', 32, 'A client with a swollen leg of uncertain cause suddenly becomes short of breath. Which condition should the nurse suspect?', '[{"id": "a", "text": "Worsening cellulitis"}, {"id": "b", "text": "Spreading skin infection"}, {"id": "c", "text": "Sepsis from cellulitis"}, {"id": "d", "text": "DVT with pulmonary embolism"}]'::jsonb, '["d"]', 'When in doubt, sudden respiratory symptoms point to DVT/PE. Spreading redness with fever, not sudden dyspnea, points to worsening cellulitis or sepsis.'),
  ('dvt_cellulitis', 33, 'A client on bed rest for a DVT has a sudden drop in oxygen saturation. How does the nurse interpret this finding?', '[{"id": "a", "text": "Possible pulmonary embolism"}, {"id": "b", "text": "Expected effect of immobility"}, {"id": "c", "text": "Sign of spreading cellulitis"}, {"id": "d", "text": "Normal response to heparin"}]'::jsonb, '["a"]', 'Decreased oxygen saturation, along with sudden chest pain, shortness of breath, and hemoptysis, is a warning sign of PE in a client with DVT. It is an emergency, not an expected finding.'),
  ('dvt_cellulitis', 34, 'What is the nurse''s priority monitoring focus for a client with an acute DVT?', '[{"id": "a", "text": "Spread of redness past pen marks"}, {"id": "b", "text": "Signs of pulmonary embolism"}, {"id": "c", "text": "Drainage from skin blisters"}, {"id": "d", "text": "Healing of the skin wound"}]'::jsonb, '["b"]', 'Monitoring for PE is the nursing priority in DVT. Tracking spread of redness, blister drainage, and wound healing are cellulitis priorities.'),
  ('dvt_cellulitis', 35, 'The nurse teaches a client with a DVT about home care. Which statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will report sudden shortness of breath.\""}, {"id": "b", "text": "\"I will take my anticoagulant as prescribed.\""}, {"id": "c", "text": "\"I will rub my calf when it starts to cramp.\""}, {"id": "d", "text": "\"I will call if I start coughing up blood.\""}]'::jsonb, '["c"]', 'Massage of a DVT leg is to be avoided, so rubbing the calf needs correction. Reporting shortness of breath or coughing up blood is correct because these are PE warning signs.'),
  ('dvt_cellulitis', 36, 'A client with a DVT asks what warfarin is for. Which response by the nurse is correct?', '[{"id": "a", "text": "\"It treats the bacteria in your leg.\""}, {"id": "b", "text": "\"It reduces the fever from infection.\""}, {"id": "c", "text": "\"It shrinks the redness on your skin.\""}, {"id": "d", "text": "\"It is an anticoagulant for the clot.\""}]'::jsonb, '["d"]', 'DVT is treated with anticoagulation such as heparin or warfarin. Bacterial infection is treated with antibiotics, which is cellulitis treatment.'),
  ('dvt_cellulitis', 37, 'Which client condition increases the risk of developing cellulitis?', '[{"id": "a", "text": "Immunosuppression"}, {"id": "b", "text": "Oral contraceptive use"}, {"id": "c", "text": "Cigarette smoking"}, {"id": "d", "text": "Obesity"}]'::jsonb, '["a"]', 'Immunosuppression is a cellulitis risk factor, along with diabetes, skin injury, and lymphedema. Oral contraceptives, smoking, and obesity are DVT risk factors.'),
  ('dvt_cellulitis', 38, 'Which risk factor in a client''s history is associated with DVT rather than cellulitis?', '[{"id": "a", "text": "Lymphedema"}, {"id": "b", "text": "Obesity"}, {"id": "c", "text": "Diabetes"}, {"id": "d", "text": "Skin injury"}]'::jsonb, '["b"]', 'Obesity is a DVT risk factor along with recent surgery or trauma, immobility, smoking, oral contraceptives, and cancer. Lymphedema, diabetes, and skin injury are cellulitis risk factors.'),
  ('dvt_cellulitis', 39, 'A client with cellulitis asks whether antibiotics are always given through an IV. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Only IV antibiotics treat cellulitis.\""}, {"id": "b", "text": "\"Antibiotics are not used for cellulitis.\""}, {"id": "c", "text": "\"Antibiotics may be given orally or IV.\""}, {"id": "d", "text": "\"Anticoagulants are used instead.\""}]'::jsonb, '["c"]', 'Cellulitis is treated with antibiotics given orally or IV. Anticoagulants are the treatment for DVT.'),
  ('dvt_cellulitis', 40, 'Which intervention is included in the treatment of a DVT?', '[{"id": "a", "text": "Warm compresses to the calf"}, {"id": "b", "text": "Massage of the affected calf"}, {"id": "c", "text": "Antibiotics taken by mouth"}, {"id": "d", "text": "Elevation of the affected leg"}]'::jsonb, '["d"]', 'DVT treatment includes anticoagulation and elevation. Warm compresses and antibiotics are cellulitis treatments, and massage is avoided in DVT.'),
  ('dvt_cellulitis', 41, 'Which nursing priority applies to cellulitis but not to DVT?', '[{"id": "a", "text": "Monitor spread of infection"}, {"id": "b", "text": "Monitor for pulmonary embolism"}, {"id": "c", "text": "Avoid massage of the limb"}, {"id": "d", "text": "Encourage ambulation if stable"}]'::jsonb, '["a"]', 'Monitoring the spread of infection is a cellulitis nursing priority. Monitoring for PE, avoiding massage, and encouraging ambulation if stable are DVT priorities.'),
  ('dvt_cellulitis', 42, 'The nurse outlined a client''s area of cellulitis in the morning. By evening, the redness extends well past the line and the client has a high fever. How does the nurse interpret these findings?', '[{"id": "a", "text": "Expected response to warm compresses"}, {"id": "b", "text": "Worsening cellulitis with sepsis risk"}, {"id": "c", "text": "Early signs of a pulmonary embolism"}, {"id": "d", "text": "Typical progression of a DVT"}]'::jsonb, '["b"]', 'Spreading redness with fever points to worsening cellulitis and sepsis risk. Pulmonary embolism is suggested by sudden respiratory symptoms, not spreading redness.'),
  ('dvt_cellulitis', 43, 'Which term describes the combination of venous stasis, hypercoagulability, and endothelial injury that leads to DVT?', '[{"id": "a", "text": "Homan''s sign"}, {"id": "b", "text": "Duplex ultrasound"}, {"id": "c", "text": "Virchow''s triad"}, {"id": "d", "text": "D-dimer"}]'::jsonb, '["c"]', 'Venous stasis, hypercoagulability, and endothelial injury make up Virchow''s triad, the etiology of DVT. Homan''s sign is an unreliable assessment, and duplex ultrasound and D-dimer are diagnostic tools.'),
  ('dvt_cellulitis', 44, 'The nurse is caring for four clients. Which client requires the nurse''s immediate attention?', '[{"id": "a", "text": "A client with cellulitis reporting burning at a wound"}, {"id": "b", "text": "A client with DVT reporting a dull ache in the calf"}, {"id": "c", "text": "A client with cellulitis whose skin is warm and shiny"}, {"id": "d", "text": "A client with DVT reporting sudden chest pain"}]'::jsonb, '["d"]', 'Sudden shortness of breath or chest pain in a client with DVT signals PE, an immediate emergency. Burning, a dull calf ache, and warm shiny skin are expected findings of each condition.'),
  ('dvt_cellulitis', 45, 'The provider has been notified that a client with a DVT has signs of a pulmonary embolism. Which interventions should the nurse prepare for?', '[{"id": "a", "text": "Oxygen, imaging, and anticoagulation"}, {"id": "b", "text": "Antibiotics, warm packs, and elevation"}, {"id": "c", "text": "Blood cultures and skin border marking"}, {"id": "d", "text": "Leg massage and early ambulation"}]'::jsonb, '["a"]', 'PE is an emergency; the nurse prepares for oxygen, imaging, and possible anticoagulation. Antibiotics, warm compresses, and blood cultures are cellulitis interventions.'),
  ('dvt_cellulitis', 46, 'A client reports redness of one leg. Which history finding points toward cellulitis rather than DVT?', '[{"id": "a", "text": "Recent cancer diagnosis"}, {"id": "b", "text": "A wound on the leg"}, {"id": "c", "text": "Long period of immobility"}, {"id": "d", "text": "Use of oral contraceptives"}]'::jsonb, '["b"]', 'Cellulitis is caused by Streptococcus or Staphylococcus entering through a skin break or wound. Cancer, immobility, and oral contraceptives are DVT risk factors.'),
  ('dvt_cellulitis', 47, 'Which swelling pattern does the nurse expect in a client with a DVT?', '[{"id": "a", "text": "Bilateral swelling of both legs"}, {"id": "b", "text": "Swelling limited to a skin wound"}, {"id": "c", "text": "Unilateral leg swelling with pitting edema"}, {"id": "d", "text": "Swelling of both arms and hands"}]'::jsonb, '["c"]', 'DVT causes unilateral leg swelling with pitting edema. Swelling localized around a skin wound fits cellulitis.'),
  ('dvt_cellulitis', 48, 'Which statement best describes a deep vein thrombosis?', '[{"id": "a", "text": "A bacterial infection of the skin"}, {"id": "b", "text": "An infection entering through a wound"}, {"id": "c", "text": "A reaction to an insect bite"}, {"id": "d", "text": "A blood clot in a deep vein"}]'::jsonb, '["d"]', 'DVT is a blood clot in a deep vein, usually in the lower extremities. A bacterial skin infection entering through a wound or bite describes cellulitis.'),
  ('dvt_cellulitis', 49, 'Which statement by a client with cellulitis shows understanding of how spread of the infection is tracked?', '[{"id": "a", "text": "\"The line drawn on my skin shows if the red area grows.\""}, {"id": "b", "text": "\"The ultrasound of my leg will show if the infection spreads.\""}, {"id": "c", "text": "\"My D-dimer level will show how far the infection spreads.\""}, {"id": "d", "text": "\"Squeezing my calf will show whether the infection spreads.\""}]'::jsonb, '["a"]', 'In cellulitis, the area is marked with a pen to monitor progression. Ultrasound and D-dimer are used to evaluate DVT, not the spread of cellulitis.'),
  ('dvt_cellulitis', 50, 'A postoperative client with unilateral leg swelling asks why a D-dimer test was drawn. The nurse explains that the test helps evaluate for which condition?', '[{"id": "a", "text": "Cellulitis"}, {"id": "b", "text": "Deep vein thrombosis"}, {"id": "c", "text": "Sepsis"}, {"id": "d", "text": "Wound infection"}]'::jsonb, '["b"]', 'An elevated D-dimer, along with venous Doppler ultrasound, is used to evaluate DVT. Cellulitis is evaluated with a CBC and blood cultures if febrile or severe.'),
  ('periorbital', 1, 'A 4-year-old child has a red, swollen, warm eyelid two days after an insect bite near the eye. The child moves the eye without pain and has normal vision. Which condition does the nurse suspect?', '[{"id": "a", "text": "Periorbital cellulitis"}, {"id": "b", "text": "Orbital cellulitis"}, {"id": "c", "text": "Orbital abscess"}, {"id": "d", "text": "Ethmoid sinusitis"}]'::jsonb, '["a"]', 'Eyelid swelling, redness, and warmth with no pain on eye movement and normal vision are classic signs of periorbital (preseptal) cellulitis. Orbital cellulitis causes pain with eye movement and possible vision changes.'),
  ('periorbital', 2, 'A child admitted with periorbital cellulitis now reports pain when looking to the side. How does the nurse interpret this finding?', '[{"id": "a", "text": "An expected finding of periorbital cellulitis"}, {"id": "b", "text": "Possible progression to orbital cellulitis"}, {"id": "c", "text": "A sign that the antibiotics are working"}, {"id": "d", "text": "A normal response to warm compresses"}]'::jsonb, '["b"]', 'Pain with eye movement suggests deeper infection behind the septum and possible orbital cellulitis. Periorbital cellulitis has no pain with eye movement.'),
  ('periorbital', 3, 'Which assessment finding indicates orbital cellulitis rather than periorbital cellulitis?', '[{"id": "a", "text": "Eyelid redness"}, {"id": "b", "text": "Eyelid warmth"}, {"id": "c", "text": "Bulging of the eye"}, {"id": "d", "text": "Eyelid tenderness"}]'::jsonb, '["c"]', 'Proptosis (a bulging eye) is present in orbital cellulitis and absent in periorbital cellulitis. Eyelid redness, warmth, and tenderness are expected in periorbital cellulitis.'),
  ('periorbital', 4, 'A child with periorbital cellulitis tells the nurse, "I see two of everything now." How does the nurse interpret this report?', '[{"id": "a", "text": "Expected with eyelid swelling"}, {"id": "b", "text": "Side effect of oral antibiotics"}, {"id": "c", "text": "Sign the infection is resolving"}, {"id": "d", "text": "Possible progression to orbital cellulitis"}]'::jsonb, '["d"]', 'Double vision (diplopia) is a sign of progression to orbital cellulitis. Periorbital cellulitis causes no vision changes, so diplopia is not expected.'),
  ('periorbital', 5, 'The nurse checks visual acuity each shift for a child with periorbital cellulitis. Which result should be reported to the provider?', '[{"id": "a", "text": "Visual acuity decreased from baseline"}, {"id": "b", "text": "Visual acuity unchanged from admission"}, {"id": "c", "text": "Pupils that respond normally to light"}, {"id": "d", "text": "Full eye movement without any pain"}]'::jsonb, '["a"]', 'Decreased visual acuity is a sign of progression to orbital cellulitis. Normal pupil responses and painless eye movements are expected in periorbital cellulitis.'),
  ('periorbital', 6, 'Which finding does the nurse expect when assessing a child with uncomplicated periorbital cellulitis?', '[{"id": "a", "text": "Painful eye movements"}, {"id": "b", "text": "Normal pupil responses"}, {"id": "c", "text": "Bulging of the eye"}, {"id": "d", "text": "Double vision"}]'::jsonb, '["b"]', 'In periorbital cellulitis, eye movements and pupil responses are normal. Painful eye movements, proptosis, and diplopia suggest progression to orbital cellulitis.'),
  ('periorbital', 7, 'A nursing student asks where the infection is located in periorbital cellulitis. Which response by the nurse is correct?', '[{"id": "a", "text": "\"Behind the orbital septum, within the orbit.\""}, {"id": "b", "text": "\"Only inside the ethmoid sinus.\""}, {"id": "c", "text": "\"In front of the orbital septum.\""}, {"id": "d", "text": "\"Inside the eyeball itself.\""}]'::jsonb, '["c"]', 'Periorbital cellulitis is anterior to (in front of) the orbital septum. Infection behind the septum, within the orbit, is orbital cellulitis.'),
  ('periorbital', 8, 'A parent asks what the orbital septum is. Which description by the nurse is accurate?', '[{"id": "a", "text": "An air-filled sinus beside the eye"}, {"id": "b", "text": "An oil gland along the eyelid edge"}, {"id": "c", "text": "A tear duct draining into the nose"}, {"id": "d", "text": "A tissue barrier in front of deeper eye structures"}]'::jsonb, '["d"]', 'The orbital septum is the connective tissue barrier separating the front of the eye from the deeper orbital structures. Ethmoid sinusitis is a cause of infection, not the septum itself.'),
  ('periorbital', 9, 'Where is the infection located in orbital cellulitis?', '[{"id": "a", "text": "Behind the septum, within the orbit"}, {"id": "b", "text": "In front of the septum, in the eyelid"}, {"id": "c", "text": "In the surface skin of the cheek"}, {"id": "d", "text": "In a stye along the eyelid margin"}]'::jsonb, '["a"]', 'Orbital cellulitis is posterior to (behind) the septum, within the orbit. Infection in front of the septum involving the eyelid is periorbital cellulitis.'),
  ('periorbital', 10, 'A child is diagnosed with orbital cellulitis. Which plan of care does the nurse anticipate?', '[{"id": "a", "text": "Oral antibiotics at home"}, {"id": "b", "text": "IV antibiotics and hospitalization"}, {"id": "c", "text": "Warm compresses without antibiotics"}, {"id": "d", "text": "Outpatient follow-up in one week"}]'::jsonb, '["b"]', 'Orbital cellulitis is an emergency requiring IV antibiotics and hospitalization. Outpatient care with oral antibiotics is possible only for mild periorbital cellulitis.'),
  ('periorbital', 11, 'A school-age child has mild periorbital cellulitis with normal vision and painless eye movements. Which prescription does the nurse anticipate?', '[{"id": "a", "text": "IV vancomycin in the hospital"}, {"id": "b", "text": "Immediate surgical drainage"}, {"id": "c", "text": "Oral amoxicillin-clavulanate"}, {"id": "d", "text": "IV ceftriaxone in the hospital"}]'::jsonb, '["c"]', 'Mild periorbital cellulitis is treated on an outpatient basis with oral antibiotics such as amoxicillin-clavulanate. IV ceftriaxone or vancomycin in the hospital is for moderate/severe cases or children under 1 year.'),
  ('periorbital', 12, 'An 8-month-old infant is diagnosed with periorbital cellulitis. Which treatment does the nurse anticipate?', '[{"id": "a", "text": "Oral antibiotics at home"}, {"id": "b", "text": "Warm compresses alone"}, {"id": "c", "text": "Ophthalmology referral alone"}, {"id": "d", "text": "IV antibiotics in the hospital"}]'::jsonb, '["d"]', 'Children younger than 1 year with periorbital cellulitis receive IV antibiotics in the hospital. Oral outpatient antibiotics are for mild cases in older children.'),
  ('periorbital', 13, 'Which medications does the nurse expect to administer to a child hospitalized with moderate periorbital cellulitis?', '[{"id": "a", "text": "IV ceftriaxone or vancomycin"}, {"id": "b", "text": "Oral amoxicillin-clavulanate"}, {"id": "c", "text": "Warm compresses without drugs"}, {"id": "d", "text": "Oral antibiotics only if febrile"}]'::jsonb, '["a"]', 'Moderate/severe periorbital cellulitis is treated with IV antibiotics such as ceftriaxone or vancomycin in the hospital. Oral amoxicillin-clavulanate is for mild outpatient cases.'),
  ('periorbital', 14, 'A child with periorbital cellulitis shows no improvement despite antibiotic therapy. Which intervention does the nurse anticipate?', '[{"id": "a", "text": "Switching to warm compresses alone"}, {"id": "b", "text": "Surgical drainage or ophthalmology referral"}, {"id": "c", "text": "Discharge home on oral antibiotics"}, {"id": "d", "text": "Stopping all antibiotic therapy"}]'::jsonb, '["b"]', 'With complications or no improvement, the child may need surgical drainage or an ophthalmology referral. Stopping antibiotics would go against the need for prompt antibiotic treatment.'),
  ('periorbital', 15, 'When does the nurse expect a CT scan of the orbits with contrast to be ordered for a child with periorbital cellulitis?', '[{"id": "a", "text": "For every child with eyelid redness"}, {"id": "b", "text": "Only after the child is discharged"}, {"id": "c", "text": "When the diagnosis is uncertain or worsening"}, {"id": "d", "text": "Before any antibiotic dose is given"}]'::jsonb, '["c"]', 'A CT scan of the orbits with contrast is ordered if the diagnosis is uncertain or the condition is worsening. The physical exam is the primary way to distinguish periorbital from orbital cellulitis.'),
  ('periorbital', 16, 'A parent asks why a CT scan was ordered for a child with worsening eyelid swelling. Which response by the nurse is correct?', '[{"id": "a", "text": "\"It measures the white blood cell count.\""}, {"id": "b", "text": "\"It checks for bacteria in the blood.\""}, {"id": "c", "text": "\"It replaces the need for antibiotics.\""}, {"id": "d", "text": "\"It rules out a deeper infection or abscess.\""}]'::jsonb, '["d"]', 'A CT scan of the orbits rules out orbital cellulitis or abscess. The WBC count comes from a CBC, and bacteria in the blood are checked with blood cultures.'),
  ('periorbital', 17, 'Which CBC finding is consistent with the bacterial infection of periorbital cellulitis?', '[{"id": "a", "text": "Elevated WBC count"}, {"id": "b", "text": "Decreased WBC count"}, {"id": "c", "text": "Decreased red cell count"}, {"id": "d", "text": "Decreased platelet count"}]'::jsonb, '["a"]', 'A CBC in periorbital cellulitis may show an elevated WBC count, reflecting bacterial infection. A decreased WBC count is not the expected finding.'),
  ('periorbital', 18, 'For which child with periorbital cellulitis does the nurse anticipate an order for blood cultures?', '[{"id": "a", "text": "A child who is afebrile and playful"}, {"id": "b", "text": "A child who is febrile and toxic-appearing"}, {"id": "c", "text": "A child with mild eyelid redness only"}, {"id": "d", "text": "A child with a stye that is healing"}]'::jsonb, '["b"]', 'Blood cultures are obtained if the child is febrile or toxic-appearing. A well-appearing, afebrile child with mild findings does not meet this criterion.'),
  ('periorbital', 19, 'A child is diagnosed with periorbital cellulitis. Which recent condition in the child''s history is a common cause of this infection?', '[{"id": "a", "text": "Fractured forearm"}, {"id": "b", "text": "Ankle sprain"}, {"id": "c", "text": "Ethmoid sinusitis"}, {"id": "d", "text": "Urinary infection"}]'::jsonb, '["c"]', 'Periorbital cellulitis is often caused by sinusitis, especially of the ethmoid sinus. The other conditions are not listed causes.'),
  ('periorbital', 20, 'Which history finding in a child with eyelid swelling supports a diagnosis of periorbital cellulitis?', '[{"id": "a", "text": "A recent fall onto the knee"}, {"id": "b", "text": "A recent sprain of the wrist"}, {"id": "c", "text": "A recent cut on the foot"}, {"id": "d", "text": "An insect bite on the eyelid"}]'::jsonb, '["d"]', 'Eyelid trauma such as an insect bite, scratch, or injury is a common source of periorbital cellulitis. Injuries far from the eye are not listed causes.'),
  ('periorbital', 21, 'A parent reports that a child had a stye on the eyelid last week and now has a red, swollen, warm eyelid with normal vision. How does the nurse interpret the stye?', '[{"id": "a", "text": "A possible source of the infection"}, {"id": "b", "text": "An unrelated eyelid finding"}, {"id": "c", "text": "A sign of orbital involvement"}, {"id": "d", "text": "A sign the infection has resolved"}]'::jsonb, '["a"]', 'Chalazion or stye infection is a cause of periorbital cellulitis. Orbital involvement is suggested by pain with eye movement, proptosis, or vision changes, which are absent here.'),
  ('periorbital', 22, 'Which recent illness can spread to cause periorbital cellulitis in a child?', '[{"id": "a", "text": "Urinary tract infection"}, {"id": "b", "text": "Upper respiratory tract infection"}, {"id": "c", "text": "Gastrointestinal virus"}, {"id": "d", "text": "Middle ear fluid buildup"}]'::jsonb, '["b"]', 'Periorbital cellulitis can result from spread of an upper respiratory tract infection. The other illnesses are not listed causes.'),
  ('periorbital', 23, 'Which child is at increased risk for periorbital cellulitis caused by Haemophilus influenzae?', '[{"id": "a", "text": "A fully vaccinated child"}, {"id": "b", "text": "A child older than 10 years"}, {"id": "c", "text": "An unvaccinated child"}, {"id": "d", "text": "A child with a healed stye"}]'::jsonb, '["c"]', 'Haemophilus influenzae is a common organism in unvaccinated children. A fully vaccinated child does not carry this specific risk.'),
  ('periorbital', 24, 'A parent asks why periorbital cellulitis must be treated right away. Which response by the nurse is best?', '[{"id": "a", "text": "\"It usually requires emergency surgery.\""}, {"id": "b", "text": "\"It never responds to oral antibiotics.\""}, {"id": "c", "text": "\"It always causes some loss of vision.\""}, {"id": "d", "text": "\"It can progress to orbital cellulitis.\""}]'::jsonb, '["d"]', 'Orbital cellulitis can result from progression of periorbital cellulitis, so prompt treatment is key. Mild periorbital cellulitis responds to oral antibiotics, and surgical drainage is reserved for complications or no improvement.'),
  ('periorbital', 25, 'Which nursing intervention is appropriate for a child with periorbital cellulitis?', '[{"id": "a", "text": "Apply warm compresses to the eyelid if approved"}, {"id": "b", "text": "Hold antibiotic doses until the fever resolves"}, {"id": "c", "text": "Delay antibiotics until CT results return"}, {"id": "d", "text": "Give antibiotics only when the eyelid hurts"}]'::jsonb, '["a"]', 'Warm compresses may be applied to the eyelid if approved by the provider. Antibiotics should be given on time as prescribed rather than held or delayed.'),
  ('periorbital', 26, 'An IV antibiotic is due now for a hospitalized child with periorbital cellulitis, but the child has just fallen asleep. Which action by the nurse is best?', '[{"id": "a", "text": "Skip this dose and give the next one"}, {"id": "b", "text": "Give the antibiotic on time as prescribed"}, {"id": "c", "text": "Wait until the child wakes up naturally"}, {"id": "d", "text": "Combine it with the next scheduled dose"}]'::jsonb, '["b"]', 'Antibiotics are to be administered on time, oral or IV, as prescribed. Skipping, delaying, or combining doses goes against this priority.'),
  ('periorbital', 27, 'Which routine assessment is a nursing priority for a child admitted with periorbital cellulitis?', '[{"id": "a", "text": "Daily weight only"}, {"id": "b", "text": "Hearing screening"}, {"id": "c", "text": "Temperature and vital signs"}, {"id": "d", "text": "Hourly blood glucose"}]'::jsonb, '["c"]', 'Nursing care includes monitoring temperature and vital signs regularly. The other assessments are not listed priorities for this condition.'),
  ('periorbital', 28, 'Which instruction is most important for parents of a child discharged with periorbital cellulitis?', '[{"id": "a", "text": "\"Expect the eye to hurt when it moves.\""}, {"id": "b", "text": "\"Stop the antibiotic once swelling improves.\""}, {"id": "c", "text": "\"Return only if fever lasts over a week.\""}, {"id": "d", "text": "\"Call if the eye is hard to open or moves painfully.\""}]'::jsonb, '["d"]', 'Parents should call the provider if the eye becomes difficult to open or moves painfully because this may mean progression to orbital cellulitis. Painful eye movement is not expected in periorbital cellulitis.'),
  ('periorbital', 29, 'The nurse teaches parents about home care for a child with periorbital cellulitis. Which parent statement indicates a need for further teaching?', '[{"id": "a", "text": "\"We''ll stop the antibiotic when the eyelid looks better.\""}, {"id": "b", "text": "\"We''ll give every dose of the antibiotic as prescribed.\""}, {"id": "c", "text": "\"We''ll call right away if our child has trouble seeing.\""}, {"id": "d", "text": "\"We''ll come back if the eye starts to bulge outward.\""}]'::jsonb, '["a"]', 'Medication compliance at home is encouraged to prevent complications, so stopping early needs correction. Reporting vision trouble or a bulging eye is correct because these suggest orbital cellulitis.'),
  ('periorbital', 30, 'Which discharge instruction should the nurse give caregivers of a child with periorbital cellulitis?', '[{"id": "a", "text": "\"Symptoms always worsen before they improve.\""}, {"id": "b", "text": "\"Return for care if the symptoms get worse.\""}, {"id": "c", "text": "\"No follow-up is needed after discharge.\""}, {"id": "d", "text": "\"Spreading swelling is an expected change.\""}]'::jsonb, '["b"]', 'Caregivers are educated to return if symptoms worsen. Worsening symptoms may mean progression to orbital cellulitis, so they are not expected.'),
  ('periorbital', 31, 'In which age group is periorbital cellulitis most common?', '[{"id": "a", "text": "Adults over 65 years"}, {"id": "b", "text": "Adolescents 15 to 19 years"}, {"id": "c", "text": "Children under 10 years"}, {"id": "d", "text": "Adults 20 to 40 years"}]'::jsonb, '["c"]', 'Periorbital cellulitis is most common in children under 10. The other age groups fall outside this range.'),
  ('periorbital', 32, 'A parent asks whether their child will lose vision from periorbital cellulitis. Which response by the nurse is best?', '[{"id": "a", "text": "\"Vision loss is expected but will be temporary.\""}, {"id": "b", "text": "\"Vision loss happens in most affected children.\""}, {"id": "c", "text": "\"Vision is affected only when the fever is high.\""}, {"id": "d", "text": "\"Vision is usually safe with prompt treatment.\""}]'::jsonb, '["d"]', 'Periorbital cellulitis is serious but usually not vision-threatening if treated promptly. Vision changes are absent in periorbital cellulitis and are possible only in orbital cellulitis.'),
  ('periorbital', 33, 'Which statement correctly compares periorbital and orbital cellulitis?', '[{"id": "a", "text": "\"Periorbital is more common and less dangerous.\""}, {"id": "b", "text": "\"Orbital is more common and less dangerous.\""}, {"id": "c", "text": "\"Both always require hospitalization.\""}, {"id": "d", "text": "\"Both always cause changes in vision.\""}]'::jsonb, '["a"]', 'Periorbital cellulitis is more common and less dangerous, while orbital cellulitis is rare but more severe and sight-threatening. Outpatient care is possible for periorbital cellulitis.'),
  ('periorbital', 34, 'A child has mild periorbital cellulitis with normal eye findings. Which statement about the level of urgency is accurate?', '[{"id": "a", "text": "\"It is an emergency needing hospitalization.\""}, {"id": "b", "text": "\"It is urgent, but outpatient care is possible.\""}, {"id": "c", "text": "\"It needs no treatment because it is mild.\""}, {"id": "d", "text": "\"It requires surgery before any antibiotics.\""}]'::jsonb, '["b"]', 'Periorbital cellulitis is urgent, but outpatient care is possible. Emergency hospitalization with IV antibiotics describes orbital cellulitis.'),
  ('periorbital', 35, 'A caregiver calls about a child being treated at home for periorbital cellulitis. Which report is a red-flag symptom that must be acted on?', '[{"id": "a", "text": "The eyelid remains slightly pink"}, {"id": "b", "text": "The child is eating normally"}, {"id": "c", "text": "The child reports vision loss"}, {"id": "d", "text": "The eyelid swelling is decreasing"}]'::jsonb, '["c"]', 'Caregivers are taught that eye pain, vision loss, and fever are red-flag symptoms. Decreasing swelling and normal eating do not indicate worsening.'),
  ('periorbital', 36, 'Which assessment finding does the nurse expect in a child with periorbital cellulitis?', '[{"id": "a", "text": "Painful eye movements"}, {"id": "b", "text": "Bulging of the eye"}, {"id": "c", "text": "Decreased visual acuity"}, {"id": "d", "text": "Eyelid redness and tenderness"}]'::jsonb, '["d"]', 'Periorbital cellulitis causes eyelid swelling, redness, and tenderness. Painful eye movements, a bulging eye, and decreased visual acuity are signs of progression to orbital cellulitis.'),
  ('periorbital', 37, 'A toddler scratched an eyelid while playing. Two days later the eyelid is red, swollen, and warm, with normal eye movements. Which explanation of the cause is accurate?', '[{"id": "a", "text": "\"The scratch let bacteria infect the eyelid.\""}, {"id": "b", "text": "\"The scratch caused bleeding behind the eye.\""}, {"id": "c", "text": "\"The scratch caused an allergic eyelid rash.\""}, {"id": "d", "text": "\"The scratch damaged the orbital bones.\""}]'::jsonb, '["a"]', 'Periorbital cellulitis is a bacterial infection, often from eyelid trauma such as a scratch. Normal eye movements indicate the infection has not extended behind the septum.'),
  ('periorbital', 38, 'The nurse is caring for four children with periorbital cellulitis. Which child should the nurse assess first?', '[{"id": "a", "text": "A child with eyelid warmth and redness"}, {"id": "b", "text": "A child with a newly bulging eye"}, {"id": "c", "text": "A child with mild eyelid tenderness"}, {"id": "d", "text": "A child with a recent stye history"}]'::jsonb, '["b"]', 'A bulging eye (proptosis) is a sign of progression to orbital cellulitis, an emergency. Eyelid warmth, redness, and tenderness are expected periorbital findings.'),
  ('periorbital', 39, 'Which assessment best helps the nurse differentiate periorbital cellulitis from orbital cellulitis?', '[{"id": "a", "text": "Measuring the eyelid swelling"}, {"id": "b", "text": "Inspecting for a stye"}, {"id": "c", "text": "Checking for pain with eye movement"}, {"id": "d", "text": "Asking about insect bites"}]'::jsonb, '["c"]', 'Periorbital cellulitis is differentiated from orbital cellulitis by checking for eye movement pain and vision. Eyelid swelling, styes, and insect bites occur with periorbital cellulitis and do not distinguish the two.'),
  ('periorbital', 40, 'Periorbital cellulitis is also known by which term?', '[{"id": "a", "text": "Orbital cellulitis"}, {"id": "b", "text": "Chalazion"}, {"id": "c", "text": "Ethmoid sinusitis"}, {"id": "d", "text": "Preseptal cellulitis"}]'::jsonb, '["d"]', 'Periorbital cellulitis is also called preseptal cellulitis. Orbital cellulitis is a different, deeper infection behind the septum.'),
  ('periorbital', 41, 'Which parent statement shows understanding of what periorbital cellulitis is?', '[{"id": "a", "text": "\"It''s an infection of the eyelid and nearby skin.\""}, {"id": "b", "text": "\"It''s an infection deep inside the eye socket.\""}, {"id": "c", "text": "\"It''s an infection that always harms vision.\""}, {"id": "d", "text": "\"It''s an infection that needs no antibiotics.\""}]'::jsonb, '["a"]', 'Periorbital cellulitis is an infection of the eyelid and surrounding skin tissues in front of the orbital septum. Infection within the orbit describes orbital cellulitis.'),
  ('periorbital', 42, 'Which finding is possible in orbital cellulitis but absent in periorbital cellulitis?', '[{"id": "a", "text": "Eyelid redness"}, {"id": "b", "text": "Vision changes"}, {"id": "c", "text": "Eyelid warmth"}, {"id": "d", "text": "Eyelid swelling"}]'::jsonb, '["b"]', 'Vision changes are possible in orbital cellulitis, while periorbital cellulitis has no vision changes. Eyelid redness, warmth, and swelling occur in periorbital cellulitis.'),
  ('periorbital', 43, 'What is the primary method used to distinguish periorbital cellulitis from orbital cellulitis?', '[{"id": "a", "text": "Blood cultures"}, {"id": "b", "text": "Complete blood count"}, {"id": "c", "text": "Physical examination"}, {"id": "d", "text": "Response to compresses"}]'::jsonb, '["c"]', 'Diagnosis begins with the physical exam to distinguish periorbital from orbital cellulitis. Blood cultures and CBC assess infection but do not determine its depth.'),
  ('periorbital', 44, 'Which cause is shared by both periorbital and orbital cellulitis?', '[{"id": "a", "text": "Insect bite"}, {"id": "b", "text": "Chalazion"}, {"id": "c", "text": "Vaccination"}, {"id": "d", "text": "Sinusitis"}]'::jsonb, '["d"]', 'Sinusitis is a common cause of both periorbital cellulitis (with skin trauma) and orbital cellulitis (with progression from periorbital cellulitis). Insect bites and chalazion are listed as causes of periorbital cellulitis only.'),
  ('periorbital', 45, 'Which statement by the nurse reflects a key principle in managing periorbital cellulitis?', '[{"id": "a", "text": "\"Prompt antibiotic treatment is key.\""}, {"id": "b", "text": "\"Antibiotics should wait for CT results.\""}, {"id": "c", "text": "\"Compresses replace antibiotics if mild.\""}, {"id": "d", "text": "\"Antibiotics are given only for fever.\""}]'::jsonb, '["a"]', 'Prompt antibiotic treatment is key in periorbital cellulitis. Even mild cases are treated with oral antibiotics, so compresses do not replace them.'),
  ('periorbital', 46, 'The charge nurse observes a new nurse caring for a child receiving IV antibiotics for periorbital cellulitis. Which action requires correction?', '[{"id": "a", "text": "Checking eye movement for pain"}, {"id": "b", "text": "Delaying the IV antibiotic two hours"}, {"id": "c", "text": "Monitoring the child''s temperature"}, {"id": "d", "text": "Asking the child about double vision"}]'::jsonb, '["b"]', 'Antibiotics are to be administered on time as prescribed, so a two-hour delay requires correction. Checking eye movement pain, temperature, and double vision are appropriate assessments.'),
  ('periorbital', 47, 'Which parent statement indicates understanding of discharge teaching for periorbital cellulitis?', '[{"id": "a", "text": "\"I''ll stop the medicine when the redness fades.\""}, {"id": "b", "text": "\"Pain when the eye moves is normal for now.\""}, {"id": "c", "text": "\"I''ll give every dose until it is finished.\""}, {"id": "d", "text": "\"We won''t need to return if it gets worse.\""}]'::jsonb, '["c"]', 'Medication compliance at home is encouraged to prevent complications. Pain with eye movement is a red flag for orbital cellulitis, not a normal finding.'),
  ('periorbital', 48, 'Which child with periorbital cellulitis does the nurse expect to be admitted for IV antibiotics?', '[{"id": "a", "text": "A 5-year-old with mild eyelid swelling"}, {"id": "b", "text": "A 7-year-old with mild redness and normal vision"}, {"id": "c", "text": "A 3-year-old with mild eyelid warmth"}, {"id": "d", "text": "A 4-year-old with a severe infection"}]'::jsonb, '["d"]', 'Moderate/severe periorbital cellulitis, or any case in a child under 1 year, is treated with IV antibiotics in the hospital. Mild cases in older children can be treated with oral antibiotics as outpatients.'),
  ('periorbital', 49, 'A blood culture from a child with periorbital cellulitis grows Staphylococcus aureus. How does the nurse interpret this result?', '[{"id": "a", "text": "A common organism for this infection"}, {"id": "b", "text": "An unusual organism for this infection"}, {"id": "c", "text": "Proof the infection is orbital"}, {"id": "d", "text": "An organism seen only if unvaccinated"}]'::jsonb, '["a"]', 'Staphylococcus aureus is a common organism in periorbital cellulitis, along with Streptococcus pneumoniae. Only Haemophilus influenzae is linked specifically to unvaccinated children.'),
  ('periorbital', 50, 'A child has eyelid swelling and redness, a mild fever, normal vision, and painless eye movements. How does the nurse interpret these findings?', '[{"id": "a", "text": "Progression to orbital cellulitis"}, {"id": "b", "text": "Consistent with periorbital cellulitis"}, {"id": "c", "text": "Need for emergency surgical drainage"}, {"id": "d", "text": "Evidence of an orbital abscess"}]'::jsonb, '["b"]', 'In periorbital cellulitis, fever may be present while vision and eye movements remain normal. Orbital cellulitis is suggested by pain with eye movement, proptosis, or vision changes, which are absent.'),
  ('pressure', 1, 'While turning an immobile client, the nurse finds a red area over the sacrum. The skin is intact and does not turn white when pressed. How should the nurse document this finding?', '[{"id": "a", "text": "Stage 1 pressure injury"}, {"id": "b", "text": "Stage 2 pressure injury"}, {"id": "c", "text": "Deep tissue injury"}, {"id": "d", "text": "Unstageable pressure injury"}]'::jsonb, '["a"]', 'Red, intact skin that is non-blanchable is a Stage 1 pressure ulcer. A deep tissue injury is a purple/maroon area under intact skin, not red.'),
  ('pressure', 2, 'A bedridden client has a Stage 1 pressure injury on the right heel. Which nursing action is the priority?', '[{"id": "a", "text": "Apply an alginate dressing to the heel"}, {"id": "b", "text": "Pack the area loosely with gauze"}, {"id": "c", "text": "Relieve pressure from the right heel"}, {"id": "d", "text": "Arrange surgical debridement of the heel"}]'::jsonb, '["c"]', 'For a Stage 1 pressure injury, pressure relief/offloading is the priority. Alginate is for heavy drainage, and packing is for deep cavities, neither of which applies to intact skin.'),
  ('pressure', 3, 'The nurse assesses the coccyx of a client who is incontinent and finds a shallow open wound with partial-thickness skin loss. No fat is visible. Which stage does the nurse document?', '[{"id": "a", "text": "Stage 1"}, {"id": "b", "text": "Stage 2"}, {"id": "c", "text": "Stage 3"}, {"id": "d", "text": "Stage 4"}]'::jsonb, '["b"]', 'A shallow open wound or blister with partial-thickness skin loss is a Stage 2 pressure ulcer. Stage 3 is full-thickness loss with the fat layer exposed.'),
  ('pressure', 4, 'An older adult in long-term care has a deep, crater-like sacral wound with the fat layer visible and a small amount of yellow slough at one edge. No muscle, tendon, or bone is visible. Which stage is this?', '[{"id": "a", "text": "Stage 2"}, {"id": "b", "text": "Stage 4"}, {"id": "c", "text": "Unstageable"}, {"id": "d", "text": "Stage 3"}]'::jsonb, '["d"]', 'A deep crater with full-thickness skin loss and the fat layer exposed, possibly with yellow slough, is Stage 3. Stage 4 requires exposed muscle, tendon, or bone.'),
  ('pressure', 5, 'During a dressing change, the nurse observes exposed bone at the base of a client''s sacral pressure injury. How should the nurse stage this wound?', '[{"id": "a", "text": "Stage 2"}, {"id": "b", "text": "Stage 3"}, {"id": "c", "text": "Stage 4"}, {"id": "d", "text": "Deep tissue injury"}]'::jsonb, '["c"]', 'Full-thickness loss with exposed muscle, tendon, or bone is a Stage 4 pressure ulcer. Stage 3 exposes the fat layer but not bone.'),
  ('pressure', 6, 'A client''s buttock pressure injury is completely covered with yellow slough, and the nurse cannot see the wound base. How should the nurse classify the wound?', '[{"id": "a", "text": "Unstageable"}, {"id": "b", "text": "Stage 2"}, {"id": "c", "text": "Stage 3"}, {"id": "d", "text": "Deep tissue injury"}]'::jsonb, '["a"]', 'A wound covered with slough or eschar so that depth cannot be determined is unstageable. It cannot be called Stage 3 until the depth can be seen.'),
  ('pressure', 7, 'The nurse finds a purple area on a client''s heel that looks like a deep bruise. The skin is intact, and the client says it is very painful. Which type of pressure injury is this?', '[{"id": "a", "text": "Stage 1 pressure injury"}, {"id": "b", "text": "Deep tissue injury"}, {"id": "c", "text": "Stage 2 pressure injury"}, {"id": "d", "text": "Unstageable pressure injury"}]'::jsonb, '["b"]', 'A purple/maroon area of intact skin that looks like a deep bruise and is very painful is a deep tissue injury. A Stage 1 injury is red and non-blanchable, not purple.'),
  ('pressure', 8, 'A client''s sacral pressure injury is covered with slough, so the depth cannot be seen. What is needed before the nurse can accurately stage this wound?', '[{"id": "a", "text": "A transparent film dressing"}, {"id": "b", "text": "Repositioning every 2 hours"}, {"id": "c", "text": "A high-protein diet for a week"}, {"id": "d", "text": "Debridement of the wound"}]'::jsonb, '["d"]', 'An unstageable wound covered with slough or eschar needs debridement so its depth can be assessed. Repositioning and protein support healing but do not reveal the wound depth.'),
  ('pressure', 9, 'A client has a heel pressure injury covered with stable, dry, intact eschar. Which prescription should the nurse question?', '[{"id": "a", "text": "Offload pressure from both heels"}, {"id": "b", "text": "Debride the heel eschar today"}, {"id": "c", "text": "Assess skin over bony areas daily"}, {"id": "d", "text": "Reposition the client every 2 hours"}]'::jsonb, '["b"]', 'Stable, dry, intact heel eschar should not be debrided. Offloading, daily skin assessment, and repositioning every 2 hours are appropriate.'),
  ('pressure', 10, 'A family member sees a maroon, bruise-like area on the client''s intact hip skin and says, ''At least the skin isn''t broken, so it''s not serious.'' Which response by the nurse is best?', '[{"id": "a", "text": "You''re right; intact skin means it is minor."}, {"id": "b", "text": "It is a Stage 1 injury that will fade soon."}, {"id": "c", "text": "There is damage underneath that can open up."}, {"id": "d", "text": "It will need debridement before it heals."}]'::jsonb, '["c"]', 'A deep tissue injury is damage under intact skin that can worsen to an open wound. Debridement is needed to stage wounds covered with slough or eschar, not intact skin.'),
  ('pressure', 11, 'The nurse is comparing a Stage 1 pressure injury with a deep tissue injury. Which finding is seen only in the deep tissue injury?', '[{"id": "a", "text": "Purple or maroon intact skin"}, {"id": "b", "text": "Skin that remains intact"}, {"id": "c", "text": "Pain reported at the site"}, {"id": "d", "text": "Location over a bony area"}]'::jsonb, '["a"]', 'A deep tissue injury appears as a purple/maroon area like a deep bruise, while a Stage 1 injury is red and non-blanchable. Both have intact skin and can be painful, so those findings do not distinguish them.'),
  ('pressure', 12, 'The nurse is reviewing assigned clients. Which client is at the highest risk for developing a pressure ulcer?', '[{"id": "a", "text": "A walking adult admitted for a minor cough"}, {"id": "b", "text": "A teen who sits briefly between classes"}, {"id": "c", "text": "An active adult with a healed ankle sprain"}, {"id": "d", "text": "A bedridden adult with a spinal cord injury"}]'::jsonb, '["d"]', 'Pressure ulcers are common in bedridden, immobile clients, and spinal cord injuries increase risk. The other clients are mobile and change position.'),
  ('pressure', 13, 'A client in a semi-upright position keeps sliding down in bed, so the skin over the sacrum stays in place while the body moves downward. Which risk factor does the nurse identify?', '[{"id": "a", "text": "Friction"}, {"id": "b", "text": "Shearing"}, {"id": "c", "text": "Moisture"}, {"id": "d", "text": "Poor nutrition"}]'::jsonb, '["b"]', 'Shearing occurs when the skin slides one direction while the body moves another, such as sliding down in bed. Friction is rubbing against a surface.'),
  ('pressure', 14, 'An older adult is frequently incontinent of urine and stool. After cleaning the skin, which intervention helps protect it from breakdown?', '[{"id": "a", "text": "Apply an alginate dressing to the buttocks"}, {"id": "b", "text": "Leave the skin damp to keep it soft"}, {"id": "c", "text": "Apply a zinc oxide barrier cream"}, {"id": "d", "text": "Pack the gluteal fold with dry gauze"}]'::jsonb, '["c"]', 'Barrier creams such as zinc oxide or petroleum jelly protect skin against urine and stool. Leaving skin damp is wrong because moisture weakens skin.'),
  ('pressure', 15, 'The nurse is performing a skin assessment on an immobile client. Which areas should the nurse inspect most closely for pressure injury?', '[{"id": "a", "text": "Sacrum, coccyx, and heels"}, {"id": "b", "text": "Abdomen and anterior thighs"}, {"id": "c", "text": "Palms and inner forearms"}, {"id": "d", "text": "Front of the shins and chest"}]'::jsonb, '["a"]', 'Pressure ulcers commonly form over bony prominences such as the sacrum, coccyx, and heels. The abdomen, palms, and anterior thighs are not listed as common locations.'),
  ('pressure', 16, 'The nurse is supervising unlicensed assistive personnel (UAP) caring for an immobile client. Which action by the UAP requires correction?', '[{"id": "a", "text": "Places pillows to support the bony areas"}, {"id": "b", "text": "Keeps the client''s skin clean and dry"}, {"id": "c", "text": "Reports a new red area on the hip"}, {"id": "d", "text": "Repositions the client every 4 hours"}]'::jsonb, '["d"]', 'Clients should be repositioned every 2 hours to relieve pressure, so every 4 hours is too long. Using pillows and keeping skin clean and dry are correct prevention measures.'),
  ('pressure', 17, 'A client on prolonged bed rest is at high risk for pressure injury. Which intervention best reduces pressure on the skin?', '[{"id": "a", "text": "Keep the client in one position to rest"}, {"id": "b", "text": "Place the client on a low-air-loss mattress"}, {"id": "c", "text": "Restrict fluids to keep the skin dry"}, {"id": "d", "text": "Reposition the client once per shift"}]'::jsonb, '["b"]', 'Special mattresses such as low-air-loss or foam reduce pressure. Staying in one position causes prolonged pressure, and poor hydration weakens skin.'),
  ('pressure', 18, 'The nurse is writing a prevention plan for an immobile client. Which skin assessment entry is appropriate?', '[{"id": "a", "text": "Inspect the skin weekly during the bath"}, {"id": "b", "text": "Inspect the skin only if pain is reported"}, {"id": "c", "text": "Inspect the skin daily, especially bony areas"}, {"id": "d", "text": "Inspect the skin only when the client is turned"}]'::jsonb, '["c"]', 'Skin should be assessed daily, especially over bony areas. Waiting for pain or a weekly check could miss early, non-blanchable redness.'),
  ('pressure', 19, 'A client with a Stage 3 pressure injury is choosing meals. Which selection best supports wound healing?', '[{"id": "a", "text": "Chicken, eggs, and a glass of milk"}, {"id": "b", "text": "Clear broth, gelatin, and tea"}, {"id": "c", "text": "Green salad with vinegar dressing"}, {"id": "d", "text": "Plain crackers and black coffee"}]'::jsonb, '["a"]', 'A high-protein, high-calorie diet helps heal skin; chicken, eggs, and milk supply protein. The other choices are low in protein.'),
  ('pressure', 20, 'The nurse teaches a family member how to prevent pressure injuries in a client who is cared for at home. Which statement indicates a need for further teaching?', '[{"id": "a", "text": "I will turn him every 2 hours."}, {"id": "b", "text": "I''ll put pillows under his bony areas."}, {"id": "c", "text": "I''ll offer him protein-rich foods."}, {"id": "d", "text": "I''ll keep his skin damp with wet cloths."}]'::jsonb, '["d"]', 'Skin should be kept clean and dry because moisture causes breakdown. Turning every 2 hours, padding bony areas, and offering protein are correct.'),
  ('pressure', 21, 'A client with a Stage 3 pressure ulcer has diabetes, a low protein intake, and vitamin deficiencies. Which outcome does the nurse anticipate?', '[{"id": "a", "text": "Healing within a few days"}, {"id": "b", "text": "Delayed wound healing"}, {"id": "c", "text": "Conversion to a Stage 1 injury"}, {"id": "d", "text": "Healing without wound care"}]'::jsonb, '["b"]', 'Poor nutrition (low protein, vitamin deficiencies) slows healing, and diabetes increases the risk of non-healing ulcers. Rapid healing is not expected with these factors.'),
  ('pressure', 22, 'A client has a shallow Stage 2 pressure injury on the coccyx with light drainage. Which dressing does the nurse expect to apply?', '[{"id": "a", "text": "Alginate dressing"}, {"id": "b", "text": "Gauze packing"}, {"id": "c", "text": "Hydrocolloid dressing"}, {"id": "d", "text": "Wound VAC therapy"}]'::jsonb, '["c"]', 'Hydrocolloid is used for shallow wounds with light-to-moderate drainage and maintains a moist environment. Alginate is for heavy drainage, and packing is for deep cavities.'),
  ('pressure', 23, 'The nurse is selecting wounds that are appropriate for a transparent film dressing. Which wound is the best match?', '[{"id": "a", "text": "Superficial wound with no drainage"}, {"id": "b", "text": "Deep cavity with heavy drainage"}, {"id": "c", "text": "Infected wound with purulent drainage"}, {"id": "d", "text": "Deep tunnel that requires packing"}]'::jsonb, '["a"]', 'Transparent film is best for superficial wounds with little or no drainage. It does not absorb much drainage and should be avoided with heavily draining or infected wounds.'),
  ('pressure', 24, 'The charge nurse observes a nurse caring for pressure injuries. Which action requires correction?', '[{"id": "a", "text": "Applying hydrogel to a dry wound bed"}, {"id": "b", "text": "Packing a deep cavity loosely with gauze"}, {"id": "c", "text": "Using zinc oxide on skin near the wound"}, {"id": "d", "text": "Applying transparent film to a heavily draining wound"}]'::jsonb, '["d"]', 'Transparent film does not absorb much drainage and should be avoided with heavily draining wounds. Hydrogel for dry wounds and loose packing of cavities are correct.'),
  ('pressure', 25, 'A client''s Stage 3 pressure injury has a dry wound bed with dry slough. Which dressing should the nurse anticipate?', '[{"id": "a", "text": "Alginate dressing"}, {"id": "b", "text": "Hydrogel dressing"}, {"id": "c", "text": "Hydrofiber dressing"}, {"id": "d", "text": "Transparent film"}]'::jsonb, '["b"]', 'Hydrogel adds moisture and is used for dry wounds or wounds with dry slough/eschar. Alginate and hydrofiber absorb drainage and should not be used on dry wounds.'),
  ('pressure', 26, 'The nurse reviews wound care orders for a client with a dry Stage 3 pressure injury. Which order should the nurse question?', '[{"id": "a", "text": "Reposition the client every 2 hours"}, {"id": "b", "text": "Apply hydrogel to the wound bed"}, {"id": "c", "text": "Apply an alginate dressing daily"}, {"id": "d", "text": "Encourage a high-protein diet"}]'::jsonb, '["c"]', 'Alginate should never be used on a dry wound because it is highly absorbent. Hydrogel is the dressing for a dry wound.'),
  ('pressure', 27, 'A client has a Stage 4 sacral pressure injury with heavy drainage that saturates the dressing. Which dressing is most appropriate?', '[{"id": "a", "text": "Alginate dressing"}, {"id": "b", "text": "Transparent film"}, {"id": "c", "text": "Hydrogel dressing"}, {"id": "d", "text": "Hydrocolloid dressing"}]'::jsonb, '["a"]', 'Heavy drainage calls for alginate or hydrofiber. Hydrogel adds moisture and should not be used on heavily draining wounds, and hydrocolloid is usually avoided with heavy drainage.'),
  ('pressure', 28, 'The nurse applies a hydrofiber dressing to a deep pressure injury with moderate-to-heavy drainage. Which effect does the nurse expect from this dressing?', '[{"id": "a", "text": "It adds moisture to a dry wound bed"}, {"id": "b", "text": "It seals out drainage without absorbing it"}, {"id": "c", "text": "It uses suction to pull out drainage"}, {"id": "d", "text": "It absorbs drainage and forms a gel"}]'::jsonb, '["d"]', 'Hydrofiber absorbs drainage and forms a gel and is used for moderate-to-heavy drainage. Adding moisture describes hydrogel, and suction describes a wound VAC.'),
  ('pressure', 29, 'The nurse is placing an alginate dressing into a deep, heavily draining pressure injury. What should the nurse anticipate needing?', '[{"id": "a", "text": "A hydrogel layer to add moisture"}, {"id": "b", "text": "A secondary dressing over the alginate"}, {"id": "c", "text": "Tight packing to fill the cavity"}, {"id": "d", "text": "Debridement of a stable heel eschar"}]'::jsonb, '["b"]', 'Alginate is highly absorbent and often needs a secondary dressing. Tight packing is never appropriate, and hydrogel is not used on heavily draining wounds.'),
  ('pressure', 30, 'A client has a deep Stage 4 pressure injury with tunneling. Which technique should the nurse use when packing the wound with gauze?', '[{"id": "a", "text": "Pack the gauze as tightly as possible"}, {"id": "b", "text": "Leave the tunnels open and unfilled"}, {"id": "c", "text": "Pack the gauze loosely into the cavity"}, {"id": "d", "text": "Cover the tunnels with transparent film"}]'::jsonb, '["c"]', 'Gauze packing is used for deep wounds, tunnels, and cavities and should be packed loosely, never tightly. Transparent film is for superficial wounds with little drainage.'),
  ('pressure', 31, 'The nurse observes a new graduate caring for a client with a deep cavity pressure ulcer. Which action requires correction?', '[{"id": "a", "text": "Firmly packing gauze to fill the cavity"}, {"id": "b", "text": "Turning the client every 2 hours"}, {"id": "c", "text": "Checking the wound for signs of infection"}, {"id": "d", "text": "Protecting nearby skin with barrier film"}]'::jsonb, '["a"]', 'A pressure ulcer should never be tightly packed; deep cavities are packed loosely. Turning every 2 hours, checking for infection, and protecting surrounding skin are correct.'),
  ('pressure', 32, 'A nurse plans to remove plain dry gauze from a deep pressure injury. Which risk should the nurse keep in mind?', '[{"id": "a", "text": "The gauze may cause a deep tissue injury"}, {"id": "b", "text": "The gauze may add too much moisture"}, {"id": "c", "text": "The gauze may break the suction seal"}, {"id": "d", "text": "The gauze may damage healthy tissue"}]'::jsonb, '["d"]', 'Plain dry gauze may damage healthy tissue when it is removed. It does not add moisture; hydrogel is the dressing that adds moisture.'),
  ('pressure', 33, 'A client''s Stage 3 pressure injury shows a high bacterial burden with redness, warmth, and pus. Which type of dressing does the nurse anticipate?', '[{"id": "a", "text": "Transparent film dressing"}, {"id": "b", "text": "Silver-containing dressing"}, {"id": "c", "text": "Hydrogel dressing"}, {"id": "d", "text": "Plain dry gauze"}]'::jsonb, '["b"]', 'Antimicrobial dressings, such as silver-containing dressings, are used for infected wounds or a high bacterial burden. Transparent film should be avoided with infected wounds.'),
  ('pressure', 34, 'The nurse is teaching a nursing student about pressure injury dressings. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "Hydrogel is a good choice for a dry wound."}, {"id": "b", "text": "Deep cavities should be packed loosely."}, {"id": "c", "text": "Every pressure injury needs a silver dressing."}, {"id": "d", "text": "Alginate should not go on a dry wound."}]'::jsonb, '["c"]', 'Antimicrobial dressings such as silver are for infected wounds or high bacterial burden and are not needed for every pressure injury. The other statements are correct.'),
  ('pressure', 35, 'A client with a deep Stage 4 pressure injury has negative-pressure wound therapy (wound VAC). Which assessment is most important for the nurse to include?', '[{"id": "a", "text": "Check the seal and suction system"}, {"id": "b", "text": "Check that the gauze is packed tightly"}, {"id": "c", "text": "Check that the wound bed is kept dry"}, {"id": "d", "text": "Check that the film is left off the wound"}]'::jsonb, '["a"]', 'With a wound VAC, the nurse checks the seal and suction system. Tight packing is never appropriate for a pressure ulcer.'),
  ('pressure', 36, 'The wound care team is considering negative-pressure wound therapy. Which client is the most appropriate candidate?', '[{"id": "a", "text": "A client with a Stage 1 sacral injury"}, {"id": "b", "text": "A client with a dry Stage 2 blister"}, {"id": "c", "text": "A client with stable, dry heel eschar"}, {"id": "d", "text": "A client with a deep Stage 4 injury"}]'::jsonb, '["d"]', 'Negative-pressure wound therapy is used for selected deep Stage 3 to 4 pressure injuries. A Stage 1 injury needs pressure relief, and stable, dry heel eschar is left alone.'),
  ('pressure', 37, 'A client with a hydrocolloid dressing on a Stage 2 pressure injury asks how the dressing helps. Which response by the nurse is accurate?', '[{"id": "a", "text": "It uses suction to pull out the drainage."}, {"id": "b", "text": "It keeps the wound moist and helps loosen dead tissue."}, {"id": "c", "text": "It kills bacteria with silver in the dressing."}, {"id": "d", "text": "It is packed into the wound to fill the space."}]'::jsonb, '["b"]', 'Hydrocolloid maintains a moist environment and promotes autolytic debridement. Suction describes a wound VAC, and silver describes an antimicrobial dressing.'),
  ('pressure', 38, 'A client with a sacral pressure injury is incontinent of stool. The nurse applies a barrier film to the skin around the wound. What is the purpose of this action?', '[{"id": "a", "text": "To absorb heavy wound drainage"}, {"id": "b", "text": "To add moisture to a dry wound bed"}, {"id": "c", "text": "To prevent moisture-related skin damage"}, {"id": "d", "text": "To loosen slough in the wound bed"}]'::jsonb, '["c"]', 'Skin barrier products such as zinc oxide and barrier film protect skin around the wound, especially with incontinence, and prevent moisture-associated skin damage. Absorbing heavy drainage describes alginate or hydrofiber.'),
  ('pressure', 39, 'The nurse assesses a client''s Stage 3 pressure injury. Which findings suggest the wound is infected?', '[{"id": "a", "text": "Redness, swelling, warmth, and pus"}, {"id": "b", "text": "Purple, intact skin over the heel"}, {"id": "c", "text": "Red, intact skin that does not blanch"}, {"id": "d", "text": "Shallow, open blister with no drainage"}]'::jsonb, '["a"]', 'Redness, swelling, warmth, and pus indicate infection. Purple intact skin describes a deep tissue injury, and red non-blanchable skin describes Stage 1.'),
  ('pressure', 40, 'A client with a Stage 4 pressure ulcer now has a fever and chills, and the wound looks worse than yesterday. Which action should the nurse take?', '[{"id": "a", "text": "Switch to a hydrogel dressing"}, {"id": "b", "text": "Reassess the wound in 4 hours"}, {"id": "c", "text": "Increase the protein in the diet"}, {"id": "d", "text": "Notify the provider promptly"}]'::jsonb, '["d"]', 'Fever with a worsening ulcer suggests possible sepsis, which is life-threatening, so the provider should be called. Changing the dressing or diet does not address possible sepsis.'),
  ('pressure', 41, 'A client has a Stage 4 sacral pressure ulcer with bone visible in the wound bed. Which complication is this client specifically at risk for?', '[{"id": "a", "text": "Deep tissue injury"}, {"id": "b", "text": "Osteomyelitis"}, {"id": "c", "text": "Shearing injury"}, {"id": "d", "text": "Moisture damage"}]'::jsonb, '["b"]', 'Bone infection (osteomyelitis) can develop in Stage 4 ulcers, where bone is exposed. Deep tissue injury is damage under intact skin, not a complication of an open Stage 4 wound.'),
  ('pressure', 42, 'A client with a painful deep pressure ulcer refuses to move in bed because of the pain. Which complication should the nurse anticipate?', '[{"id": "a", "text": "Deep tissue injury"}, {"id": "b", "text": "Moisture-associated skin damage"}, {"id": "c", "text": "Contractures"}, {"id": "d", "text": "Osteomyelitis"}]'::jsonb, '["c"]', 'Pain from deep ulcers can limit movement, and contractures can develop if patients don''t move. Osteomyelitis is a bone infection in Stage 4 ulcers, not a result of immobility.'),
  ('pressure', 43, 'The nurse is supervising UAP caring for a client who is incontinent of urine. Which action by the UAP requires correction?', '[{"id": "a", "text": "Leaving a wet brief on until the next round"}, {"id": "b", "text": "Cleaning the skin right after incontinence"}, {"id": "c", "text": "Applying the prescribed barrier cream"}, {"id": "d", "text": "Turning the client every 2 hours"}]'::jsonb, '["a"]', 'Moisture from sweat, urine, or stool weakens skin, so a wet brief should not be left in place. Cleaning promptly, applying barrier cream, and turning every 2 hours are correct.'),
  ('pressure', 44, 'A client has a large Stage 4 pressure ulcer with exposed muscle. Which treatment does the nurse anticipate the provider may recommend?', '[{"id": "a", "text": "Transparent film alone"}, {"id": "b", "text": "Turning every 2 hours only"}, {"id": "c", "text": "Hydrogel to keep it moist"}, {"id": "d", "text": "Skin grafting of the ulcer"}]'::jsonb, '["d"]', 'Large Stage 3 and 4 ulcers may need skin grafting, and Stage 4 may need surgery. Transparent film is for superficial wounds with little or no drainage.'),
  ('pressure', 45, 'A family member of a client with a Stage 3 pressure ulcer makes these statements after dressing teaching. Which statement indicates a need for further teaching?', '[{"id": "a", "text": "I''ll still keep her off the wound area."}, {"id": "b", "text": "The dressing means she can be turned less."}, {"id": "c", "text": "I''ll keep turning her every 2 hours."}, {"id": "d", "text": "I''ll watch for fever or more drainage."}]'::jsonb, '["b"]', 'Pressure relief and repositioning are essential regardless of the dressing used. Keeping the client off the wound and turning every 2 hours are correct.'),
  ('pressure', 46, 'The family of a newly bedridden client asks why the nurse insists on frequent position changes. Which explanation is most accurate?', '[{"id": "a", "text": "Turning keeps the skin from getting too dry."}, {"id": "b", "text": "Turning helps the body absorb more protein."}, {"id": "c", "text": "Constant pressure cuts blood flow to the skin."}, {"id": "d", "text": "Turning prevents bacteria from reaching the skin."}]'::jsonb, '["c"]', 'Prolonged pressure reduces blood flow, leading to skin breakdown and open wounds; repositioning relieves that pressure. The other explanations are not why repositioning prevents pressure ulcers.'),
  ('pressure', 47, 'The nurse is caring for four clients with pressure injuries. Which client should the nurse see first?', '[{"id": "a", "text": "Stage 4 ulcer, new fever, and confusion"}, {"id": "b", "text": "Stage 1 sacral redness found on turning"}, {"id": "c", "text": "Stage 2 blister due for a dressing change"}, {"id": "d", "text": "Stable, dry eschar on the left heel"}]'::jsonb, '["a"]', 'Fever and confusion with a pressure ulcer suggest sepsis, which is life-threatening. The Stage 1, Stage 2, and stable heel eschar clients are not showing signs of a life-threatening complication.'),
  ('pressure', 48, 'The nurse teaches a caregiver about a client''s Stage 2 pressure injury on the coccyx. Which statement indicates a need for further teaching?', '[{"id": "a", "text": "I''ll keep the area clean."}, {"id": "b", "text": "I''ll help him change positions."}, {"id": "c", "text": "A moist dressing helps it heal."}, {"id": "d", "text": "I''ll leave it uncovered to dry out."}]'::jsonb, '["d"]', 'Stage 2 wounds are treated with moisture-retaining dressings, such as hydrocolloid or transparent film, because moist dressings help them heal. Keeping the area clean and repositioning are correct.'),
  ('pressure', 49, 'The nurse is reassessing a client''s Stage 2 sacral pressure injury. Which new finding indicates the wound has progressed to Stage 3?', '[{"id": "a", "text": "The skin is red and does not blanch"}, {"id": "b", "text": "The fat layer is now visible"}, {"id": "c", "text": "A purple, bruise-like area appears"}, {"id": "d", "text": "A clear blister forms on the skin"}]'::jsonb, '["b"]', 'Stage 3 is full-thickness skin loss with the fat layer exposed. A blister is consistent with Stage 2, and red non-blanchable skin is Stage 1.'),
  ('pressure', 50, 'A client asks how the wound VAC on a deep Stage 4 pressure injury will help the wound heal. Which response by the nurse is accurate?', '[{"id": "a", "text": "It adds moisture to a dry wound bed."}, {"id": "b", "text": "It kills bacteria with silver ions."}, {"id": "c", "text": "It removes drainage and promotes new tissue."}, {"id": "d", "text": "It protects nearby skin from urine."}]'::jsonb, '["c"]', 'Negative-pressure wound therapy uses suction to remove drainage and promote granulation tissue. Adding moisture to a dry wound describes hydrogel.')
  ) AS v(source_key, display_order, stem, options, correct_answer, rationale)
  JOIN _burns_seed_map m USING (source_key)
 CROSS JOIN _burns_seed_config c;

DO $$
DECLARE
  v_bad text;
BEGIN
  SELECT string_agg(format('%s=%s', m.source_key, coalesce(n.cnt, 0)), ', ')
    INTO v_bad
    FROM _burns_seed_map m
    LEFT JOIN (SELECT category, count(*) AS cnt FROM test_questions GROUP BY category) n
      ON n.category = m.category
   WHERE coalesce(n.cnt, 0) <> 50;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'Burns-Skin seed post-check failed (expected 50 per topic): %', v_bad;
  END IF;
END $$;

COMMIT;
